fn merge_deferred_visual_targets(
    text_targets: &mut HashSet<String>,
    visual_targets: HashSet<String>,
) {
    text_targets.extend(visual_targets);
}

fn can_use_targeted_deferred_rebuild(
    dirty: Dirty,
    text_requires_full: bool,
    visual_requires_full: bool,
    has_targets: bool,
) -> bool {
    matches!(dirty, Dirty::Text) && !text_requires_full && !visual_requires_full && has_targets
}

fn coalesce_runtime_command_batch(commands: &mut Vec<Command>) {
    if commands.len() < 2 {
        return;
    }
    let mut seen_scatter_updates = HashMap::new();
    let mut seen_scatter_actor_updates = HashMap::new();
    let mut seen_scatter_scalar_bars = HashMap::new();
    let mut seen_line_plot_updates = HashMap::new();
    let structurally_replaced_ids: HashSet<String> = commands
        .iter()
        .filter_map(|command| match command {
            Command::ReplaceNode { id, .. } | Command::ReplaceChildren { id, .. } => {
                Some(id.clone())
            }
            _ => None,
        })
        .collect();
    let mut seen_extension_display_lists = HashSet::new();
    let mut seen_icon_theme = false;
    let mut seen_theme = false;
    let mut seen_stylesheet_mutations = HashSet::new();
    let mut seen_stylesheet_clears = HashSet::new();
    let mut seen_props = HashSet::new();
    let mut filtered = Vec::with_capacity(commands.len());
    while let Some(command) = commands.pop() {
        let keep = match &command {
            Command::SetProp { id, prop, .. } => seen_props.insert((id.clone(), prop.clone())),
            Command::SetScatterPointsPacked {
                id,
                fit,
                coalesce: true,
                ..
            } => {
                if let Some(index) = seen_scatter_updates.get(id).copied() {
                    if *fit {
                        if let Command::SetScatterPointsPacked { fit: kept_fit, .. } =
                            &mut filtered[index]
                        {
                            *kept_fit = true;
                        }
                    }
                    false
                } else {
                    seen_scatter_updates.insert(id.clone(), filtered.len());
                    true
                }
            }
            Command::SetLinePlotDataPacked {
                id,
                series,
                fit,
                coalesce: true,
                ..
            } => {
                let key = (id.clone(), series.clone());
                if let Some(index) = seen_line_plot_updates.get(&key).copied() {
                    if *fit {
                        if let Command::SetLinePlotDataPacked { fit: kept_fit, .. } =
                            &mut filtered[index]
                        {
                            *kept_fit = true;
                        }
                    }
                    false
                } else {
                    seen_line_plot_updates.insert(key, filtered.len());
                    true
                }
            }
            Command::UpdateScatterActorPacked { id, actor_id, .. } => {
                let key = (id.clone(), *actor_id);
                if seen_scatter_actor_updates.contains_key(&key) {
                    false
                } else {
                    seen_scatter_actor_updates.insert(key, filtered.len());
                    true
                }
            }
            Command::SetScatterScalarBar { id, .. } => {
                if seen_scatter_scalar_bars.contains_key(id) {
                    false
                } else {
                    seen_scatter_scalar_bars.insert(id.clone(), filtered.len());
                    true
                }
            }
            Command::UpdateExtensionDisplayList { id, .. } => {
                structurally_replaced_ids.contains(id)
                    || seen_extension_display_lists.insert(id.clone())
            }
            Command::SetIconTheme { .. } => {
                let keep = !seen_icon_theme;
                seen_icon_theme = true;
                keep
            }
            Command::SetTheme { .. } => {
                let keep = !seen_theme;
                seen_theme = true;
                keep
            }
            Command::SetStylesheet { origin, id, .. } => {
                !seen_stylesheet_clears.contains(origin)
                    && seen_stylesheet_mutations.insert((*origin, id.clone()))
            }
            Command::RemoveStylesheet { origin, id } => {
                !seen_stylesheet_clears.contains(origin)
                    && seen_stylesheet_mutations.insert((*origin, Some(id.clone())))
            }
            Command::ClearStylesheets { origin } => seen_stylesheet_clears.insert(*origin),
            _ => true,
        };
        if keep {
            filtered.push(command);
        }
    }
    filtered.reverse();
    coalesce_adjacent_line_plot_appends(&mut filtered);
    *commands = filtered;
}

fn coalesce_adjacent_line_plot_appends(commands: &mut Vec<Command>) {
    if commands.len() < 2 {
        return;
    }
    let mut merged: Vec<Command> = Vec::with_capacity(commands.len());
    for command in commands.drain(..) {
        match command {
            Command::AppendLinePlotPointsPacked {
                id,
                series,
                xy,
                max_points,
                payload_format,
            } => {
                if let Some(Command::AppendLinePlotPointsPacked {
                    id: prev_id,
                    series: prev_series,
                    xy: prev_xy,
                    max_points: prev_max_points,
                    payload_format: prev_payload_format,
                }) = merged.last_mut()
                {
                    if *prev_id == id
                        && *prev_series == series
                        && *prev_max_points == max_points
                        && *prev_payload_format == payload_format
                    {
                        prev_xy.extend(xy);
                        continue;
                    }
                }
                merged.push(Command::AppendLinePlotPointsPacked {
                    id,
                    series,
                    xy,
                    max_points,
                    payload_format,
                });
            }
            other => merged.push(other),
        }
    }
    *commands = merged;
}

fn command_is_coalesced_scatter_points(command: &Command) -> bool {
    matches!(
        command,
        Command::SetScatterPointsPacked { coalesce: true, .. }
            | Command::UpdateScatterActorPacked { .. }
    )
}

fn decode_mesh_positions(b64: &str) -> Result<Vec<[f32; 3]>, DragonError> {
    let bytes = BASE64
        .decode(b64)
        .map_err(|e| DragonError::ParseError(format!("mesh positions base64: {e}")))?;
    if bytes.len() % 12 != 0 {
        return Err(DragonError::ParseError(format!(
            "mesh positions length {} is not a multiple of 12 (xyz float32)",
            bytes.len()
        )));
    }
    Ok(bytes
        .chunks_exact(12)
        .map(|c| {
            [
                f32::from_le_bytes([c[0], c[1], c[2], c[3]]),
                f32::from_le_bytes([c[4], c[5], c[6], c[7]]),
                f32::from_le_bytes([c[8], c[9], c[10], c[11]]),
            ]
        })
        .collect())
}

fn decode_mesh_indices(b64: &str) -> Result<Vec<[u32; 3]>, DragonError> {
    let bytes = BASE64
        .decode(b64)
        .map_err(|e| DragonError::ParseError(format!("mesh indices base64: {e}")))?;
    if bytes.len() % 12 != 0 {
        return Err(DragonError::ParseError(format!(
            "mesh indices length {} is not a multiple of 12 (3 × uint32 per triangle)",
            bytes.len()
        )));
    }
    Ok(bytes
        .chunks_exact(12)
        .map(|c| {
            [
                u32::from_le_bytes([c[0], c[1], c[2], c[3]]),
                u32::from_le_bytes([c[4], c[5], c[6], c[7]]),
                u32::from_le_bytes([c[8], c[9], c[10], c[11]]),
            ]
        })
        .collect())
}

/// Format a scalar like Python's :.4g — 4 significant figures, scientific when |exp| ≥ 4.
fn format_4g(v: f32) -> String {
    if v == 0.0 {
        return "0".to_string();
    }
    let abs = v.abs();
    if abs >= 1e-4_f32 && abs < 1e4_f32 {
        let exp = abs.log10().floor() as i32;
        let prec = (3 - exp).max(0) as usize;
        // Remove redundant trailing zeros after decimal point.
        let mut s = String::with_capacity(16);
        let _ = write!(&mut s, "{:.prec$}", v, prec = prec);
        if let Some(dot) = s.find('.') {
            while s.ends_with('0') {
                s.pop();
            }
            if s.len() == dot + 1 {
                s.truncate(dot);
            }
        }
        s
    } else {
        format!("{:.3e}", v)
    }
}

fn decode_actor_payload(
    b64: &str,
    colormap: &str,
    format: ScatterPayloadFormat,
) -> Result<Vec<PointInstance>, DragonError> {
    let bytes = BASE64
        .decode(b64)
        .map_err(|e| DragonError::ParseError(format!("scatter actor base64: {e}")))?;
    decode_actor_payload_bytes(&bytes, colormap, format)
}

fn decode_actor_payload_bytes(
    bytes: &[u8],
    colormap: &str,
    format: ScatterPayloadFormat,
) -> Result<Vec<PointInstance>, DragonError> {
    let mut pts = Vec::new();
    match format {
        ScatterPayloadFormat::XyzF32V0 => {
            decode_scatter_points_bytes_into_colormap(bytes, &mut pts, colormap)?;
        }
        ScatterPayloadFormat::PointInstanceV1 => {
            decode_scatter_points_v1(bytes, &mut pts)?;
        }
    }
    Ok(pts)
}

fn decode_line_plot_points_bytes(
    bytes: &[u8],
    format: LinePlotPayloadFormat,
) -> Result<Vec<[f32; 2]>, DragonError> {
    match format {
        LinePlotPayloadFormat::XyF32V0 => {
            if bytes.len() % 8 != 0 {
                return Err(DragonError::ParseError(format!(
                    "line plot xy payload length {} is not a multiple of 8",
                    bytes.len()
                )));
            }
            Ok(bytes
                .chunks_exact(8)
                .map(|chunk| {
                    [
                        f32::from_le_bytes(chunk[0..4].try_into().unwrap()),
                        f32::from_le_bytes(chunk[4..8].try_into().unwrap()),
                    ]
                })
                .collect())
        }
    }
}

fn decode_hover_meta_lines(meta: &str) -> Option<Vec<String>> {
    if let Some(packed) = meta.strip_prefix('\0') {
        return Some(if packed.is_empty() {
            Vec::new()
        } else {
            packed.split('\0').map(str::to_string).collect()
        });
    }
    serde_json::from_str::<Vec<String>>(meta).ok().or_else(|| {
        serde_json::from_str::<Vec<serde_json::Value>>(meta)
            .ok()
            .map(|values| {
                values
                    .iter()
                    .map(|value| value.as_str().unwrap_or("").to_string())
                    .collect()
            })
    })
}

#[derive(Debug, Clone)]
struct ScatterHoverColumn {
    name: String,
    values: ScatterHoverColumnValues,
}

#[derive(Debug, Clone)]
enum ScatterHoverColumnValues {
    F32(Vec<f32>),
    F64(Vec<f64>),
    I64(Vec<i64>),
    U64(Vec<u64>),
    Bool(Vec<u8>),
    Utf8(Vec<String>),
}

impl ScatterHoverColumn {
    fn row_text(&self, row: usize) -> Option<String> {
        let value = match &self.values {
            ScatterHoverColumnValues::F32(values) => values.get(row).map(|value| format_4g(*value)),
            ScatterHoverColumnValues::F64(values) => {
                values.get(row).map(|value| format_4g(*value as f32))
            }
            ScatterHoverColumnValues::I64(values) => values.get(row).map(i64::to_string),
            ScatterHoverColumnValues::U64(values) => values.get(row).map(u64::to_string),
            ScatterHoverColumnValues::Bool(values) => values.get(row).map(|value| {
                if *value == 0 {
                    "false".to_string()
                } else {
                    "true".to_string()
                }
            }),
            ScatterHoverColumnValues::Utf8(values) => values.get(row).cloned(),
        }?;
        Some(format!("{}: {}", self.name, value))
    }
}

fn decode_scatter_hover_columns(
    packets: Vec<ScatterHoverColumnPacket>,
) -> Result<Vec<ScatterHoverColumn>, DragonError> {
    packets
        .into_iter()
        .map(decode_scatter_hover_column)
        .collect()
}

fn decode_scatter_hover_column(
    packet: ScatterHoverColumnPacket,
) -> Result<ScatterHoverColumn, DragonError> {
    let values = match packet.dtype.as_str() {
        "f32" => {
            ensure_hover_column_bytes(&packet, 4)?;
            ScatterHoverColumnValues::F32(
                packet
                    .bytes
                    .chunks_exact(4)
                    .map(|chunk| f32::from_le_bytes(chunk.try_into().unwrap()))
                    .collect(),
            )
        }
        "f64" => {
            ensure_hover_column_bytes(&packet, 8)?;
            ScatterHoverColumnValues::F64(
                packet
                    .bytes
                    .chunks_exact(8)
                    .map(|chunk| f64::from_le_bytes(chunk.try_into().unwrap()))
                    .collect(),
            )
        }
        "i64" => {
            ensure_hover_column_bytes(&packet, 8)?;
            ScatterHoverColumnValues::I64(
                packet
                    .bytes
                    .chunks_exact(8)
                    .map(|chunk| i64::from_le_bytes(chunk.try_into().unwrap()))
                    .collect(),
            )
        }
        "u64" => {
            ensure_hover_column_bytes(&packet, 8)?;
            ScatterHoverColumnValues::U64(
                packet
                    .bytes
                    .chunks_exact(8)
                    .map(|chunk| u64::from_le_bytes(chunk.try_into().unwrap()))
                    .collect(),
            )
        }
        "bool" => {
            ensure_hover_column_bytes(&packet, 1)?;
            ScatterHoverColumnValues::Bool(packet.bytes)
        }
        "utf8" => {
            let text = String::from_utf8(packet.bytes).map_err(|e| {
                DragonError::ParseError(format!(
                    "scatter hover column {:?} is not valid utf-8: {e}",
                    packet.name
                ))
            })?;
            let values = if packet.len == 0 && text.is_empty() {
                Vec::new()
            } else {
                text.split('\0').map(str::to_string).collect::<Vec<_>>()
            };
            if values.len() != packet.len {
                return Err(DragonError::ParseError(format!(
                    "scatter hover column {:?} expected {} rows, found {}",
                    packet.name,
                    packet.len,
                    values.len()
                )));
            }
            ScatterHoverColumnValues::Utf8(values)
        }
        other => {
            return Err(DragonError::ParseError(format!(
                "unsupported scatter hover column dtype {other:?}"
            )));
        }
    };
    Ok(ScatterHoverColumn {
        name: packet.name,
        values,
    })
}

fn ensure_hover_column_bytes(
    packet: &ScatterHoverColumnPacket,
    bytes_per_value: usize,
) -> Result<(), DragonError> {
    let expected = packet.len.checked_mul(bytes_per_value).ok_or_else(|| {
        DragonError::ParseError(format!(
            "scatter hover column {:?} byte length overflow",
            packet.name
        ))
    })?;
    if packet.bytes.len() != expected {
        return Err(DragonError::ParseError(format!(
            "scatter hover column {:?} expected {} bytes, found {}",
            packet.name,
            expected,
            packet.bytes.len()
        )));
    }
    Ok(())
}

fn format_scatter_hover_columns(columns: &[ScatterHoverColumn], row: usize) -> Option<String> {
    if columns.is_empty() {
        return None;
    }
    let lines = columns
        .iter()
        .filter_map(|column| column.row_text(row))
        .collect::<Vec<_>>();
    (!lines.is_empty()).then(|| lines.join("\n"))
}

fn parse_line_plot_color(value: Option<String>) -> Option<ColorRef> {
    let text = value?;
    if text.trim().is_empty() {
        return None;
    }
    if let Some(color) = parse_web_color(text.trim()) {
        return Some(ColorRef::Rgba(color));
    }
    let parts: Vec<_> = text.split(',').map(str::trim).collect();
    if parts.len() == 3 || parts.len() == 4 {
        let parsed: Option<Vec<f32>> = parts.iter().map(|part| part.parse::<f32>().ok()).collect();
        if let Some(values) = parsed {
            let channel = |value: f32| {
                if value > 1.0 {
                    (value / 255.0).clamp(0.0, 1.0)
                } else {
                    value.clamp(0.0, 1.0)
                }
            };
            return Some(ColorRef::Rgba([
                channel(values[0]),
                channel(values[1]),
                channel(values[2]),
                values.get(3).copied().unwrap_or(1.0).clamp(0.0, 1.0),
            ]));
        }
    }
    Some(ColorRef::Token(text))
}

fn limit_line_plot_points(points: &mut Vec<[f32; 2]>, max_points: Option<usize>) -> usize {
    let Some(max_points) = max_points.filter(|value| *value > 0) else {
        return 0;
    };
    if points.len() <= max_points {
        return 0;
    }
    let drain = points.len() - max_points;
    points.drain(0..drain);
    drain
}

fn line_plot_front_trim_count(len: usize, max_points: Option<usize>) -> usize {
    let Some(max_points) = max_points.filter(|value| *value > 0) else {
        return 0;
    };
    len.saturating_sub(max_points)
}

fn line_plot_first_finite_x(points: &[[f32; 2]]) -> Option<f32> {
    points
        .iter()
        .find(|[x, y]| x.is_finite() && y.is_finite())
        .map(|[x, _]| *x)
}

fn line_plot_last_finite_x(points: &[[f32; 2]]) -> Option<f32> {
    points
        .iter()
        .rev()
        .find(|[x, y]| x.is_finite() && y.is_finite())
        .map(|[x, _]| *x)
}

fn line_plot_first_finite_raw_x(points: &[[f32; 2]]) -> Option<f32> {
    points.iter().find(|[x, _]| x.is_finite()).map(|[x, _]| *x)
}

fn line_plot_last_finite_raw_x(points: &[[f32; 2]]) -> Option<f32> {
    points
        .iter()
        .rev()
        .find(|[x, _]| x.is_finite())
        .map(|[x, _]| *x)
}

fn line_plot_append_preserves_x_order(existing: &[[f32; 2]], appended: &[[f32; 2]]) -> bool {
    match (
        line_plot_last_finite_raw_x(existing),
        line_plot_first_finite_raw_x(appended),
    ) {
        (Some(last), Some(first)) => last <= first,
        _ => true,
    }
}

fn line_plot_bounds_after_front_trim(
    points: &[[f32; 2]],
    trim: usize,
    combined_bounds: Option<[f32; 4]>,
    x_sorted: bool,
) -> Option<[f32; 4]> {
    if trim == 0 {
        return combined_bounds;
    }
    if trim >= points.len() {
        return None;
    }
    let retained = &points[trim..];
    if trim > retained.len() {
        return document::line_plot_points_bounds(retained);
    }
    let Some([x_min, x_max, y_min, y_max]) = combined_bounds else {
        return document::line_plot_points_bounds(retained);
    };
    let removed_touches_bound = points[..trim].iter().any(|[x, y]| {
        x.is_finite()
            && y.is_finite()
            && ((!x_sorted && (*x <= x_min || *x >= x_max)) || *y <= y_min || *y >= y_max)
    });
    if removed_touches_bound {
        return document::line_plot_points_bounds(retained);
    }
    if x_sorted {
        let x_min = line_plot_first_finite_x(retained)?;
        let x_max = line_plot_last_finite_x(retained)?;
        Some([x_min, x_max, y_min, y_max])
    } else {
        combined_bounds
    }
}

fn merge_line_plot_bounds(current: Option<[f32; 4]>, next: Option<[f32; 4]>) -> Option<[f32; 4]> {
    match (current, next) {
        (Some([cx_min, cx_max, cy_min, cy_max]), Some([nx_min, nx_max, ny_min, ny_max])) => Some([
            cx_min.min(nx_min),
            cx_max.max(nx_max),
            cy_min.min(ny_min),
            cy_max.max(ny_max),
        ]),
        (Some(bounds), None) | (None, Some(bounds)) => Some(bounds),
        (None, None) => None,
    }
}

fn line_plot_visible_x_range(points: &[[f32; 2]], x_min: f32, x_max: f32) -> (usize, usize) {
    if points.is_empty() {
        return (0, 0);
    }
    let Some(first) = points.first().map(|point| point[0]) else {
        return (0, 0);
    };
    let Some(last) = points.last().map(|point| point[0]) else {
        return (0, 0);
    };
    if !first.is_finite() || !last.is_finite() || first > last {
        return (0, points.len());
    }
    let start = points.partition_point(|point| point[0] < x_min);
    let end = points.partition_point(|point| point[0] <= x_max);
    (start, end)
}

fn line_plot_hover_x_range(
    points: &[[f32; 2]],
    bounds: LinePlotBounds,
    plot: [f32; 4],
    pos: [f32; 2],
    radius_px: f32,
) -> (usize, usize) {
    if points.is_empty() || plot[2] <= 1.0 {
        return (0, 0);
    }
    let Some(first) = points.first().map(|point| point[0]) else {
        return (0, 0);
    };
    let Some(last) = points.last().map(|point| point[0]) else {
        return (0, 0);
    };
    if !first.is_finite() || !last.is_finite() || first > last {
        return line_plot_visible_x_range(points, bounds.x_min, bounds.x_max);
    }
    let x_span = (bounds.x_max - bounds.x_min).max(f32::EPSILON);
    let tx = ((pos[0] - plot[0]) / plot[2]).clamp(0.0, 1.0);
    let data_x = bounds.x_min + tx * x_span;
    let radius_x = (radius_px.max(1.0) / plot[2]) * x_span;
    let start = points.partition_point(|point| point[0] < data_x - radius_x);
    let end = points.partition_point(|point| point[0] <= data_x + radius_x);
    if start < end {
        return (start.saturating_sub(1), (end + 1).min(points.len()));
    }
    if start > 0 && start < points.len() {
        return (start - 1, start + 1);
    }
    (start, end)
}

fn line_plot_visible_y_bounds(
    series: &document::LinePlotSeriesProp,
    start: usize,
    end: usize,
) -> Option<[f32; 2]> {
    if series.x_sorted {
        if let Some(bounds) = series.logical_y_bounds(start, end) {
            return Some(bounds);
        }
    }
    let points = series.logical_points();
    let end = end.min(points.len());
    if start >= end {
        return None;
    }
    let mut y_min = f32::INFINITY;
    let mut y_max = f32::NEG_INFINITY;
    for [x, y] in &points[start..end] {
        if x.is_finite() && y.is_finite() {
            y_min = y_min.min(*y);
            y_max = y_max.max(*y);
        }
    }
    y_min.is_finite().then_some([y_min, y_max])
}

fn apply_line_plot_window_to_node(node: &mut WidgetNode) -> bool {
    let Some(window) = node
        .props
        .line_plot_window_size
        .filter(|value| value.is_finite() && *value > 0.0)
    else {
        return false;
    };
    let latest_x = node
        .props
        .line_plot_series
        .iter()
        .filter_map(|series| {
            series
                .bounds
                .map(|bounds| bounds[1])
                .filter(|x| x.is_finite())
                .or_else(|| {
                    series
                        .logical_points()
                        .iter()
                        .rev()
                        .find(|[x, _]| x.is_finite())
                        .map(|[x, _]| *x)
                })
        })
        .fold(f32::NEG_INFINITY, f32::max);
    if !latest_x.is_finite() {
        return false;
    }
    let x_max = latest_x;
    let x_min = latest_x - window;
    let mut y_min = f32::INFINITY;
    let mut y_max = f32::NEG_INFINITY;
    for series in &node.props.line_plot_series {
        let points = series.logical_points();
        let (start, end) = line_plot_visible_x_range(points, x_min, x_max);
        if let Some([series_y_min, series_y_max]) = line_plot_visible_y_bounds(series, start, end) {
            y_min = y_min.min(series_y_min);
            y_max = y_max.max(series_y_max);
        }
    }
    if !y_min.is_finite() || !y_max.is_finite() {
        for series in &node.props.line_plot_series {
            if let Some([_, _, series_y_min, series_y_max]) = series.bounds {
                if series_y_min.is_finite() && series_y_max.is_finite() {
                    y_min = y_min.min(series_y_min);
                    y_max = y_max.max(series_y_max);
                    continue;
                }
            }
            for [_, y] in series.logical_points() {
                if y.is_finite() {
                    y_min = y_min.min(*y);
                    y_max = y_max.max(*y);
                }
            }
        }
    }
    if !y_min.is_finite() || !y_max.is_finite() {
        y_min = -1.0;
        y_max = 1.0;
    } else if (y_max - y_min).abs() <= f32::EPSILON {
        let pad = y_min.abs().max(1.0) * 0.5;
        y_min -= pad;
        y_max += pad;
    } else {
        let pad = (y_max - y_min).abs() * 0.05;
        y_min -= pad;
        y_max += pad;
    }
    node.props.line_plot_auto_fit = false;
    node.props.line_plot_x_min = Some(x_min);
    node.props.line_plot_x_max = Some(x_max);
    node.props.line_plot_y_min = Some(y_min);
    node.props.line_plot_y_max = Some(y_max);
    true
}

fn line_plot_point_counts(node: &WidgetNode) -> (usize, usize, usize) {
    let series_count = node.props.line_plot_series.len();
    let total_points = node
        .props
        .line_plot_series
        .iter()
        .map(|series| series.logical_len())
        .sum();
    let visible_points = line_plot_resolved_bounds(node)
        .map(|bounds| {
            node.props
                .line_plot_series
                .iter()
                .map(|series| {
                    let (start, end) = line_plot_visible_x_range(
                        series.logical_points(),
                        bounds.x_min,
                        bounds.x_max,
                    );
                    end.saturating_sub(start)
                })
                .sum()
        })
        .unwrap_or(0);
    (series_count, total_points, visible_points)
}

fn decode_scatter_points_bytes_into_colormap(
    bytes: &[u8],
    pts: &mut Vec<PointInstance>,
    colormap: &str,
) -> Result<Option<(glam::Vec3, glam::Vec3)>, DragonError> {
    decode_scatter_points_bytes_into_colormap_with_bounds(bytes, pts, colormap, None)
}

fn decode_scatter_points_bytes_into_colormap_with_bounds(
    bytes: &[u8],
    pts: &mut Vec<PointInstance>,
    colormap: &str,
    bounds_hint: Option<(glam::Vec3, glam::Vec3)>,
) -> Result<Option<(glam::Vec3, glam::Vec3)>, DragonError> {
    if bytes.len() % 12 != 0 {
        return Err(DragonError::ParseError(format!(
            "scatter data length {} is not a multiple of 12 (xyz float32)",
            bytes.len()
        )));
    }

    let n = bytes.len() / 12;
    pts.clear();
    pts.reserve(n);

    if n == 0 {
        return Ok(None);
    }

    if let Some((min, max)) = valid_scatter_bounds_hint(bounds_hint) {
        let z_min = min.z;
        let z_max = max.z;
        let z_range = if z_max > z_min { z_max - z_min } else { 1.0 };
        let cmap = scatter::colormap::resolve(colormap);
        for chunk in bytes.chunks_exact(12) {
            let [x, y, z] = read_xyz_f32_v0(chunk);
            let t = if z.is_finite() {
                ((z - z_min) / z_range).clamp(0.0, 1.0)
            } else {
                0.0
            };
            let [r, g, b] = scatter::colormap::sample(cmap, t);
            pts.push(PointInstance {
                position: [x, y, z],
                size: 3.0,
                color: [r, g, b],
                alpha: 1.0,
            });
        }
        return Ok(Some((min, max)));
    }

    // Decode once while computing z range and data bounds. Color is filled after
    // the final z range is known so xyz_f32_v0 keeps exact auto-colormap behavior.
    let mut z_min = f32::INFINITY;
    let mut z_max = f32::NEG_INFINITY;
    let mut min = glam::Vec3::splat(f32::INFINITY);
    let mut max = glam::Vec3::splat(f32::NEG_INFINITY);
    for chunk in bytes.chunks_exact(12) {
        let [x, y, z] = read_xyz_f32_v0(chunk);
        if z.is_finite() {
            z_min = z_min.min(z);
            z_max = z_max.max(z);
        }
        if x.is_finite() && y.is_finite() && z.is_finite() {
            let p = glam::Vec3::new(x, y, z);
            min = min.min(p);
            max = max.max(p);
        }
        pts.push(PointInstance {
            position: [x, y, z],
            size: 3.0,
            color: [0.0, 0.0, 0.0],
            alpha: 1.0,
        });
    }
    let z_range = if z_max > z_min { z_max - z_min } else { 1.0 };
    let bounds = if min.x > max.x {
        None
    } else {
        Some((min, max))
    };

    // Assign colors by normalized z position within the range.
    let cmap = scatter::colormap::resolve(colormap);
    for pt in pts.iter_mut() {
        let z = pt.position[2];
        let t = if z.is_finite() {
            ((z - z_min) / z_range).clamp(0.0, 1.0)
        } else {
            0.0
        };
        let [r, g, b] = scatter::colormap::sample(cmap, t);
        pt.color = [r, g, b];
    }

    Ok(bounds)
}

#[inline]
fn read_xyz_f32_v0(chunk: &[u8]) -> [f32; 3] {
    [
        f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]),
        f32::from_le_bytes([chunk[4], chunk[5], chunk[6], chunk[7]]),
        f32::from_le_bytes([chunk[8], chunk[9], chunk[10], chunk[11]]),
    ]
}

fn valid_scatter_bounds_hint(
    bounds_hint: Option<(glam::Vec3, glam::Vec3)>,
) -> Option<(glam::Vec3, glam::Vec3)> {
    bounds_hint.filter(|(min, max)| {
        min.is_finite() && max.is_finite() && min.x <= max.x && min.y <= max.y && min.z <= max.z
    })
}

fn decode_scatter_points_v1(
    bytes: &[u8],
    pts: &mut Vec<PointInstance>,
) -> Result<Option<(glam::Vec3, glam::Vec3)>, DragonError> {
    const STRIDE: usize = std::mem::size_of::<PointInstance>();
    if bytes.len() % STRIDE != 0 {
        return Err(DragonError::ParseError(format!(
            "scatter point_instance_v1 payload length {} is not a multiple of {} (PointInstance size)",
            bytes.len(),
            STRIDE
        )));
    }
    let n = bytes.len() / STRIDE;
    pts.clear();
    pts.reserve(n);
    let mut min = glam::Vec3::splat(f32::INFINITY);
    let mut max = glam::Vec3::splat(f32::NEG_INFINITY);
    for chunk in bytes.chunks_exact(STRIDE) {
        let mut point = bytemuck::pod_read_unaligned::<PointInstance>(chunk);
        let [x, y, z] = point.position;
        if x.is_finite() && y.is_finite() && z.is_finite() {
            let p = glam::Vec3::new(x, y, z);
            min = min.min(p);
            max = max.max(p);
        }
        point.size = point.size.max(0.0);
        pts.push(point);
    }
    if min.x > max.x {
        Ok(None)
    } else {
        Ok(Some((min, max)))
    }
}

fn bounds_from_scatter_point_instances_v1(
    bytes: &[u8],
) -> Result<Option<(glam::Vec3, glam::Vec3)>, DragonError> {
    const STRIDE: usize = std::mem::size_of::<PointInstance>();
    if bytes.len() % STRIDE != 0 {
        return Err(DragonError::ParseError(format!(
            "scatter point_instance_v1 payload length {} is not a multiple of {} (PointInstance size)",
            bytes.len(),
            STRIDE
        )));
    }
    let mut min = glam::Vec3::splat(f32::INFINITY);
    let mut max = glam::Vec3::splat(f32::NEG_INFINITY);
    for chunk in bytes.chunks_exact(STRIDE) {
        let point = bytemuck::pod_read_unaligned::<PointInstance>(chunk);
        let [x, y, z] = point.position;
        if x.is_finite() && y.is_finite() && z.is_finite() {
            let p = glam::Vec3::new(x, y, z);
            min = min.min(p);
            max = max.max(p);
        }
    }
    if min.x > max.x {
        Ok(None)
    } else {
        Ok(Some((min, max)))
    }
}

fn compute_scatter_bounds(pts: &[PointInstance]) -> Option<(glam::Vec3, glam::Vec3)> {
    let mut min = glam::Vec3::splat(f32::INFINITY);
    let mut max = glam::Vec3::splat(f32::NEG_INFINITY);
    for pt in pts {
        let [x, y, z] = pt.position;
        if x.is_finite() && y.is_finite() && z.is_finite() {
            min = min.min(glam::Vec3::new(x, y, z));
            max = max.max(glam::Vec3::new(x, y, z));
        }
    }
    if min.x > max.x {
        None
    } else {
        Some((min, max))
    }
}

fn scatter_chrome_from_props(props: &document::NodeProps) -> scatter::ScatterChromeState {
    scatter::ScatterChromeState {
        grid_visible: props.scatter_grid_visible,
        major_planes: props.scatter_major_planes,
        minor_planes: props.scatter_minor_planes,
        grid_sticky: props.scatter_grid_sticky,
        grid_all_edges: props.scatter_grid_all_edges,
        tick_override: props.scatter_tick_override,
        axis_labels: props.scatter_axis_labels.clone(),
        axis_visible: props.scatter_axis_visible,
        background_color: props.scatter_background,
        legend: scatter::LegendState {
            visible: props.scatter_legend_visible,
            position: scatter::LegendPosition::from_str(&props.scatter_legend_position),
            entries: props
                .scatter_legend_entries
                .iter()
                .map(|(label, r, g, b)| scatter::LegendEntry {
                    label: label.clone(),
                    color: [*r, *g, *b],
                })
                .collect(),
            title: props.scatter_legend_title.clone(),
        },
        scalar_bar: scatter::ScalarBarState {
            visible: props.scatter_scalar_bar_visible,
            vmin: props.scatter_scalar_bar_vmin,
            vmax: props.scatter_scalar_bar_vmax,
            log_scale: props.scatter_scalar_bar_log_scale,
            colormap: props.scatter_scalar_bar_colormap.clone(),
            title: props.scatter_scalar_bar_title.clone(),
        },
        orientation_axes_visible: props.scatter_orientation_axes_visible,
    }
}

fn scatter_chrome_from_node(node: &WidgetNode) -> scatter::ScatterChromeState {
    let mut chrome = scatter_chrome_from_props(&node.props);
    apply_scatter_chrome_style(&mut chrome, &node.style.widget);
    chrome
}

fn scatter_interaction_mode_from_node(node: &WidgetNode) -> scatter::ScatterInteractionMode {
    node.props
        .raw_props
        .get("interaction")
        .and_then(|value| value.as_str())
        .map(scatter::ScatterInteractionMode::from_str)
        .unwrap_or_default()
}

fn apply_scatter_chrome_style(chrome: &mut scatter::ScatterChromeState, style: &WidgetStyle) {
    if let Some(visible) = style.scatter_grid_visible {
        chrome.grid_visible = visible;
    }
    if let Some((major, minor)) = style.scatter_grid_planes {
        chrome.major_planes = major;
        chrome.minor_planes = minor;
    }
    if let Some(position) = style.scatter_legend_position.as_deref() {
        chrome.legend.position = scatter::LegendPosition::from_str(position);
    }
    if let Some(visible) = style.scatter_orientation_axes_visible {
        chrome.orientation_axes_visible = visible;
    }
}

