// Depth texture helpers
// ---------------------------------------------------------------------------

fn create_depth_texture(
    device: &wgpu::Device,
    width: u32,
    height: u32,
) -> (wgpu::Texture, wgpu::TextureView) {
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("depth"),
        size: wgpu::Extent3d {
            width,
            height,
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: crate::DEPTH_STENCIL_FORMAT,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
        view_formats: &[],
    });
    let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
    (texture, view)
}

#[repr(C)]
#[derive(Copy, Clone, Pod, Zeroable)]
struct ScatterCompositeUniforms {
    target_rect: [f32; 4],
    screen_size: [f32; 2],
    _pad: [f32; 2],
}

struct ScatterCompositeRenderer {
    pipeline: wgpu::RenderPipeline,
    bind_group_layout: wgpu::BindGroupLayout,
    sampler: wgpu::Sampler,
}

impl ScatterCompositeRenderer {
    fn new(device: &wgpu::Device, surface_format: wgpu::TextureFormat) -> Self {
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("scatter-composite"),
            source: wgpu::ShaderSource::Wgsl(include_str!("scatter/composite.wgsl").into()),
        });
        let bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("scatter-composite-bgl"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::VERTEX,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Uniform,
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 2,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
            ],
        });
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("scatter-composite-pl"),
            bind_group_layouts: &[Some(&bind_group_layout)],
            immediate_size: 0,
        });
        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("scatter-composite"),
            layout: Some(&pipeline_layout),
            vertex: wgpu::VertexState {
                module: &shader,
                entry_point: Some("vs_main"),
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[],
            },
            fragment: Some(wgpu::FragmentState {
                module: &shader,
                entry_point: Some("fs_main"),
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    blend: Some(wgpu::BlendState {
                        color: wgpu::BlendComponent {
                            src_factor: wgpu::BlendFactor::One,
                            dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
                            operation: wgpu::BlendOperation::Add,
                        },
                        alpha: wgpu::BlendComponent {
                            src_factor: wgpu::BlendFactor::One,
                            dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
                            operation: wgpu::BlendOperation::Add,
                        },
                    }),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleStrip,
                ..Default::default()
            },
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview_mask: None,
            cache: None,
        });
        let sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("scatter-composite-sampler"),
            mag_filter: wgpu::FilterMode::Linear,
            min_filter: wgpu::FilterMode::Linear,
            mipmap_filter: wgpu::MipmapFilterMode::Nearest,
            address_mode_u: wgpu::AddressMode::ClampToEdge,
            address_mode_v: wgpu::AddressMode::ClampToEdge,
            ..Default::default()
        });
        Self {
            pipeline,
            bind_group_layout,
            sampler,
        }
    }

    fn create_bind_group(
        &self,
        device: &wgpu::Device,
        uniform_buffer: &wgpu::Buffer,
        source_view: &wgpu::TextureView,
    ) -> wgpu::BindGroup {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("scatter-composite-bg"),
            layout: &self.bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: uniform_buffer.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: wgpu::BindingResource::TextureView(source_view),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: wgpu::BindingResource::Sampler(&self.sampler),
                },
            ],
        })
    }

    fn render<'pass>(
        &'pass self,
        pass: &mut wgpu::RenderPass<'pass>,
        bind_group: &'pass wgpu::BindGroup,
    ) {
        pass.set_pipeline(&self.pipeline);
        pass.set_bind_group(0, bind_group, &[]);
        pass.draw(0..4, 0..1);
    }
}

struct ScatterRenderTarget {
    _color_texture: wgpu::Texture,
    color_view: wgpu::TextureView,
    _depth_texture: wgpu::Texture,
    depth_view: wgpu::TextureView,
    bind_group: wgpu::BindGroup,
    composite_uniform_buffer: wgpu::Buffer,
    width: u32,
    height: u32,
    format: wgpu::TextureFormat,
    scene_revision: u64,
}

impl ScatterRenderTarget {
    fn new(
        device: &wgpu::Device,
        compositor: &ScatterCompositeRenderer,
        width: u32,
        height: u32,
        format: wgpu::TextureFormat,
    ) -> Self {
        let color_texture = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("scatter-render-scale-color"),
            size: wgpu::Extent3d {
                width,
                height,
                depth_or_array_layers: 1,
            },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format,
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::TEXTURE_BINDING,
            view_formats: &[],
        });
        let color_view = color_texture.create_view(&wgpu::TextureViewDescriptor::default());
        let depth_texture = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("scatter-render-scale-depth"),
            size: wgpu::Extent3d {
                width,
                height,
                depth_or_array_layers: 1,
            },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: crate::DEPTH_STENCIL_FORMAT,
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
            view_formats: &[],
        });
        let depth_view = depth_texture.create_view(&wgpu::TextureViewDescriptor::default());
        let composite_uniform_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("scatter-composite-uniforms"),
            size: std::mem::size_of::<ScatterCompositeUniforms>() as u64,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let bind_group =
            compositor.create_bind_group(device, &composite_uniform_buffer, &color_view);
        Self {
            _color_texture: color_texture,
            color_view,
            _depth_texture: depth_texture,
            depth_view,
            bind_group,
            composite_uniform_buffer,
            width,
            height,
            format,
            scene_revision: 0,
        }
    }

    fn matches(&self, width: u32, height: u32, format: wgpu::TextureFormat) -> bool {
        self.width == width && self.height == height && self.format == format
    }

    fn update_composite_uniforms(
        &self,
        queue: &wgpu::Queue,
        target_rect: [f32; 4],
        screen_width: u32,
        screen_height: u32,
    ) {
        let uniforms = ScatterCompositeUniforms {
            target_rect,
            screen_size: [screen_width as f32, screen_height as f32],
            _pad: [0.0; 2],
        };
        queue.write_buffer(
            &self.composite_uniform_buffer,
            0,
            bytemuck::bytes_of(&uniforms),
        );
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct FrameRenderTimings {
    total_ms: f64,
    prepare_ms: f64,
    acquire_ms: f64,
    encode_ms: f64,
    submit_ms: f64,
    present_ms: f64,
}

impl FrameRenderTimings {
    fn work_ms(self) -> f64 {
        self.prepare_ms + self.encode_ms + self.submit_ms
    }
}

fn display_list_text_commands(display_list: Option<&Value>) -> Vec<&Value> {
    display_list
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|command| command.get("cmd").and_then(Value::as_str) == Some("text"))
        .collect()
}

fn extension_display_list_dirty(previous: Option<&Value>, next: &Value) -> Dirty {
    if display_list_text_commands(previous) == display_list_text_commands(Some(next)) {
        Dirty::Visual
    } else {
        Dirty::Text
    }
}

const STAGE_TIMING_SAMPLE_WINDOW: usize = 128;

#[derive(Debug, Clone, Copy)]
struct StageTimingStats {
    count: u64,
    last_ms: f64,
    total_ms: f64,
    min_ms: f64,
    max_ms: f64,
    samples_ms: [f64; STAGE_TIMING_SAMPLE_WINDOW],
    sample_count: u16,
    sample_cursor: u16,
}

impl Default for StageTimingStats {
    fn default() -> Self {
        Self {
            count: 0,
            last_ms: 0.0,
            total_ms: 0.0,
            min_ms: 0.0,
            max_ms: 0.0,
            samples_ms: [0.0; STAGE_TIMING_SAMPLE_WINDOW],
            sample_count: 0,
            sample_cursor: 0,
        }
    }
}

impl StageTimingStats {
    fn record(&mut self, ms: f64) {
        if self.count == 0 {
            self.min_ms = ms;
            self.max_ms = ms;
        } else {
            self.min_ms = self.min_ms.min(ms);
            self.max_ms = self.max_ms.max(ms);
        }
        self.count += 1;
        self.last_ms = ms;
        self.total_ms += ms;
        let cursor = self.sample_cursor as usize;
        self.samples_ms[cursor] = ms;
        self.sample_cursor = ((cursor + 1) % STAGE_TIMING_SAMPLE_WINDOW) as u16;
        self.sample_count = self
            .sample_count
            .saturating_add(1)
            .min(STAGE_TIMING_SAMPLE_WINDOW as u16);
    }

    fn avg_ms(self) -> f64 {
        if self.count == 0 {
            0.0
        } else {
            self.total_ms / self.count as f64
        }
    }

    fn percentile_ms(self, percentile: f64) -> f64 {
        let sample_count = self.sample_count as usize;
        if sample_count == 0 {
            return 0.0;
        }
        let mut samples = self.samples_ms[..sample_count].to_vec();
        samples.sort_by(f64::total_cmp);
        let rank = ((samples.len() - 1) as f64 * percentile.clamp(0.0, 1.0)).round() as usize;
        samples[rank]
    }

    fn json_value(self) -> Value {
        json!({
            "count": self.count,
            "last_ms": self.last_ms,
            "avg_ms": self.avg_ms(),
            "total_ms": self.total_ms,
            "min_ms": self.min_ms,
            "max_ms": self.max_ms,
            "p50_ms": self.percentile_ms(0.50),
            "p95_ms": self.percentile_ms(0.95),
            "p99_ms": self.percentile_ms(0.99),
            "sample_window": self.sample_count,
        })
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct FrameTimingStats {
    total: StageTimingStats,
    work: StageTimingStats,
    prepare: StageTimingStats,
    acquire: StageTimingStats,
    encode: StageTimingStats,
    submit: StageTimingStats,
    present: StageTimingStats,
}

impl FrameTimingStats {
    fn record(&mut self, timings: FrameRenderTimings) {
        self.total.record(timings.total_ms);
        self.work.record(timings.work_ms());
        self.prepare.record(timings.prepare_ms);
        self.acquire.record(timings.acquire_ms);
        self.encode.record(timings.encode_ms);
        self.submit.record(timings.submit_ms);
        self.present.record(timings.present_ms);
    }

    fn json_value(self) -> Value {
        json!({
            "total": self.total.json_value(),
            "work": self.work.json_value(),
            "prepare": self.prepare.json_value(),
            "acquire": self.acquire.json_value(),
            "encode": self.encode.json_value(),
            "submit": self.submit.json_value(),
            "present": self.present.json_value(),
        })
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct DirtyRebuildStats {
    requested: [u64; 5],
    executed: [u64; 5],
    deferred_merges: u64,
}

impl DirtyRebuildStats {
    fn index(dirty: Dirty) -> usize {
        match dirty {
            Dirty::Layout => 0,
            Dirty::Text => 1,
            Dirty::Visual => 2,
            Dirty::GpuData => 3,
            Dirty::Full => 4,
        }
    }

    fn record_request(&mut self, dirty: Dirty) {
        let index = Self::index(dirty);
        self.requested[index] = self.requested[index].saturating_add(1);
    }

    fn record_execution(&mut self, dirty: Dirty) {
        let index = Self::index(dirty);
        self.executed[index] = self.executed[index].saturating_add(1);
    }

    fn counts_json(counts: [u64; 5]) -> Value {
        json!({
            "layout": counts[0],
            "text": counts[1],
            "visual": counts[2],
            "gpu_data": counts[3],
            "full": counts[4],
        })
    }

    fn json_value(self) -> Value {
        json!({
            "requested": Self::counts_json(self.requested),
            "executed": Self::counts_json(self.executed),
            "deferred_merges": self.deferred_merges,
        })
    }
}

