fn collect_targeted_text_roots(
    node: &WidgetNode,
    targets: &HashSet<String>,
    roots: &mut HashSet<String>,
    matched: &mut usize,
    ancestor_selected: bool,
) {
    let selected = targets.contains(&node.id);
    if selected {
        *matched += 1;
    }
    if selected && !ancestor_selected {
        roots.insert(node.id.clone());
    }
    for child in &node.children {
        collect_targeted_text_roots(
            child,
            targets,
            roots,
            matched,
            ancestor_selected || selected,
        );
    }
}

fn normalize_targeted_text_roots(
    tree: &WidgetNode,
    targets: &HashSet<String>,
) -> Option<HashSet<String>> {
    let mut roots = HashSet::new();
    let mut matched = 0;
    collect_targeted_text_roots(tree, targets, &mut roots, &mut matched, false);
    (matched == targets.len()).then_some(roots)
}

fn subtree_contains_widget_kind(node: &WidgetNode, kind: WidgetKind) -> bool {
    node.kind == kind
        || node
            .children
            .iter()
            .any(|child| subtree_contains_widget_kind(child, kind))
}

fn targeted_subtrees_contain_widget_kind(
    tree: &WidgetNode,
    targets: &HashSet<String>,
    kind: WidgetKind,
) -> Option<bool> {
    for target in targets {
        let node = find_node(tree, target)?;
        if subtree_contains_widget_kind(node, kind) {
            return Some(true);
        }
    }
    Some(false)
}

fn surface_present_mode_name(mode: wgpu::PresentMode) -> &'static str {
    match mode {
        wgpu::PresentMode::AutoVsync => "auto-vsync",
        wgpu::PresentMode::AutoNoVsync => "auto-no-vsync",
        wgpu::PresentMode::Fifo => "fifo",
        wgpu::PresentMode::FifoRelaxed => "fifo-relaxed",
        wgpu::PresentMode::Immediate => "immediate",
        wgpu::PresentMode::Mailbox => "mailbox",
    }
}

fn surface_present_mode_from_name(value: &str) -> Option<wgpu::PresentMode> {
    match value.trim().to_ascii_lowercase().as_str() {
        "auto-vsync" | "autovsync" | "vsync" => Some(wgpu::PresentMode::AutoVsync),
        "auto-no-vsync" | "autonovsync" | "no-vsync" | "novsync" | "uncapped" => {
            Some(wgpu::PresentMode::AutoNoVsync)
        }
        "fifo" => Some(wgpu::PresentMode::Fifo),
        "fifo-relaxed" | "fiforelaxed" => Some(wgpu::PresentMode::FifoRelaxed),
        "immediate" => Some(wgpu::PresentMode::Immediate),
        "mailbox" => Some(wgpu::PresentMode::Mailbox),
        _ => None,
    }
}

fn choose_surface_present_mode(
    requested: Option<&str>,
    fallback: wgpu::PresentMode,
    supported: &[wgpu::PresentMode],
) -> wgpu::PresentMode {
    let Some(requested) = requested.and_then(surface_present_mode_from_name) else {
        return fallback;
    };
    if matches!(
        requested,
        wgpu::PresentMode::AutoVsync | wgpu::PresentMode::AutoNoVsync
    ) || supported.contains(&requested)
    {
        return requested;
    }
    match requested {
        wgpu::PresentMode::Immediate | wgpu::PresentMode::Mailbox => wgpu::PresentMode::AutoNoVsync,
        wgpu::PresentMode::FifoRelaxed => wgpu::PresentMode::AutoVsync,
        _ => fallback,
    }
}

// ---------------------------------------------------------------------------
// Walk helpers
// ---------------------------------------------------------------------------

fn collect_visible_scatter_ids(
    node: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    out: &mut Vec<String>,
) {
    if node.kind == WidgetKind::Scatter3D && layout.visible_rect(&node.id).is_some() {
        out.push(node.id.clone());
    }
    // Visit children in z-index paint order (matching primitives/text stacking_children).
    if node
        .children
        .iter()
        .all(|child| child.style.layout.z_index.is_none())
    {
        for child in &node.children {
            collect_visible_scatter_ids(child, layout, out);
        }
        return;
    }
    let mut children: Vec<_> = node.children.iter().enumerate().collect();
    children.sort_by_key(|(index, child)| (child.style.layout.z_index.unwrap_or(0), *index));
    for (_, child) in children {
        collect_visible_scatter_ids(child, layout, out);
    }
}

fn collect_all_scatter_ids(node: &WidgetNode, out: &mut Vec<String>) {
    if node.kind == WidgetKind::Scatter3D {
        out.push(node.id.clone());
    }
    for child in &node.children {
        collect_all_scatter_ids(child, out);
    }
}

fn scatter_clip_radii(node: &WidgetNode, fallback_radius_lp: f32, scale_factor: f32) -> [f32; 4] {
    let radius_lp = node
        .style
        .visual
        .border_radius
        .unwrap_or(fallback_radius_lp)
        .max(0.0);
    node.style
        .visual
        .corner_radii
        .resolve(radius_lp)
        .map(|radius| radius.max(0.0) * scale_factor)
}

fn scatter_border_inset(node: &WidgetNode, scale_factor: f32) -> f32 {
    node.style
        .visual
        .border_width
        .unwrap_or(BORDER_WIDTH_LP)
        .max(0.0)
        * scale_factor
}

fn inset_scatter_clip_radii(radii: [f32; 4], inset: f32) -> [f32; 4] {
    radii.map(|radius| (radius - inset).max(0.0))
}

#[cfg(test)]
fn find_first_widget_kind_id<'a>(node: &'a WidgetNode, kind: &WidgetKind) -> Option<&'a str> {
    if &node.kind == kind {
        return Some(&node.id);
    }
    for child in &node.children {
        if let Some(id) = find_first_widget_kind_id(child, kind) {
            return Some(id);
        }
    }
    None
}

fn collect_widget_kinds(node: &WidgetNode, out: &mut HashMap<String, WidgetKind>) {
    out.insert(node.id.clone(), node.kind.clone());
    for child in &node.children {
        collect_widget_kinds(child, out);
    }
}

fn collect_tooltip_overlay_targets(node: &WidgetNode, out: &mut HashSet<String>) {
    if node
        .props
        .tooltip
        .as_deref()
        .is_some_and(|tooltip| !tooltip.trim().is_empty())
    {
        out.insert(node.id.clone());
    }
    if node.kind == WidgetKind::Tooltip {
        if let Some(target) = node
            .props
            .target
            .as_deref()
            .filter(|target| !target.is_empty())
        {
            out.insert(target.to_string());
        }
    }
    for child in &node.children {
        collect_tooltip_overlay_targets(child, out);
    }
}

fn find_widget<'a>(node: &'a WidgetNode, id: &str) -> Option<&'a WidgetNode> {
    if node.id == id {
        return Some(node);
    }
    for child in &node.children {
        if let Some(found) = find_widget(child, id) {
            return Some(found);
        }
    }
    None
}

fn radio_neighbor_id(
    node: &WidgetNode,
    current_id: &str,
    direction: i32,
    state: &WidgetState,
) -> Option<String> {
    let radios: Vec<&WidgetNode> = node
        .children
        .iter()
        .filter(|child| child.kind == WidgetKind::RadioButton)
        .collect();
    if let Some(current) = radios.iter().position(|child| child.id == current_id) {
        if radios.len() <= 1 {
            return None;
        }
        let step_back = direction < 0;
        for offset in 1..=radios.len() {
            let idx = if step_back {
                (current + radios.len() - offset) % radios.len()
            } else {
                (current + offset) % radios.len()
            };
            let candidate = radios[idx];
            if !candidate.props.disabled && !state.is_disabled(&candidate.id) {
                return Some(candidate.id.clone());
            }
        }
        return None;
    }
    for child in &node.children {
        if let Some(id) = radio_neighbor_id(child, current_id, direction, state) {
            return Some(id);
        }
    }
    None
}

fn collect_tree_node_ids(node: &WidgetNode, out: &mut Vec<String>) {
    if node.kind == WidgetKind::TreeNode {
        out.push(node.id.clone());
    }
    for child in &node.children {
        collect_tree_node_ids(child, out);
    }
}

fn tree_node_selection_scope_ids(node: &WidgetNode, current_id: &str) -> Option<Vec<String>> {
    if node.kind == WidgetKind::TreeView {
        let mut ids = Vec::new();
        collect_tree_node_ids(node, &mut ids);
        if ids.iter().any(|id| id == current_id) {
            return Some(ids);
        }
    }
    for child in &node.children {
        if let Some(ids) = tree_node_selection_scope_ids(child, current_id) {
            return Some(ids);
        }
    }
    None
}

fn visible_tree_node_ids(
    node: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    state: &WidgetState,
    out: &mut Vec<String>,
) {
    if node.kind == WidgetKind::TreeNode
        && !state.is_disabled(&node.id)
        && layout
            .visible_rect(&node.id)
            .is_some_and(|rect| rect.w > 0.0 && rect.h > 0.0)
    {
        out.push(node.id.clone());
    }
    for child in &node.children {
        visible_tree_node_ids(child, layout, state, out);
    }
}

fn tree_node_neighbor_id(
    tree: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    state: &WidgetState,
    current_id: &str,
    direction: i32,
) -> Option<String> {
    let mut ids = Vec::new();
    visible_tree_node_ids(tree, layout, state, &mut ids);
    let current = ids.iter().position(|id| id == current_id)?;
    let next = if direction < 0 {
        current.checked_sub(1)?
    } else {
        (current + 1 < ids.len()).then_some(current + 1)?
    };
    ids.get(next).cloned()
}

fn first_visible_child_tree_node_id(
    node: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    state: &WidgetState,
    current_id: &str,
) -> Option<String> {
    let current = find_widget(node, current_id)?;
    current
        .children
        .iter()
        .find(|child| {
            child.kind == WidgetKind::TreeNode
                && !state.is_disabled(&child.id)
                && layout
                    .visible_rect(&child.id)
                    .is_some_and(|rect| rect.w > 0.0 && rect.h > 0.0)
        })
        .map(|child| child.id.clone())
}

fn active_modal_ref(node: &WidgetNode) -> Option<&WidgetNode> {
    for child in node.children.iter().rev() {
        if let Some(modal) = active_modal_ref(child) {
            return Some(modal);
        }
    }
    (node.kind == WidgetKind::Modal && node.props.open.unwrap_or(false)).then_some(node)
}

fn has_rich_tooltip_for_target(node: &WidgetNode, target: &str) -> bool {
    if node.kind == WidgetKind::Tooltip && node.props.target.as_deref() == Some(target) {
        return true;
    }
    node.children
        .iter()
        .any(|child| has_rich_tooltip_for_target(child, target))
}

fn scroll_container_at_pos(
    node: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    state: &WidgetState,
    pos: [f32; 2],
) -> Option<String> {
    if node.kind == WidgetKind::Tooltip {
        return None;
    }
    for child in node.children.iter().rev() {
        if let Some(id) = scroll_container_at_pos(child, layout, state, pos) {
            return Some(id);
        }
    }
    if !is_scroll_container_node(node) || state.is_disabled(&node.id) {
        return None;
    }
    let rect = layout.visible_rect(&node.id)?;
    if pos[0] < rect.x || pos[0] >= rect.x + rect.w || pos[1] < rect.y || pos[1] >= rect.y + rect.h
    {
        return None;
    }
    let max_scroll_x = layout
        .scroll_max_x
        .get(&node.id)
        .copied()
        .unwrap_or_else(|| scroll_container_max_x(node, layout));
    let max_scroll_y = layout
        .scroll_max_y
        .get(&node.id)
        .copied()
        .unwrap_or_else(|| scroll_container_max_y(node, layout));
    (max_scroll_x > 0.0 || max_scroll_y > 0.0).then(|| node.id.clone())
}

fn active_scroll_container_at_pos(
    tree: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    state: &WidgetState,
    pos: [f32; 2],
) -> Option<String> {
    let root = active_modal_ref(tree).unwrap_or(tree);
    scroll_container_at_pos(root, layout, state, pos)
}

fn clear_line_plot_hover_except(
    node: &mut WidgetNode,
    keep_id: Option<&str>,
    changed: &mut bool,
    cleared: &mut Vec<String>,
) {
    if node.kind == WidgetKind::LinePlot
        && Some(node.id.as_str()) != keep_id
        && node.props.line_plot_hover.is_some()
    {
        node.props.line_plot_hover = None;
        cleared.push(node.id.clone());
        *changed = true;
    }
    for child in &mut node.children {
        clear_line_plot_hover_except(child, keep_id, changed, cleared);
    }
}

