fn part_style_snapshot(style: &PartStyle) -> Value {
    let mut map = Map::new();
    insert_object_if_non_empty(
        &mut map,
        "layout",
        part_layout_style_snapshot(&style.layout),
    );
    insert_object_if_non_empty(&mut map, "visual", visual_style_snapshot(&style.visual));
    insert_object_if_non_empty(&mut map, "text", text_style_snapshot(&style.text));
    if let Some(content) = &style.content {
        map.insert(
            "content".to_string(),
            json!(generated_content_snapshot(content)),
        );
    }
    Value::Object(map)
}

fn generated_content_snapshot(content: &GeneratedContent) -> String {
    match content {
        GeneratedContent::Text(value) => value.clone(),
        GeneratedContent::Attr(name) => format!("attr({name})"),
    }
}

fn insert_object_if_non_empty(map: &mut Map<String, Value>, key: &str, value: Value) {
    if value.as_object().is_some_and(|object| !object.is_empty()) {
        map.insert(key.to_string(), value);
    }
}

fn compact_part_styles_snapshot(
    style: &NodeStyle,
    matched_part_rules: Option<&std::collections::BTreeMap<String, Vec<String>>>,
) -> Value {
    let mut names = std::collections::BTreeSet::new();
    names.extend(style.parts.parts.keys().cloned());
    names.extend(style.parts.hover.keys().cloned());
    names.extend(style.parts.active.keys().cloned());
    names.extend(style.parts.focus.keys().cloned());
    names.extend(style.parts.disabled.keys().cloned());
    names.extend(style.parts.checked.keys().cloned());
    names.extend(style.parts.open.keys().cloned());
    names.extend(style.parts.expanded.keys().cloned());
    names.extend(style.parts.collapsed.keys().cloned());
    names.extend(style.parts.selected.keys().cloned());
    if let Some(matched_part_rules) = matched_part_rules {
        names.extend(matched_part_rules.keys().cloned());
    }

    let mut out = Map::new();
    for name in names {
        let mut part = Map::new();
        if let Some(matched) = matched_part_rules.and_then(|rules| rules.get(&name)) {
            if !matched.is_empty() {
                part.insert("matched_rules".to_string(), json!(matched));
            }
        }
        if let Some(base) = style.parts.parts.get(&name) {
            if let Value::Object(base_map) = part_style_snapshot(base) {
                part.extend(base_map);
            }
        }
        insert_part_state_snapshot(&mut part, "hover", style.parts.hover.get(&name));
        insert_part_state_snapshot(&mut part, "active", style.parts.active.get(&name));
        insert_part_state_snapshot(&mut part, "focus", style.parts.focus.get(&name));
        insert_part_state_snapshot(&mut part, "disabled", style.parts.disabled.get(&name));
        insert_part_state_snapshot(&mut part, "checked", style.parts.checked.get(&name));
        insert_part_state_snapshot(&mut part, "open", style.parts.open.get(&name));
        insert_part_state_snapshot(&mut part, "expanded", style.parts.expanded.get(&name));
        insert_part_state_snapshot(&mut part, "collapsed", style.parts.collapsed.get(&name));
        insert_part_state_snapshot(&mut part, "selected", style.parts.selected.get(&name));
        if !part.is_empty() {
            out.insert(name, Value::Object(part));
        }
    }
    Value::Object(out)
}

fn insert_part_state_snapshot(map: &mut Map<String, Value>, key: &str, style: Option<&PartStyle>) {
    let Some(style) = style else {
        return;
    };
    insert_object_if_non_empty(map, key, part_style_snapshot(style));
}

fn node_style_snapshot(
    style: &NodeStyle,
    matched_part_rules: Option<&std::collections::BTreeMap<String, Vec<String>>>,
) -> Value {
    let mut map = Map::new();
    map.insert("layout".to_string(), layout_style_snapshot(&style.layout));
    map.insert("visual".to_string(), visual_style_snapshot(&style.visual));
    map.insert("text".to_string(), text_style_snapshot(&style.text));
    map.insert("widget".to_string(), widget_style_snapshot(&style.widget));
    insert_object_if_non_empty(
        &mut map,
        "transition",
        transition_style_snapshot(&style.transition),
    );
    insert_object_if_non_empty(
        &mut map,
        "animation",
        animation_style_snapshot(&style.animation),
    );
    insert_object_if_non_empty(
        &mut map,
        "parts",
        compact_part_styles_snapshot(style, matched_part_rules),
    );
    map.insert("hover".to_string(), visual_style_snapshot(&style.hover));
    map.insert("active".to_string(), visual_style_snapshot(&style.active));
    map.insert("focus".to_string(), visual_style_snapshot(&style.focus));
    map.insert(
        "disabled".to_string(),
        visual_style_snapshot(&style.disabled),
    );
    map.insert("checked".to_string(), visual_style_snapshot(&style.checked));
    map.insert("open".to_string(), visual_style_snapshot(&style.open));
    map.insert(
        "expanded".to_string(),
        visual_style_snapshot(&style.expanded),
    );
    map.insert(
        "collapsed".to_string(),
        visual_style_snapshot(&style.collapsed),
    );
    map.insert(
        "selected".to_string(),
        visual_style_snapshot(&style.selected),
    );
    Value::Object(map)
}

fn style_declaration_provenance_snapshot(style: &NodeStyle) -> Value {
    let mut properties = Map::new();
    for (property, candidates) in &style.provenance {
        let Some(winner) = candidates.last() else {
            continue;
        };
        let overridden = candidates
            .iter()
            .take(candidates.len().saturating_sub(1))
            .map(|candidate| style_declaration_candidate_snapshot(candidate))
            .collect::<Vec<_>>();
        properties.insert(
            property.to_string(),
            json!({
                "winner": style_declaration_candidate_snapshot(winner),
                "overridden": overridden,
            }),
        );
    }
    Value::Object(properties)
}

fn style_declaration_candidate_snapshot(
    candidate: &crate::style::StyleDeclarationProvenance,
) -> Value {
    let mut value = Map::new();
    value.insert("origin".to_string(), json!(candidate.origin));
    value.insert(
        "authored_property".to_string(),
        json!(candidate.authored_property),
    );
    if let Some(source_origin) = &candidate.source_origin {
        value.insert("source_origin".to_string(), json!(source_origin));
    }
    if let Some(inherited_from) = &candidate.inherited_from {
        value.insert("inherited_from".to_string(), json!(inherited_from));
    }
    if let Some(widget_type) = &candidate.python_widget_type {
        value.insert("python_widget_type".to_string(), json!(widget_type));
    }
    if let Some(python_class) = &candidate.python_class {
        value.insert("python_class".to_string(), json!(python_class));
    }
    if let Some(construction) = &candidate.construction {
        value.insert("construction".to_string(), json!(construction));
    }
    value.insert("important".to_string(), json!(candidate.important));
    if let Some(selector) = &candidate.selector {
        value.insert("selector".to_string(), json!(selector));
    }
    if let Some(source_value) = &candidate.value {
        value.insert("value".to_string(), source_value.clone());
    }
    if let Some(source_index) = candidate.source_index {
        value.insert("source_index".to_string(), json!(source_index));
    }
    if let Some(line) = candidate.source_line {
        value.insert("line".to_string(), json!(line));
    }
    if let Some(column) = candidate.source_column {
        value.insert("column".to_string(), json!(column));
    }
    if let Some(source_order) = candidate.source_order {
        value.insert("source_order".to_string(), json!(source_order));
    }
    if let Some([ids, classes, types]) = candidate.specificity {
        value.insert(
            "specificity".to_string(),
            json!({"ids": ids, "classes": classes, "types": types}),
        );
    }
    Value::Object(value)
}

fn computed_styles_snapshot(
    root: Option<&WidgetNode>,
    store: &StylesheetStore,
    media: Option<DgMediaEnvironment>,
) -> Value {
    computed_styles_snapshot_with_state(root, store, media, None)
}

fn computed_styles_snapshot_with_state(
    root: Option<&WidgetNode>,
    store: &StylesheetStore,
    media: Option<DgMediaEnvironment>,
    state: Option<&WidgetState>,
) -> Value {
    computed_styles_snapshot_with_state_and_containers(root, store, media, state, None)
}

fn computed_styles_snapshot_with_state_and_containers(
    root: Option<&WidgetNode>,
    store: &StylesheetStore,
    media: Option<DgMediaEnvironment>,
    state: Option<&WidgetState>,
    containers: Option<&DgContainerQueryContext>,
) -> Value {
    let Some(root) = root else {
        return json!({});
    };
    let mut diagnostic_root = root.clone();
    let mut diagnostic_store = store.clone();
    apply_stylesheets_to_tree_for_diagnostics(
        &mut diagnostic_root,
        &mut diagnostic_store,
        media,
        containers,
    );
    let root = &diagnostic_root;
    let store = &diagnostic_store;
    let matched_rules = matched_rule_labels_for_tree_with_media(root, store, media);
    let matched_rule_details = matched_rule_diagnostics_for_tree_with_media(root, store, media);
    let matched_part_rules = matched_part_rule_labels_for_tree_with_media(root, store, media);
    let mut out = Map::new();
    collect_computed_styles_snapshot(
        root,
        store.fallback_theme(),
        &matched_rules,
        &matched_rule_details,
        &matched_part_rules,
        state,
        NativeLayoutFallbackContext::default(),
        &mut out,
    );
    Value::Object(out)
}

fn collect_computed_styles_snapshot(
    node: &WidgetNode,
    fallback_theme: Option<&Theme>,
    matched_rules: &std::collections::BTreeMap<String, Vec<String>>,
    matched_rule_details: &std::collections::BTreeMap<String, Vec<DgMatchedRuleDiagnostic>>,
    matched_part_rules: &std::collections::BTreeMap<
        String,
        std::collections::BTreeMap<String, Vec<String>>,
    >,
    state: Option<&WidgetState>,
    fallback_context: NativeLayoutFallbackContext,
    out: &mut Map<String, Value>,
) {
    let mut snapshot_style = node.style.clone();
    materialize_native_fallback_provenance(
        &mut snapshot_style,
        node,
        fallback_context,
        fallback_theme,
    );
    refresh_live_pane_fallback_provenance(
        &mut snapshot_style,
        node,
        fallback_context,
        state.and_then(|state| state.pane_size(&node.id)),
    );
    let mut node_snapshot = json!({
        "matched_rules": matched_rules.get(&node.id).cloned().unwrap_or_default(),
        "matched_selectors": matched_rule_details.get(&node.id).into_iter().flatten().map(|rule| {
            json!({
                "selector": rule.selector,
                "origin": rule.origin,
                "source_index": rule.source_index,
                "line": rule.source_line,
                "column": rule.source_column,
                "source_order": rule.source_order,
                "specificity": {
                    "ids": rule.specificity.ids,
                    "classes": rule.specificity.classes,
                    "types": rule.specificity.types,
                },
            })
        }).collect::<Vec<_>>(),
        "style": node_style_snapshot(&snapshot_style, matched_part_rules.get(&node.id)),
        "provenance": style_declaration_provenance_snapshot(&snapshot_style),
    });
    if matches!(node.kind, WidgetKind::IconButton | WidgetKind::NavItem) {
        if let Some(requested) = node.props.raw_props.get("icon").and_then(Value::as_str) {
            let custom_resource = node.props.raw_props.get("icon_override_resource");
            let override_name = node
                .props
                .raw_props
                .get("icon_override_name")
                .and_then(Value::as_str);
            let resolution = crate::icons::resolve_builtin_icon(override_name.unwrap_or(requested));
            let source = if custom_resource.is_some() || override_name.is_some() {
                "application"
            } else {
                "builtin"
            };
            let resolved = if custom_resource.is_some() {
                node.props
                    .raw_props
                    .get("icon_override_key")
                    .and_then(Value::as_str)
                    .unwrap_or(requested)
            } else {
                resolution.resolved
            };
            node_snapshot
                .as_object_mut()
                .expect("snapshot object")
                .insert(
                    "icon".to_string(),
                    json!({
                        "requested": requested,
                        "resolved": resolved,
                        "recognized": custom_resource.is_some() || resolution.recognized,
                        "alias": custom_resource.is_none() && resolution.alias,
                        "fallback": custom_resource.is_none() && !resolution.recognized,
                        "source": source,
                        "resource_type": custom_resource
                            .and_then(|resource| resource.get("type"))
                            .and_then(Value::as_str),
                    }),
                );
        }
    }
    out.insert(node.id.clone(), node_snapshot);
    let child_fallback_context = child_layout_fallback_context(node);
    for child in &node.children {
        collect_computed_styles_snapshot(
            child,
            fallback_theme,
            matched_rules,
            matched_rule_details,
            matched_part_rules,
            state,
            child_fallback_context,
            out,
        );
    }
}

fn props_snapshot(node: &WidgetNode) -> Value {
    let props = &node.props;
    let mut snapshot = json!({
        "text": props.text.as_deref(),
        "badge": props.badge.as_deref(),
        "level": props.level.as_deref(),
        "fixed_width": props.fixed_width,
        "fixed_height": props.fixed_height,
        "grid_columns": props.grid_columns,
        "grid_min_column_width": props.grid_min_column_width,
        "grid_template_columns": props.grid_template_columns.as_ref().map(|tracks| {
            tracks.iter().map(grid_track_json).collect::<Vec<_>>()
        }),
        "grid_template_rows": props.grid_template_rows.as_ref().map(|tracks| {
            tracks.iter().map(grid_track_json).collect::<Vec<_>>()
        }),
        "grid_masonry": props.grid_masonry,
        "flow_align": props.flow_align.as_deref(),
        "flow_cross_align": props.flow_cross_align.as_deref(),
        "disabled": props.disabled,
        "expanded": props.expanded,
        "open": props.open,
        "target": props.target.as_deref(),
        "tooltip": props.tooltip.as_deref(),
        "image_path": props.image_path.as_deref(),
        "image_fit": props.image_fit.as_deref(),
        "led_state": props.led_state.as_deref(),
        "led_size": props.led_size,
        "checked": props.checked,
        "toggle": props.toggle,
        "value": props.value,
        "min": props.min,
        "max": props.max,
        "step": props.step,
        "placeholder": props.placeholder.as_deref(),
        "rows": props.rows,
        "wrap": props.wrap,
        "items_count": props.items.len(),
        "route_value": props.route_value.as_deref(),
        "page": props.page.as_deref(),
        "table": {
            "columns": props.table_columns.len(),
            "rows": props.table_rows,
            "resource_id": props.table_resource_id.as_deref(),
            "page_size": props.page_size,
            "sample_rows": props.table_sample_rows,
            "sortable": props.table_sortable,
            "resizable_columns": props.table_resizable_columns,
        },
    });
    if let Value::Object(map) = &mut snapshot {
        map.insert(
            "grid_column_breakpoints".to_string(),
            Value::Array(
                props
                    .grid_column_breakpoints
                    .iter()
                    .map(|rule| json!({ "max_width": rule.max_width, "columns": rule.columns }))
                    .collect(),
            ),
        );
        map.insert("grid_auto_fit".to_string(), json!(props.grid_auto_fit));
        map.insert(
            "grid_balance_last_row".to_string(),
            json!(props.grid_balance_last_row),
        );
        map.insert(
            "orientation".to_string(),
            json!(props.orientation.as_deref()),
        );
        map.insert("gutter_size".to_string(), json!(props.gutter_size));
        map.insert("pane_size".to_string(), json!(props.pane_size));
        map.insert("pane_min_size".to_string(), json!(props.pane_min_size));
        map.insert("pane_max_size".to_string(), json!(props.pane_max_size));
        map.insert("pane_flex".to_string(), json!(props.pane_flex));
        map.insert(
            "extension_type".to_string(),
            json!(props.extension_type.as_deref()),
        );
        map.insert("intrinsic_width".to_string(), json!(props.intrinsic_width));
        map.insert(
            "intrinsic_height".to_string(),
            json!(props.intrinsic_height),
        );
    }
    if node.kind == WidgetKind::HtmlReport {
        if let Value::Object(map) = &mut snapshot {
            map.insert(
                "html_report".to_string(),
                json!({
                    "path": props.html_report_path.as_deref(),
                    "base_dir": props.html_report_base_dir.as_deref(),
                    "allow_remote": props.html_report_allow_remote,
                    "allow_scripts": props.html_report_allow_scripts,
                    "external_fallback": props.html_report_external_fallback,
                    "inline_bytes": props.html_report_html.as_ref().map(|html| html.len()),
                }),
            );
        }
    }
    if node.kind == WidgetKind::Histogram {
        if let Value::Object(map) = &mut snapshot {
            map.insert(
                "histogram".to_string(),
                json!({
                    "bins": props.histogram.counts.len(),
                    "edges": props.histogram.edges.len(),
                    "mode": props.histogram.mode.as_str(),
                    "cumulative": props.histogram.cumulative,
                    "x_label": props.histogram.x_label.as_deref(),
                    "y_label": props.histogram.y_label.as_deref(),
                    "show_grid": props.histogram.show_grid,
                    "show_axes": props.histogram.show_axes,
                    "show_ticks": props.histogram.show_ticks,
                    "show_toolbar": props.histogram.show_toolbar,
                    "tick_count": props.histogram.tick_count,
                    "auto_fit": props.histogram.auto_fit,
                    "interaction": props.histogram.interaction.as_str(),
                }),
            );
        }
    }
    if node.kind == WidgetKind::BarChart {
        if let Value::Object(map) = &mut snapshot {
            map.insert(
                "bar_chart".to_string(),
                json!({
                    "categories": props.bar_chart.labels.len(),
                    "series": props.bar_chart.series.len(),
                    "aggregate": props.bar_chart.aggregate.as_str(),
                    "orientation": props.bar_chart.orientation.as_str(),
                    "x_label": props.bar_chart.x_label.as_deref(),
                    "y_label": props.bar_chart.y_label.as_deref(),
                    "show_grid": props.bar_chart.show_grid,
                    "show_axes": props.bar_chart.show_axes,
                    "show_ticks": props.bar_chart.show_ticks,
                    "show_toolbar": props.bar_chart.show_toolbar,
                    "tick_count": props.bar_chart.tick_count,
                    "auto_fit": props.bar_chart.auto_fit,
                }),
            );
        }
    }
    if node.kind == WidgetKind::LinePlot {
        let line_plot_series = props
            .line_plot_series
            .iter()
            .map(|series| {
                json!({
                    "label": series.label.as_deref(),
                    "line_style": series.line_style,
                    "points": series.logical_len(),
                    "stored_points": series.points.len(),
                    "front_offset": series.front_offset,
                    "y_blocks": series.y_blocks.len(),
                    "declared_points": series.declared_point_count,
                })
            })
            .collect::<Vec<_>>();
        if let Value::Object(map) = &mut snapshot {
            map.insert(
                "line_plot".to_string(),
                json!({
                "x_label": props.line_plot_x_label.as_deref(),
                "y_label": props.line_plot_y_label.as_deref(),
                "show_grid": props.line_plot_show_grid,
                "show_axes": props.line_plot_show_axes,
                "show_ticks": props.line_plot_show_ticks,
                "show_legend": props.line_plot_show_legend,
                "legend_position": props.line_plot_legend_position,
                "tick_count": props.line_plot_tick_count,
                "window_size": props.line_plot_window_size,
                "series": line_plot_series,
                }),
            );
        }
    }
    snapshot
}

fn node_snapshot(node: &WidgetNode) -> Value {
    json!({
        "id": &node.id,
        "type": widget_kind_name(&node.kind),
        "render_kind": widget_kind_name(&node.kind),
        "css_types": &node.css_types,
        "key": node.key.as_deref(),
        "class": node.class_name.as_deref(),
        "props": props_snapshot(node),
        "default_style": node_style_snapshot(&node.default_style, None),
        "inline_style": &node.style_json,
        "style": &node.style_json,
        "children": node.children.iter().map(node_snapshot).collect::<Vec<_>>(),
    })
}

fn layout_diagnostic_issues(
    root: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    state: Option<&WidgetState>,
) -> HashMap<String, Vec<Value>> {
    let mut issues = HashMap::<String, Vec<Value>>::new();
    let Some(root_rect) = layout.rects.get(&root.id).copied() else {
        return issues;
    };
    let scale_factor = layout.scale_factor.max(0.001);
    let root_layout = &root.style.layout;
    for (axis, available, required) in [
        (
            "x",
            root_rect.w,
            snapshot_layout_length_px(
                root_layout.min_width_value,
                root_layout.min_width,
                scale_factor,
                root_rect.w,
            ),
        ),
        (
            "y",
            root_rect.h,
            snapshot_layout_length_px(
                root_layout.min_height_value,
                root_layout.min_height,
                scale_factor,
                root_rect.h,
            ),
        ),
    ] {
        let Some(required) = required else {
            continue;
        };
        if required > available + 0.5 {
            let message = format!(
                "below-minimum-viewport-{axis}: {} {} requires {required:.1}px but viewport provides {available:.1}px",
                root.id,
                widget_kind_name(&root.kind)
            );
            issues.entry(root.id.clone()).or_default().push(json!({
                "code": "below-minimum-viewport",
                "severity": "error",
                "axis": axis,
                "widget_id": &root.id,
                "widget_type": widget_kind_name(&root.kind),
                "parent_id": Value::Null,
                "parent_type": Value::Null,
                "rect": rect_json(root_rect),
                "clip": rect_json(layout.clips.get(&root.id).copied().unwrap_or(root_rect)),
                "available": available,
                "required": required,
                "reason": "viewport is smaller than the root's declared minimum",
                "message": message,
            }));
        }
    }

    let root_scrolls_x = snapshot_axis_bounded(root, "x");
    let root_scrolls_y = snapshot_axis_bounded(root, "y");
    let mut reported_x = root_scrolls_x;
    let mut reported_y = root_scrolls_y;
    collect_unreachable_root_overflow(
        root,
        layout,
        &root.id,
        widget_kind_name(&root.kind),
        root_rect,
        root_scrolls_x,
        root_scrolls_y,
        &mut reported_x,
        &mut reported_y,
        &mut issues,
    );
    collect_clip_diagnostic_issues(root, None, false, false, layout, state, &mut issues);
    collect_scroll_diagnostic_issues(root, layout, &mut issues);
    issues
}

fn collect_scroll_diagnostic_issues(
    node: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    issues: &mut HashMap<String, Vec<Value>>,
) {
    let Some(viewport) = layout.rects.get(&node.id).copied() else {
        return;
    };
    for child in &node.children {
        if !snapshot_normal_flow_child(child) {
            continue;
        }
        let Some(child_rect) = layout.rects.get(&child.id).copied() else {
            continue;
        };
        for (axis, outside, available, required, scroll_range) in [
            (
                "x",
                child_rect.x < viewport.x - 0.5
                    || child_rect.x + child_rect.w > viewport.x + viewport.w + 0.5,
                viewport.w,
                (child_rect.x + child_rect.w).max(viewport.x + viewport.w)
                    - child_rect.x.min(viewport.x),
                layout.scroll_max_x.get(&node.id).copied().unwrap_or(0.0),
            ),
            (
                "y",
                child_rect.y < viewport.y - 0.5
                    || child_rect.y + child_rect.h > viewport.y + viewport.h + 0.5,
                viewport.h,
                (child_rect.y + child_rect.h).max(viewport.y + viewport.h)
                    - child_rect.y.min(viewport.y),
                layout.scroll_max_y.get(&node.id).copied().unwrap_or(0.0),
            ),
        ] {
            if !outside {
                continue;
            }
            let overflow = snapshot_axis_overflow(node, axis);
            let code_and_reason = match overflow {
                Some(OverflowStyle::Auto | OverflowStyle::Scroll) if scroll_range <= 0.5 => Some((
                    "unreachable-scroll-content",
                    "content exceeds a scrolling viewport but the axis has no usable scroll range",
                )),
                Some(OverflowStyle::Hidden) if node.kind == WidgetKind::ScrollArea => Some((
                    "disabled-axis-overflow",
                    "ScrollArea content exceeds an axis explicitly disabled by its axis policy",
                )),
                _ => None,
            };
            let Some((code, reason)) = code_and_reason else {
                continue;
            };
            let clip = layout.clips.get(&node.id).copied().unwrap_or(viewport);
            let message = format!(
                "{code}-{axis}: {} {} contains {} {} beyond its {axis}-axis viewport",
                node.id,
                widget_kind_name(&node.kind),
                child.id,
                widget_kind_name(&child.kind),
            );
            let duplicate = issues.get(&node.id).is_some_and(|existing| {
                existing
                    .iter()
                    .any(|issue| issue["code"] == code && issue["axis"] == axis)
            });
            if !duplicate {
                issues.entry(node.id.clone()).or_default().push(json!({
                    "code": code,
                    "severity": "error",
                    "axis": axis,
                    "widget_id": &node.id,
                    "widget_type": widget_kind_name(&node.kind),
                    "subject_id": &child.id,
                    "subject_type": widget_kind_name(&child.kind),
                    "parent_id": Value::Null,
                    "parent_type": Value::Null,
                    "rect": rect_json(viewport),
                    "clip": rect_json(clip),
                    "available": available,
                    "required": required,
                    "scroll_range": scroll_range,
                    "reason": reason,
                    "message": message,
                }));
            }
        }
    }
    for child in &node.children {
        collect_scroll_diagnostic_issues(child, layout, issues);
    }
}

fn collect_clip_diagnostic_issues(
    node: &WidgetNode,
    parent: Option<&WidgetNode>,
    parent_fully_clipped: bool,
    inside_scroll_owner: bool,
    layout: &crate::layout::LayoutResult,
    state: Option<&WidgetState>,
    issues: &mut HashMap<String, Vec<Value>>,
) {
    let Some(rect) = layout.rects.get(&node.id).copied() else {
        return;
    };
    let clip = layout.clips.get(&node.id).copied().unwrap_or(rect);
    let has_area = rect.w > 0.5 && rect.h > 0.5;
    let fully_clipped = has_area && (clip.w <= 0.5 || clip.h <= 0.5);
    let exempt_empty_clip = matches!(node.kind, WidgetKind::Spacer | WidgetKind::Separator);
    let parent_id = parent.map(|parent| parent.id.as_str());
    let parent_kind = parent.map(|parent| widget_kind_name(&parent.kind));

    if let Some(parent) = parent {
        collect_dimension_contract_issues(node, parent, rect, layout, issues);

        let main_axis = match parent.kind {
            WidgetKind::HLayout => Some(("x", rect.w, "width")),
            WidgetKind::VLayout => Some(("y", rect.h, "height")),
            _ => None,
        };
        if let Some((axis, allocated, dimension)) = main_axis {
            let required_flex = node.style.layout.flex_grow.unwrap_or(0.0) > 0.0
                && !matches!(node.kind, WidgetKind::Spacer | WidgetKind::Separator)
                && !node.children.is_empty();
            let required_minimum = match axis {
                "x" => node.style.layout.min_width,
                "y" => node.style.layout.min_height,
                _ => None,
            }
            .filter(|minimum| *minimum > 0.5);
            let below_required_minimum =
                required_minimum.is_some_and(|minimum| allocated + 0.5 < minimum);
            if required_flex && (allocated <= 0.5 || below_required_minimum) {
                let message = format!(
                    "flex-allocation-failure-{axis}: {} {} requested flexible space but received only {:.1} usable {dimension} inside {} {}",
                    node.id,
                    widget_kind_name(&node.kind),
                    allocated,
                    parent.id,
                    widget_kind_name(&parent.kind),
                );
                issues.entry(node.id.clone()).or_default().push(json!({
                    "code": "flex-allocation-failure",
                    "severity": "error",
                    "axis": axis,
                    "widget_id": &node.id,
                    "widget_type": widget_kind_name(&node.kind),
                    "parent_id": &parent.id,
                    "parent_type": widget_kind_name(&parent.kind),
                    "rect": rect_json(rect),
                    "clip": rect_json(clip),
                    "required_minimum": required_minimum,
                    "reason": if allocated <= 0.5 {
                        "non-empty flexible region received no main-axis allocation"
                    } else {
                        "flexible region fell below its declared main-axis minimum"
                    },
                    "message": message,
                }));
            }
        }
    }

    // Report only the first empty clip in a clipped subtree. Descendants inherit
    // the same structural failure and would otherwise turn one bad boundary
    // into dozens of redundant errors.
    if fully_clipped && !parent_fully_clipped && !inside_scroll_owner && !exempt_empty_clip {
        let message = format!(
            "empty-paint-clip: {} {} has rect ({:.1}, {:.1}, {:.1}, {:.1}) but final clip ({:.1}, {:.1}, {:.1}, {:.1}) is empty",
            node.id,
            widget_kind_name(&node.kind),
            rect.x,
            rect.y,
            rect.w,
            rect.h,
            clip.x,
            clip.y,
            clip.w,
            clip.h,
        );
        issues.entry(node.id.clone()).or_default().push(json!({
            "code": "empty-paint-clip",
            "severity": "error",
            "widget_id": &node.id,
            "widget_type": widget_kind_name(&node.kind),
            "parent_id": parent_id,
            "parent_type": parent_kind,
            "rect": rect_json(rect),
            "clip": rect_json(clip),
            "reason": "non-zero layout rect has no final paintable area",
            "message": message,
        }));
    }

    let disabled = node.props.disabled || state.is_some_and(|state| state.is_disabled(&node.id));
    if fully_clipped && !inside_scroll_owner && is_interactive_node(node) && !disabled {
        let message = format!(
            "fully-clipped-interactive: enabled {} {} is entirely outside its final paint clip",
            node.id,
            widget_kind_name(&node.kind),
        );
        issues.entry(node.id.clone()).or_default().push(json!({
            "code": "fully-clipped-interactive",
            "severity": "error",
            "widget_id": &node.id,
            "widget_type": widget_kind_name(&node.kind),
            "parent_id": parent_id,
            "parent_type": parent_kind,
            "rect": rect_json(rect),
            "clip": rect_json(clip),
            "reason": "enabled interactive widget has no reachable painted area",
            "message": message,
        }));
    }

    let descendants_inside_scroll_owner = inside_scroll_owner
        || matches!(
            snapshot_axis_overflow(node, "x"),
            Some(OverflowStyle::Auto | OverflowStyle::Scroll)
        )
        || matches!(
            snapshot_axis_overflow(node, "y"),
            Some(OverflowStyle::Auto | OverflowStyle::Scroll)
        );
    for child in &node.children {
        collect_clip_diagnostic_issues(
            child,
            Some(node),
            fully_clipped,
            descendants_inside_scroll_owner,
            layout,
            state,
            issues,
        );
    }
}

fn collect_dimension_contract_issues(
    node: &WidgetNode,
    parent: &WidgetNode,
    rect: Rect,
    layout: &crate::layout::LayoutResult,
    issues: &mut HashMap<String, Vec<Value>>,
) {
    let Some(parent_rect) = layout.rects.get(&parent.id).copied() else {
        return;
    };
    let scale_factor = layout.scale_factor.max(0.001);
    let style = &node.style.layout;
    for (axis, resolved, parent_axis, minimum, maximum) in [
        (
            "x",
            rect.w,
            parent_rect.w,
            snapshot_layout_length_px(
                style.min_width_value,
                style.min_width,
                scale_factor,
                parent_rect.w,
            ),
            snapshot_layout_length_px(
                style.max_width_value,
                style.max_width,
                scale_factor,
                parent_rect.w,
            ),
        ),
        (
            "y",
            rect.h,
            parent_rect.h,
            snapshot_layout_length_px(
                style.min_height_value,
                style.min_height,
                scale_factor,
                parent_rect.h,
            ),
            snapshot_layout_length_px(
                style.max_height_value,
                style.max_height,
                scale_factor,
                parent_rect.h,
            ),
        ),
    ] {
        // Layout rectangles ultimately land on physical pixels. Fractional
        // logical minima (notably at 1.25x and 1.5x) can therefore resolve up
        // to one physical pixel below their mathematical value without
        // violating the effective size contract.
        const PHYSICAL_PIXEL_QUANTIZATION_TOLERANCE: f32 = 1.0;
        let violation = if minimum
            .is_some_and(|minimum| resolved + PHYSICAL_PIXEL_QUANTIZATION_TOLERANCE < minimum)
        {
            Some(("minimum", minimum.unwrap()))
        } else if maximum
            .is_some_and(|maximum| resolved > maximum + PHYSICAL_PIXEL_QUANTIZATION_TOLERANCE)
        {
            Some(("maximum", maximum.unwrap()))
        } else {
            None
        };
        let Some((contract, expected)) = violation else {
            continue;
        };
        let clip = layout.clips.get(&node.id).copied().unwrap_or(rect);
        let message = format!(
            "invalid-min-max-resolution-{axis}: {} {} resolved to {resolved:.1}px, violating {contract} {expected:.1}px",
            node.id,
            widget_kind_name(&node.kind),
        );
        issues.entry(node.id.clone()).or_default().push(json!({
            "code": "invalid-min-max-resolution",
            "severity": "error",
            "axis": axis,
            "widget_id": &node.id,
            "widget_type": widget_kind_name(&node.kind),
            "parent_id": &parent.id,
            "parent_type": widget_kind_name(&parent.kind),
            "rect": rect_json(rect),
            "clip": rect_json(clip),
            "resolved": resolved,
            "parent_available": parent_axis,
            "contract": contract,
            "expected": expected,
            "reason": format!("resolved {axis}-axis size violates declared {contract}"),
            "message": message,
        }));
    }
}

fn snapshot_layout_length_px(
    value: Option<LayoutLength>,
    legacy: Option<f32>,
    scale_factor: f32,
    parent_axis: f32,
) -> Option<f32> {
    match value {
        Some(LayoutLength::LogicalPx(value)) => Some(value * scale_factor),
        Some(LayoutLength::Percent(value)) => Some(parent_axis * value / 100.0),
        Some(LayoutLength::Calc(value)) => {
            Some(parent_axis * value.percent / 100.0 + value.px * scale_factor)
        }
        Some(LayoutLength::Auto) => None,
        None => legacy.map(|value| value * scale_factor),
    }
    .filter(|value| value.is_finite() && *value >= 0.0)
}

#[allow(clippy::too_many_arguments)]
fn collect_unreachable_root_overflow(
    node: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    root_id: &str,
    root_type: &str,
    root_rect: Rect,
    inherited_scroll_x: bool,
    inherited_scroll_y: bool,
    reported_x: &mut bool,
    reported_y: &mut bool,
    issues: &mut HashMap<String, Vec<Value>>,
) {
    let owns_scroll_x = inherited_scroll_x || snapshot_axis_bounded(node, "x");
    let owns_scroll_y = inherited_scroll_y || snapshot_axis_bounded(node, "y");
    for child in &node.children {
        if !snapshot_normal_flow_child(child) {
            continue;
        }
        let Some(rect) = layout.rects.get(&child.id).copied() else {
            continue;
        };
        for (axis, owned, reported, outside, required, available) in [
            (
                "x",
                owns_scroll_x,
                &mut *reported_x,
                rect.x < root_rect.x - 0.5 || rect.x + rect.w > root_rect.x + root_rect.w + 0.5,
                (rect.x + rect.w).max(root_rect.x + root_rect.w) - rect.x.min(root_rect.x),
                root_rect.w,
            ),
            (
                "y",
                owns_scroll_y,
                &mut *reported_y,
                rect.y < root_rect.y - 0.5 || rect.y + rect.h > root_rect.y + root_rect.h + 0.5,
                (rect.y + rect.h).max(root_rect.y + root_rect.h) - rect.y.min(root_rect.y),
                root_rect.h,
            ),
        ] {
            if outside && !owned && !*reported {
                *reported = true;
                let message = format!(
                    "unreachable-root-overflow-{axis}: {} {} clips {} {} with no scroll owner",
                    root_id,
                    root_type,
                    child.id,
                    widget_kind_name(&child.kind)
                );
                issues.entry(root_id.to_string()).or_default().push(json!({
                    "code": "unreachable-root-overflow",
                    "severity": "error",
                    "axis": axis,
                    "widget_id": root_id,
                    "widget_type": root_type,
                    "parent_id": Value::Null,
                    "parent_type": Value::Null,
                    "rect": rect_json(root_rect),
                    "clip": rect_json(layout.clips.get(root_id).copied().unwrap_or(root_rect)),
                    "available": available,
                    "required": required,
                    "subject_id": &child.id,
                    "subject_type": widget_kind_name(&child.kind),
                    "reason": "normal-flow content exceeds the root viewport without a scroll owner",
                    "message": message,
                }));
            }
        }
        collect_unreachable_root_overflow(
            child,
            layout,
            root_id,
            root_type,
            root_rect,
            owns_scroll_x,
            owns_scroll_y,
            reported_x,
            reported_y,
            issues,
        );
    }
}

fn snapshot_axis_bounded(node: &WidgetNode, axis: &str) -> bool {
    matches!(
        snapshot_axis_overflow(node, axis),
        Some(OverflowStyle::Hidden | OverflowStyle::Auto | OverflowStyle::Scroll)
    )
}

fn snapshot_axis_overflow(node: &WidgetNode, axis: &str) -> Option<OverflowStyle> {
    if axis == "x" {
        node.style.layout.overflow_x.or(node.style.layout.overflow)
    } else {
        node.style
            .layout
            .overflow_y
            .or(node.style.layout.overflow)
            .or_else(|| (node.kind == WidgetKind::ScrollArea).then_some(OverflowStyle::Auto))
    }
}

fn snapshot_normal_flow_child(node: &WidgetNode) -> bool {
    !matches!(
        node.style.layout.position,
        Some(PositionStyle::Absolute | PositionStyle::Fixed)
    ) && !matches!(
        node.kind,
        WidgetKind::Modal | WidgetKind::Tooltip | WidgetKind::Toast | WidgetKind::ContextMenu
    )
}

fn layout_snapshot(
    layout: Option<&crate::layout::LayoutResult>,
    root: Option<&WidgetNode>,
) -> Value {
    layout_snapshot_with_context(layout, root, None, None)
}

fn layout_snapshot_with_context(
    layout: Option<&crate::layout::LayoutResult>,
    root: Option<&WidgetNode>,
    theme: Option<&Theme>,
    state: Option<&WidgetState>,
) -> Value {
    let Some(layout) = layout else {
        return json!({});
    };
    let mut rects = Map::new();
    for (id, rect) in &layout.rects {
        rects.insert(id.clone(), rect_json(*rect));
    }
    let mut clips = Map::new();
    for (id, rect) in &layout.clips {
        clips.insert(id.clone(), rect_json(*rect));
    }
    let mut paint_clips = Map::new();
    for (id, rect) in &layout.paint_clips {
        paint_clips.insert(id.clone(), rect_json(*rect));
    }
    let resolved_grids = layout
        .resolved_grid_tracks
        .iter()
        .map(|(id, tracks)| {
            (
                id.clone(),
                json!({
                    "column_count": tracks.column_count,
                    "column_widths": tracks.column_widths,
                }),
            )
        })
        .collect::<Map<String, Value>>();
    let semantic_issues = root
        .map(|root| layout_diagnostic_issues(root, layout, state))
        .unwrap_or_default();
    let mut inspection = Map::new();
    if let (Some(root), Some(theme)) = (root, theme) {
        collect_layout_inspection_snapshot(
            root,
            None,
            layout,
            theme,
            &semantic_issues,
            &mut inspection,
        );
    }
    let mut dynamic_geometry = Map::new();
    if let (Some(root), Some(theme)) = (root, theme) {
        collect_dynamic_geometry_snapshot(root, layout, theme, state, None, &mut dynamic_geometry);
    }
    let mut diagnostics = Map::new();
    for (id, rect) in &layout.rects {
        let clip = layout.clips.get(id).copied().unwrap_or(*rect);
        let overflow_left = (clip.x - rect.x).max(0.0);
        let overflow_top = (clip.y - rect.y).max(0.0);
        let overflow_right = ((rect.x + rect.w) - (clip.x + clip.w)).max(0.0);
        let overflow_bottom = ((rect.y + rect.h) - (clip.y + clip.h)).max(0.0);
        diagnostics.insert(
            id.clone(),
            json!({
                "resolved": {
                    "x": rect.x,
                    "y": rect.y,
                    "width": rect.w,
                    "height": rect.h,
                },
                "available": {
                    "x": clip.x,
                    "y": clip.y,
                    "width": clip.w,
                    "height": clip.h,
                },
                "overflow": {
                    "left": overflow_left,
                    "top": overflow_top,
                    "right": overflow_right,
                    "bottom": overflow_bottom,
                    "width": overflow_left + overflow_right,
                    "height": overflow_top + overflow_bottom,
                },
                "scroll_range": {
                    "x": layout.scroll_max_x.get(id).copied().unwrap_or(0.0),
                    "y": layout.scroll_max_y.get(id).copied().unwrap_or(0.0),
                },
                "dynamic_geometry": dynamic_geometry.get(id).cloned().unwrap_or(Value::Null),
                "issues": semantic_issues.get(id).cloned().unwrap_or_default(),
                "inspection": inspection.get(id).cloned().unwrap_or(Value::Null),
            }),
        );
    }
    json!({
        "schema_version": 1,
        "rects": Value::Object(rects),
        "clips": Value::Object(clips),
        "paint_clips": Value::Object(paint_clips),
        "resolved_grids": Value::Object(resolved_grids),
        "diagnostics": Value::Object(diagnostics),
        "scroll_x": &layout.scroll_x,
        "scroll_y": &layout.scroll_y,
        "scroll_max_x": &layout.scroll_max_x,
        "scroll_max_y": &layout.scroll_max_y,
        "reconciliation": {
            "iterations": layout.reconciliation_iterations,
            "converged": layout.reconciliation_converged,
        },
    })
}

fn collect_layout_inspection_snapshot(
    node: &WidgetNode,
    parent: Option<&WidgetNode>,
    layout: &crate::layout::LayoutResult,
    theme: &Theme,
    issues: &HashMap<String, Vec<Value>>,
    out: &mut Map<String, Value>,
) {
    let Some(rect) = layout.rects.get(&node.id).copied() else {
        return;
    };
    let sf = layout.scale_factor.max(0.001);
    let parent_rect = parent
        .and_then(|parent| layout.rects.get(&parent.id).copied())
        .unwrap_or(rect);
    let (intrinsic_width, intrinsic_height) = debug_intrinsic_size_lp(node, theme);
    let (semantic_width, semantic_height) = debug_semantic_minimum_lp(node, theme);
    let preferred_width = snapshot_layout_length_px(
        node.style.layout.width_value,
        node.style.layout.width.or(node.props.fixed_width),
        sf,
        parent_rect.w,
    );
    let preferred_height = snapshot_layout_length_px(
        node.style.layout.height_value,
        node.style.layout.height.or(node.props.fixed_height),
        sf,
        parent_rect.h,
    );
    let parent_direction = parent.and_then(|parent| parent.style.layout.flex_direction);
    let (flex_axis, allocated_main) = match parent_direction {
        Some(FlexDirectionStyle::Row | FlexDirectionStyle::RowReverse) => ("x", rect.w),
        _ => ("y", rect.h),
    };
    let node_issues = issues.get(&node.id).cloned().unwrap_or_default();
    let structural = node_issues
        .iter()
        .filter(|issue| issue.get("severity").and_then(Value::as_str) != Some("advisory"))
        .cloned()
        .collect::<Vec<_>>();
    let advisories = node_issues
        .iter()
        .filter(|issue| {
            matches!(
                issue.get("severity").and_then(Value::as_str),
                Some("advisory" | "warning")
            )
        })
        .cloned()
        .collect::<Vec<_>>();
    let scroll_axis = |axis: &str| {
        let overflow = snapshot_axis_overflow(node, axis);
        let range = if axis == "x" {
            layout.scroll_max_x.get(&node.id).copied().unwrap_or(0.0)
        } else {
            layout.scroll_max_y.get(&node.id).copied().unwrap_or(0.0)
        };
        let offset = if axis == "x" {
            layout.scroll_x.get(&node.id).copied().unwrap_or(0.0)
        } else {
            layout.scroll_y.get(&node.id).copied().unwrap_or(0.0)
        };
        json!({
            "policy": overflow.map(overflow_style_name).unwrap_or("visible"),
            "owns_scroll": matches!(overflow, Some(OverflowStyle::Auto | OverflowStyle::Scroll)),
            "offset": offset,
            "range": range,
        })
    };
    out.insert(
        node.id.clone(),
        json!({
            "sizing": {
                "intrinsic": {
                    "width": intrinsic_width.map(|value| value * sf),
                    "height": intrinsic_height.map(|value| value * sf),
                    "units": "physical-px",
                },
                "preferred": {
                    "width": preferred_width,
                    "height": preferred_height,
                    "units": "physical-px",
                },
                "semantic_minimum": {
                    "width": semantic_width * sf,
                    "height": semantic_height * sf,
                    "units": "physical-px",
                },
            },
            "flex_allocation": {
                "axis": flex_axis,
                "allocated_main": allocated_main,
                "grow": node.style.layout.flex_grow.unwrap_or(0.0),
                "shrink": node.style.layout.flex_shrink.unwrap_or(1.0),
                "basis": snapshot_layout_length_px(
                    node.style.layout.flex_basis_value,
                    node.style.layout.flex_basis,
                    sf,
                    if flex_axis == "x" { parent_rect.w } else { parent_rect.h },
                ),
            },
            "final_rect": {
                "x": rect.x,
                "y": rect.y,
                "width": rect.w,
                "height": rect.h,
            },
            "final_paint_clip": layout.paint_clips.get(&node.id).copied().map(rect_json),
            "scroll_ownership": {
                "x": scroll_axis("x"),
                "y": scroll_axis("y"),
            },
            "structural_diagnostics": structural,
            "usability_advisories": advisories,
        }),
    );
    for child in &node.children {
        collect_layout_inspection_snapshot(child, Some(node), layout, theme, issues, out);
    }
}

fn collect_dynamic_geometry_snapshot(
    node: &WidgetNode,
    layout: &crate::layout::LayoutResult,
    theme: &Theme,
    state: Option<&WidgetState>,
    parent_height: Option<f32>,
    out: &mut Map<String, Value>,
) {
    let rect = layout.rects.get(&node.id).copied();
    if let Some(rect) = rect {
        if node.kind == WidgetKind::Label && label_wraps(node) {
            let measured = node
                .props
                .text
                .as_deref()
                .filter(|text| !text.is_empty())
                .map(|text| {
                    measure_wrapped_text_for_layout(
                        text,
                        &node.style.text,
                        theme,
                        (rect.w / layout.scale_factor.max(f32::EPSILON)).max(1.0),
                    )
                    .height
                        * layout.scale_factor
                })
                .unwrap_or(0.0);
            out.insert(
                node.id.clone(),
                json!({
                    "kind": "wrapped-text",
                    "source": "layout-measurement",
                    "axis": "height",
                    "available_width": rect.w,
                    "measured_content_height": measured,
                    "resolved_height": rect.h,
                }),
            );
        } else if node.kind == WidgetKind::TreeNode {
            let expanded = !node.children.is_empty()
                && state
                    .and_then(|state| state.expanded.get(&node.id).copied())
                    .or(node.props.expanded)
                    .unwrap_or(false);
            let row_height =
                tree_node_row_height_for_style(node, theme, layout.scale_factor, parent_height)
                    .min(rect.h.max(0.0));
            out.insert(
                node.id.clone(),
                json!({
                    "kind": "stateful-tree-row",
                    "source": "widget-state-and-content",
                    "axis": "height",
                    "expanded": expanded,
                    "child_count": node.children.len(),
                    "row_height": row_height,
                    "content_height": if expanded { (rect.h - row_height).max(0.0) } else { 0.0 },
                    "resolved_height": rect.h,
                }),
            );
        }
    }
    let child_parent_height = rect.map(|rect| rect.h).or(parent_height);
    for child in &node.children {
        collect_dynamic_geometry_snapshot(child, layout, theme, state, child_parent_height, out);
    }
}

fn widget_state_snapshot(state: Option<&WidgetState>) -> Value {
    let Some(state) = state else {
        return json!(null);
    };
    let tables: Map<String, Value> = state
        .tables
        .iter()
        .map(|(id, table)| {
            let sort = table.sort.map(|(target, direction)| {
                json!({
                    "target": match target {
                        TableSortColumn::Index => "index",
                        TableSortColumn::Data(_) => "column",
                    },
                    "column": target.data_index(),
                    "direction": match direction {
                        crate::events::SortDirection::Asc => "asc",
                        crate::events::SortDirection::Desc => "desc",
                    },
                })
            });
            (
                id.clone(),
                json!({
                    "columns": table.columns.len(),
                    "rows": table.rows,
                    "resource_id": table.resource_id.as_deref(),
                    "page_size": table.page_size,
                    "scroll_row": table.scroll_row,
                    "scroll_col": table.scroll_col,
                    "selected": table.selected.map(|(row, col)| json!([row, col])),
                    "selected_cell": table.selected.map(|(row, col)| json!({
                        "row_index": row,
                        "column_index": col,
                        "column": table.columns.get(col).map(String::as_str).unwrap_or(""),
                    })),
                    "sort": sort,
                    "column_widths": &table.column_widths,
                }),
            )
        })
        .collect();
    json!({
        "checked": &state.checked,
        "selectable_selected": &state.selectable_selected,
        "expanded": &state.expanded,
        "float_val": &state.float_val,
        "range_val": &state.range_val,
        "pane_sizes": &state.pane_sizes,
        "float_range": &state.float_range,
        "text_val": &state.text_val,
        "text_cursor": &state.text_cursor,
        "text_scroll_x": &state.text_scroll_x,
        "text_scroll_y": &state.text_scroll_y,
        "container_scroll_x": &state.container_scroll_x,
        "container_scroll_y": &state.container_scroll_y,
        "dropdown_index": &state.dropdown_index,
        "dropdown_items_count": state.dropdown_items.iter().map(|(id, items)| (id.clone(), json!(items.len()))).collect::<Map<_, _>>(),
        "disabled": state.disabled.iter().cloned().collect::<Vec<_>>(),
        "focus_order": &state.focus_order,
        "focused": state.focused.as_deref(),
        "focus_t": &state.focus_t,
        "hovered": state.hovered.as_deref(),
        "hover_t": &state.hover_t,
        "drag_source": state.drag_source.as_deref(),
        "drag_hover_target": state.drag_hover_target.as_deref(),
        "drag_kind": state.drag_kind.as_deref(),
        "drag_pos": state.drag_pos,
        "checked_t": &state.checked_t,
        "active_t": &state.active_t,
        "open_t": &state.open_t,
        "selected_t": &state.selected_t,
        "expanded_t": &state.expanded_t,
        "pressed": state.pressed.as_deref(),
        "open_dropdown": state.open_dropdown.as_deref(),
        "dropdown_hover": state.dropdown_hover.as_ref().map(|(id, idx)| json!({"id": id, "index": idx})),
        "open_menu": state.open_menu.as_deref(),
        "open_context_menu": state.open_context_menu.as_deref(),
        "context_menu_pos": state.context_menu_pos,
        "menu_items_count": state.menu_items.iter().map(|(id, items)| (id.clone(), json!(items.len()))).collect::<Map<_, _>>(),
        "context_targets": &state.context_targets,
        "active_tabs": &state.active_tabs,
        "active_pages": &state.active_pages,
        "tables": Value::Object(tables),
    })
}

fn theme_snapshot(theme: &Theme) -> Value {
    json!({
        "background": color_json(theme.background),
        "surface": color_json(theme.surface),
        "surface_alt": color_json(theme.surface_alt),
        "text": color_json(theme.text),
        "muted_text": color_json(theme.muted_text),
        "accent": color_json(theme.accent),
        "border": color_json(theme.border),
        "danger": color_json(theme.danger),
        "warning": color_json(theme.warning),
        "success": color_json(theme.success),
        "focus": color_json(theme.focus),
        "disabled": color_json(theme.disabled),
        "radius": theme.radius,
        "spacing": theme.spacing,
        "font_size": theme.font_size,
        "font_family": theme.font_family,
        "monospace_font_family": theme.monospace_font_family,
        "base_line_height": theme.base_line_height,
        "control_height": theme.control_height,
        "compact_control_height": theme.compact_control_height,
        "default_border_width": theme.default_border_width,
        "focus_width": theme.focus_width,
        "focus_offset": theme.focus_offset,
        "panel_padding": theme.panel_padding,
        "toolbar_gap": theme.toolbar_gap,
    })
}

fn theme_change_dirty(current: &Theme, next: &Theme) -> Option<Dirty> {
    if current == next {
        None
    } else if current.spacing != next.spacing
        || current.font_size != next.font_size
        || current.font_family != next.font_family
        || current.monospace_font_family != next.monospace_font_family
        || current.base_line_height != next.base_line_height
        || current.control_height != next.control_height
        || current.compact_control_height != next.compact_control_height
        || current.default_border_width != next.default_border_width
        || current.panel_padding != next.panel_padding
        || current.toolbar_gap != next.toolbar_gap
    {
        Some(Dirty::Layout)
    } else {
        Some(Dirty::Visual)
    }
}

fn active_stylesheets_snapshot(stylesheets: &StylesheetStore) -> Vec<Value> {
    stylesheets
        .active_stylesheets()
        .into_iter()
        .map(|sheet| {
            json!({
                "origin": match sheet.origin {
                    StylesheetOrigin::Framework => "framework",
                    StylesheetOrigin::Theme => "theme",
                    StylesheetOrigin::User => "user",
                    StylesheetOrigin::NativeFallback => "native-fallback",
                    StylesheetOrigin::WidgetDefault => "widget-default",
                    StylesheetOrigin::Inline => "inline",
                },
                "id": sheet.id,
                "source_order": sheet.source_order,
            })
        })
        .collect()
}

fn theme_color_scheme(theme: &Theme) -> DgMediaColorScheme {
    let [r, g, b, _] = theme.background;
    let luminance = 0.2126 * linear_srgb(r) + 0.7152 * linear_srgb(g) + 0.0722 * linear_srgb(b);
    if luminance > 0.5 {
        DgMediaColorScheme::Light
    } else {
        DgMediaColorScheme::Dark
    }
}

fn winit_theme_color_scheme(theme: WinitTheme) -> DgMediaColorScheme {
    match theme {
        WinitTheme::Light => DgMediaColorScheme::Light,
        WinitTheme::Dark => DgMediaColorScheme::Dark,
    }
}

fn linear_srgb(value: f32) -> f32 {
    let value = value.clamp(0.0, 1.0);
    if value <= 0.04045 {
        value / 12.92
    } else {
        ((value + 0.055) / 1.055).powf(2.4)
    }
}

fn now_epoch_ms() -> f64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs_f64() * 1000.0)
        .unwrap_or(0.0)
}

fn node_has_active_loading_spinner(
    node: &WidgetNode,
    layout: &LayoutResult,
    state: &WidgetState,
) -> bool {
    if node.kind == WidgetKind::LoadingSpinner
        && !state.is_disabled(&node.id)
        && layout.visible_rect(&node.id).is_some()
        && node
            .props
            .raw_props
            .get("spinning")
            .and_then(|value| value.as_bool())
            .unwrap_or(true)
    {
        return true;
    }
    node.children
        .iter()
        .any(|child| node_has_active_loading_spinner(child, layout, state))
}

fn set_widget_text_prop(node: &mut WidgetNode, id: &str, prop: &str, value: String) -> bool {
    let Some(target) = find_widget_mut(node, id) else {
        return false;
    };
    match (target.kind.clone(), prop) {
        (
            WidgetKind::Label
            | WidgetKind::Badge
            | WidgetKind::Tag
            | WidgetKind::Button
            | WidgetKind::SmallButton
            | WidgetKind::Selectable
            | WidgetKind::RadioButton
            | WidgetKind::TreeNode
            | WidgetKind::Checkbox
            | WidgetKind::ToggleSwitch
            | WidgetKind::NumberInput
            | WidgetKind::DragNumber
            | WidgetKind::ProgressBar,
            "text" | "label",
        ) => {
            target.props.text = Some(value);
            true
        }
        (WidgetKind::LoadingSpinner, "text" | "label") => {
            target.props.text = (!value.is_empty()).then_some(value);
            true
        }
        (
            WidgetKind::Panel | WidgetKind::Sidebar | WidgetKind::Modal | WidgetKind::Page,
            "title",
        ) => {
            target.props.text = Some(value);
            true
        }
        (WidgetKind::Collapsible, "title" | "text") => {
            target.props.text = Some(value);
            true
        }
        (
            WidgetKind::Tab | WidgetKind::NavItem | WidgetKind::Menu | WidgetKind::MenuItem,
            "label",
        ) => {
            target.props.text = Some(value);
            true
        }
        _ => false,
    }
}

fn set_widget_icon_prop(node: &mut WidgetNode, id: &str, icon: String) -> bool {
    let Some(target) = find_widget_mut(node, id) else {
        return false;
    };
    if target.kind != WidgetKind::IconButton || icon.trim().is_empty() {
        return false;
    }
    target
        .props
        .raw_props
        .insert("icon".to_string(), Value::String(icon));
    true
}

fn set_widget_loading_spinner_prop(
    node: &mut WidgetNode,
    id: &str,
    prop: &str,
    value: CommandValue,
) -> Option<Dirty> {
    let target = find_widget_mut(node, id)?;
    if target.kind != WidgetKind::LoadingSpinner {
        return None;
    }
    match (prop, value) {
        ("label", CommandValue::Text(text)) | ("text", CommandValue::Text(text)) => {
            target.props.text = (!text.is_empty()).then_some(text.clone());
            target
                .props
                .raw_props
                .insert("label".to_string(), Value::String(text));
            Some(Dirty::Text)
        }
        ("label", CommandValue::None) | ("text", CommandValue::None) => {
            target.props.text = None;
            target.props.raw_props.remove("label");
            Some(Dirty::Text)
        }
        ("spinning", CommandValue::Bool(spinning)) => {
            target
                .props
                .raw_props
                .insert("spinning".to_string(), Value::Bool(spinning));
            Some(Dirty::Visual)
        }
        ("speed", CommandValue::Float(speed)) if speed.is_finite() && speed >= 0.0 => {
            if let Some(number) = serde_json::Number::from_f64(speed as f64) {
                target
                    .props
                    .raw_props
                    .insert("speed".to_string(), Value::Number(number));
                Some(Dirty::Visual)
            } else {
                None
            }
        }
        ("size", CommandValue::Float(size)) if size.is_finite() && size > 0.0 => {
            if let Some(number) = serde_json::Number::from_f64(size as f64) {
                target
                    .props
                    .raw_props
                    .insert("size".to_string(), Value::Number(number));
                Some(Dirty::Layout)
            } else {
                None
            }
        }
        ("stroke_width", CommandValue::Float(width)) if width.is_finite() && width > 0.0 => {
            if let Some(number) = serde_json::Number::from_f64(width as f64) {
                target
                    .props
                    .raw_props
                    .insert("stroke_width".to_string(), Value::Number(number));
                Some(Dirty::Visual)
            } else {
                None
            }
        }
        (_, _) => None,
    }
}

