            | "flex_shrink"
            | "width"
            | "height"
            | "min_width"
            | "min_height"
            | "max_width"
            | "max_height"
            | "padding"
            | "padding_left"
            | "padding_right"
            | "padding_top"
            | "padding_bottom"
            | "margin"
            | "margin_left"
            | "margin-left"
            | "margin_right"
            | "margin-right"
            | "margin_top"
