    #[test]
    fn wheel_target_prefers_nested_scroll_panel_over_root_scroller() {
        let buttons: Vec<_> = (1..=10)
            .map(|index| {
                json!({
                    "id": format!("button-{index}"),
                    "type": "button",
                    "props": {"text": format!("Scrollable row {index}")},
                    "style": {"height": 30}
                })
            })
            .collect();
        let mut children = vec![json!({
            "id": "intro",
            "type": "label",
            "props": {"text": "The title should stay above the scrollable body."}
        })];
        children.extend(buttons);
        children.push(json!({
            "id": "pass",
            "type": "label",
            "props": {"text": "PASS: final row can scroll fully into view."}
        }));

        let tree = crate::document::parse_widget_node(&json!({
            "id": "window",
            "type": "window",
            "children": [{
                "id": "root",
                "type": "v_layout",
                "style": {
                    "height": 400,
                    "overflow_y": "auto",
                    "gap": 12
                },
                "children": [
                    {
                        "id": "before",
                        "type": "spacer",
                        "props": {"height": 260}
                    },
                    {
                        "id": "scroll-panel",
                        "type": "panel",
                        "props": {"title": "Scrollable titled panel"},
                        "style": {
                            "height": 250,
                            "overflow_y": "auto",
                            "overflow_x": "hidden",
                            "padding": 14,
                            "padding_right": 26,
                            "padding_bottom": 22,
                            "gap": 10
                        },
                        "children": children
                    },
                    {
                        "id": "after",
                        "type": "spacer",
                        "props": {"height": 260}
                    }
                ]
            }]
        }))
        .unwrap();
        for root_scroll in [0.0, 140.0, 250.0] {
            let mut state = WidgetState::from_tree(&tree);
            state
                .container_scroll_y
                .insert("root".to_string(), root_scroll);
            let layout = crate::layout::compute_layout(
                &tree,
                700.0,
                500.0,
                1.0,
                &Theme::dark(),
                Some(&state),
            );
            let panel = layout.rects.get("scroll-panel").unwrap();
            let panel_clip = layout.clips.get("scroll-panel").unwrap();
            let pos = [
                panel_clip.x + 40.0,
                (panel_clip.y + 100.0).min(panel_clip.y + panel_clip.h - 4.0),
            ];

            assert!(layout.scroll_max_y.get("root").copied().unwrap_or(0.0) > 0.0);
            assert!(
                layout
                    .scroll_max_y
                    .get("scroll-panel")
                    .copied()
                    .unwrap_or(0.0)
                    > 0.0
            );
            assert_eq!(
                scroll_container_at_pos(&tree, &layout, &state, pos),
                Some("scroll-panel".to_string()),
                "root_scroll={root_scroll} panel={panel:?} clip={panel_clip:?} pos={pos:?}"
            );
        }
    }

    #[test]
    fn wheel_target_prefers_active_modal_over_background_scroller() {
        let modal_rows: Vec<_> = (1..=12)
            .map(|index| {
                json!({
                    "id": format!("modal-row-{index}"),
                    "type": "label",
                    "props": {"text": format!("Modal row {index}")}
                })
            })
            .collect();

        let tree = crate::document::parse_widget_node(&json!({
            "id": "window",
            "type": "window",
            "children": [
                {
                    "id": "modal",
                    "type": "modal",
                    "props": {
                        "title": "Scrollable modal",
                        "open": true,
                        "width": 320,
                        "height": 145
                    },
                    "children": modal_rows
                },
                {
                    "id": "root",
                    "type": "v_layout",
                    "style": {
                        "height": 320,
                        "overflow_y": "auto"
                    },
                    "children": [
                        {"id": "top", "type": "spacer", "props": {"height": 420}},
                        {"id": "bottom", "type": "spacer", "props": {"height": 420}}
                    ]
                }
            ]
        }))
        .unwrap();
        let state = WidgetState::from_tree(&tree);
        let layout =
            crate::layout::compute_layout(&tree, 420.0, 320.0, 1.0, &Theme::dark(), Some(&state));
        let modal = layout.rects.get("modal").unwrap();
        let pos = [modal.x + modal.w * 0.5, modal.y + modal.h * 0.65];

        assert!(layout.scroll_max_y.get("root").copied().unwrap_or(0.0) > 0.0);
        assert!(layout.scroll_max_y.get("modal").copied().unwrap_or(0.0) > 0.0);
        assert_eq!(
            active_scroll_container_at_pos(&tree, &layout, &state, pos),
            Some("modal".to_string()),
            "wheel over open modal should not target background root scroller: modal={modal:?} pos={pos:?}"
        );
    }

    #[test]
    fn computed_style_snapshot_includes_part_matched_rules() {
        let mut tree = crate::document::parse_widget_node(&json!({
            "id": "root",
            "type": "window",
            "children": [{
                "id": "amount",
                "type": "number_input",
                "class": "numeric"
            }]
        }))
        .unwrap();
        let mut store = StylesheetStore::default();
        store
            .set_stylesheet(
                StylesheetOrigin::User,
                r#"
                NumberInput::stepper { width: 34px; background: surface_alt; }
                .numeric:hover::stepper-up { color: accent; }
                "#,
            )
            .unwrap();
        apply_stylesheets_to_tree(&mut tree, &mut store);

        let snapshot = computed_styles_snapshot(Some(&tree), &store, None);
        let parts = &snapshot["amount"]["style"]["parts"];

        assert_eq!(
            parts["stepper"]["matched_rules"],
            json!(["user: NumberInput::stepper"])
        );
        assert_eq!(parts["stepper"]["layout"]["width"], json!(34.0));
        assert_eq!(
            parts["stepper"]["visual"]["background"]["token"],
            "surface_alt"
        );
        assert_eq!(
            parts["stepper-up"]["matched_rules"],
            json!(["user: .numeric:hover::stepper-up"])
        );
        assert_eq!(
            parts["stepper-up"]["hover"]["text"]["color"]["token"],
            "accent"
        );
        assert!(parts.get("base").is_none());
        assert!(parts.get("hover").is_none());
    }

    #[test]
