    fn tick_css_animations(&mut self) -> CssAnimationTick {
        let Some(tree) = self.widget_tree.as_ref() else {
            self.css_animations_active = false;
            return CssAnimationTick::default();
        };
        let keyframes = self.stylesheets.keyframes();
        if keyframes.is_empty() {
            self.css_animations_active = false;
            if let Some(state) = &mut self.widget_state {
                let previous = std::mem::take(&mut state.animation_visuals);
                let visual_dirty_ids = previous.keys().cloned().collect();
                return CssAnimationTick {
                    visual_dirty_ids,
                    text_dirty_ids: previous
                        .into_iter()
                        .filter_map(|(id, visual)| {
                            animation_visual_change_affects_text(Some(&visual), None).then_some(id)
                        })
                        .collect(),
                };
            }
            return CssAnimationTick::default();
        }
        let now = Instant::now();
        let elapsed = now.saturating_duration_since(self.animation_epoch);
        let mut visuals = HashMap::new();
        let mut active = false;
        collect_animation_visuals(
            tree,
            &keyframes,
            elapsed,
            &self.theme,
            &mut visuals,
            &mut active,
        );
        let Some(state) = &mut self.widget_state else {
            self.css_animations_active = false;
            return CssAnimationTick::default();
        };
        let mut tick = CssAnimationTick::default();
        for id in state
            .animation_visuals
            .keys()
            .chain(visuals.keys())
            .collect::<HashSet<_>>()
        {
            let previous = state.animation_visuals.get(id);
            let current = visuals.get(id);
            if previous != current {
                tick.visual_dirty_ids.insert((*id).clone());
                if animation_visual_change_affects_text(previous, current) {
                    tick.text_dirty_ids.insert((*id).clone());
                }
            }
        }
        state.animation_visuals = visuals;
        self.css_animations_active = active;
        tick
    }

    fn cancel_hover_transitions(&mut self) -> bool {
        clear_style_transition_state(
            &mut self.hover_transitions,
            &mut self.focus_transitions,
            &mut self.checked_transitions,
            &mut self.active_transitions,
            &mut self.open_transitions,
            &mut self.selected_transitions,
            &mut self.expanded_transitions,
            &mut self.widget_state,
        )
    }

    fn has_style_transitions(&self) -> bool {
        !self.hover_transitions.is_empty()
            || !self.focus_transitions.is_empty()
            || !self.checked_transitions.is_empty()
            || !self.active_transitions.is_empty()
            || !self.open_transitions.is_empty()
            || !self.selected_transitions.is_empty()
            || !self.expanded_transitions.is_empty()
    }

    fn active_style_transitions_affect_text(&self) -> bool {
        let Some(tree) = self.widget_tree.as_ref() else {
            return false;
        };
        self.hover_transitions
            .keys()
            .chain(self.focus_transitions.keys())
            .chain(self.checked_transitions.keys())
            .chain(self.active_transitions.keys())
            .chain(self.open_transitions.keys())
            .chain(self.selected_transitions.keys())
            .chain(self.expanded_transitions.keys())
            .any(|id| {
                let Some(node) = find_node(tree, id) else {
                    return true;
                };
                transition_properties_affect_text(node.style.transition.properties.as_deref())
            })
    }

    fn has_css_animations(&self) -> bool {
        self.css_animations_active
    }

    fn resize(&mut self, width: u32, height: u32) {
        if width == 0 || height == 0 {
            return;
        }
        self.config.width = width;
        self.config.height = height;
        self.surface.configure(&self.device, &self.config);
        let (dt, dv) = create_depth_texture(&self.device, width, height);
        self._depth_texture = dt;
        self.depth_view = dv;
        self.apply_layout();
    }

    fn set_scale_factor(&mut self, sf: f64, new_inner_size: PhysicalSize<u32>) {
        self.scale_factor = sf as f32;
        self.resize(new_inner_size.width, new_inner_size.height);
    }

    /// Return the topmost visible scatter id that contains `pos`, or None.
    /// Checks in reverse visible order so the visually topmost scatter wins.
    fn scatter_at(&self, pos: [f32; 2]) -> Option<String> {
        for id in self.visible_scatter_order.iter().rev() {
            if let Some(runtime) = self.scatters.get(id) {
                if runtime.widget.contains_point(pos[0], pos[1]) {
                    return Some(id.clone());
                }
            }
        }
        None
    }

    fn scatter_pick_payload(&mut self, id: &str, pos: [f32; 2]) -> Option<String> {
        let runtime = self.scatters.get_mut(id)?;
        let (actor_id, index, point) = runtime.pick_all_actors_cached(pos[0], pos[1], 8.0)?;
        Some(
            json!({
                "index": index,
                "actor": actor_id,
                "x": point.position[0],
                "y": point.position[1],
                "z": point.position[2],
                "widget_id": id,
            })
            .to_string(),
        )
    }

    /// Perform polygon (lasso) selection hit test and return a JSON payload with selected indices.
    fn scatter_polygon_select_payload(&mut self, id: &str, poly: &[[f32; 2]]) -> Option<String> {
        let runtime = self.scatters.get_mut(id)?;
        if let Err(e) = runtime.ensure_primary_points_from_compact() {
            eprintln!("DragonGUI: scatter compact point cache decode failed: {e}");
            return None;
        }
        let mut actor_results = serde_json::Map::new();
        let indices = runtime
            .widget
            .select_points_in_polygon(&runtime.points, poly);
        actor_results.insert("0".into(), indices.into());
        for (actor_id, actor) in &runtime.widget.extra_actors {
            if actor.visible {
                let live = &actor.points[..actor.point_count as usize];
                let idx = runtime.widget.select_points_in_polygon(live, poly);
                actor_results.insert(actor_id.to_string(), idx.into());
            }
        }
        Some(
            json!({
                "event": "select",
                "widget_id": id,
                "actors": actor_results,
            })
            .to_string(),
        )
    }

    /// Perform rectangle selection hit test and return a JSON payload with selected indices.
    /// `rect` is in physical pixels relative to the scatter viewport.
    fn scatter_select_payload(&mut self, id: &str, rect: [f32; 4]) -> Option<String> {
        let runtime = self.scatters.get_mut(id)?;
        if let Err(e) = runtime.ensure_primary_points_from_compact() {
            eprintln!("DragonGUI: scatter compact point cache decode failed: {e}");
            return None;
        }
        let mut actor_results = serde_json::Map::new();
        // Actor 0 (primary buffer)
        let indices = runtime.widget.select_points_in_rect(&runtime.points, rect);
        actor_results.insert("0".into(), indices.into());
        // Extra actors — limit to live range to avoid picking preallocated zero-slots.
        for (actor_id, actor) in &runtime.widget.extra_actors {
            if actor.visible {
                let live = &actor.points[..actor.point_count as usize];
                let idx = runtime.widget.select_points_in_rect(live, rect);
                actor_results.insert(actor_id.to_string(), idx.into());
            }
        }
        Some(
            json!({
                "event": "select",
                "widget_id": id,
                "actors": actor_results,
            })
            .to_string(),
        )
    }

    /// Hit test interactive UI widgets at physical pixel position `pos`.
    fn hit_test_ui(&self, pos: [f32; 2]) -> Option<(String, WidgetKind)> {
        let (tree, layout) = match (self.widget_tree.as_ref(), self.current_layout.as_ref()) {
            (Some(t), Some(l)) => (t, l),
            _ => return None,
        };
        let state = self.widget_state.as_ref()?;
        hit_test(tree, layout, pos)
            .filter(|(id, kind)| {
                kind != &WidgetKind::Collapsible || self.collapsible_header_contains(id, pos)
            })
            .filter(|(id, kind)| {
                kind != &WidgetKind::TreeNode || self.tree_node_row_contains(id, pos)
            })
            .filter(|(id, _)| !state.is_disabled(id))
    }

    fn client_chrome_drag_target_at(&self, pos: [f32; 2]) -> Option<String> {
        client_chrome_drag_target_at(
            self.widget_tree.as_ref()?,
            self.current_layout.as_ref()?,
            pos,
        )
    }

    fn hit_test_hover(&self, pos: [f32; 2]) -> Option<(String, WidgetKind)> {
        if let Some(id) = self.menu_item_at(pos) {
            return Some((id, WidgetKind::MenuItem));
        }
        if self.menu_popup_contains(pos) {
            return None;
        }
        let (tree, layout) = match (self.widget_tree.as_ref(), self.current_layout.as_ref()) {
            (Some(t), Some(l)) => (t, l),
            _ => return None,
        };
        let state = self.widget_state.as_ref()?;
        hit_test_hover_with_targets(tree, layout, pos, &self.tooltip_overlay_targets)
            .filter(|(id, kind)| {
                kind != &WidgetKind::Collapsible || self.collapsible_header_contains(id, pos)
            })
            .filter(|(id, kind)| {
                kind != &WidgetKind::TreeNode || self.tree_node_row_contains(id, pos)
            })
            .filter(|(id, _)| !state.is_disabled(id))
    }

    fn extension_event_at(&self, pos: [f32; 2], event: &str) -> Option<(String, WidgetKind)> {
        let (tree, layout) = match (self.widget_tree.as_ref(), self.current_layout.as_ref()) {
            (Some(t), Some(l)) => (t, l),
            _ => return None,
        };
        let state = self.widget_state.as_ref()?;
        hit_test_extension_event(tree, layout, pos, event).filter(|(id, _)| !state.is_disabled(id))
    }

    fn drag_source_at(&self, pos: [f32; 2]) -> Option<DragSourceHit> {
        let tree = self.widget_tree.as_ref()?;
        let layout = self.current_layout.as_ref()?;
        let state = self.widget_state.as_ref()?;
        let root = active_modal_ref(tree).unwrap_or(tree);
        drag_source_at_node(root, layout, state, pos)
    }

    fn drop_target_at(&self, pos: [f32; 2], kind: Option<&str>) -> Option<String> {
        let tree = self.widget_tree.as_ref()?;
        let layout = self.current_layout.as_ref()?;
        let state = self.widget_state.as_ref()?;
        let root = active_modal_ref(tree).unwrap_or(tree);
        drop_target_at_node(root, layout, state, pos, kind)
    }

    fn set_drag_drop_state(
        &mut self,
        source: Option<String>,
        target: Option<String>,
        kind: Option<String>,
        pos: Option<[f32; 2]>,
    ) -> bool {
        let Some(state) = self.widget_state.as_mut() else {
            return false;
        };
        let widget_state_changed = state.drag_source != source
            || state.drag_hover_target != target
            || state.drag_kind != kind;
        let changed = widget_state_changed || state.drag_pos != pos;
        if changed {
            let dirty_ids = state
                .drag_source
                .clone()
                .into_iter()
                .chain(state.drag_hover_target.clone())
                .chain(source.clone())
                .chain(target.clone())
                .collect::<HashSet<_>>();
            state.drag_source = source;
            state.drag_hover_target = target;
            state.drag_kind = kind;
            state.drag_pos = pos;
            if widget_state_changed && !dirty_ids.is_empty() {
                self.rebuild_interaction_visuals(&dirty_ids, &HashSet::new(), false);
            }
            // The cursor-following drag chip is a global primitive overlay,
            // not part of either targeted widget subtree. Rebuild it for every
            // pointer-position change without rebuilding overlay text or the
            // complete widget visual tree.
            self.rebuild_overlay_primitives();
        }
        changed
    }

    fn clear_drag_drop_state(&mut self) -> bool {
        self.set_drag_drop_state(None, None, None, None)
    }

    fn collapsible_header_contains(&self, id: &str, pos: [f32; 2]) -> bool {
        let Some(tree) = self.widget_tree.as_ref() else {
            return false;
        };
        let Some(layout) = self.current_layout.as_ref() else {
            return false;
        };
        let Some(node) = find_widget(tree, id) else {
            return false;
        };
        let Some(rect) = layout.rects.get(id) else {
            return false;
        };
        if node.kind != WidgetKind::Collapsible {
            return false;
        }
        let header_h =
            collapsible_header_height_for_style(&node.style, &self.theme, self.scale_factor)
                .min(rect.h.max(0.0));
        pos[0] >= rect.x
            && pos[0] < rect.x + rect.w
            && pos[1] >= rect.y
            && pos[1] < rect.y + header_h
    }

    fn tree_node_row_contains(&self, id: &str, pos: [f32; 2]) -> bool {
        let Some(rect) = self
            .current_layout
            .as_ref()
            .and_then(|layout| layout.rects.get(id))
        else {
            return false;
        };
        let row_h = self
            .widget_tree
            .as_ref()
            .and_then(|tree| find_widget(tree, id))
            .map(|node| {
                tree_node_row_height_for_style(
                    node,
                    &self.theme,
                    self.scale_factor,
                    Some(rect.h.max(0.0)),
                )
            })
            .unwrap_or_else(|| {
                ((self.theme.font_size + self.theme.spacing * 2.0 + 4.0) * self.scale_factor)
                    .max(28.0 * self.scale_factor)
            })
            .min(rect.h.max(0.0));
        pos[0] >= rect.x && pos[0] < rect.x + rect.w && pos[1] >= rect.y && pos[1] < rect.y + row_h
    }

    fn tree_node_disclosure_contains(&self, id: &str, pos: [f32; 2]) -> bool {
        let Some(tree) = self.widget_tree.as_ref() else {
            return false;
        };
        let Some(node) = find_widget(tree, id) else {
            return false;
        };
        if node.kind != WidgetKind::TreeNode || node.children.is_empty() {
            return false;
        }
        let Some(rect) = self
            .current_layout
            .as_ref()
            .and_then(|layout| layout.rects.get(id))
        else {
            return false;
        };
        let row_h = tree_node_row_height_for_style(
            node,
            &self.theme,
            self.scale_factor,
            Some(rect.h.max(0.0)),
        )
        .min(rect.h.max(0.0));
        let indicator_w = 18.0 * self.scale_factor;
        pos[0] >= rect.x
            && pos[0] < rect.x + self.theme.spacing * self.scale_factor + indicator_w
            && pos[1] >= rect.y
            && pos[1] < rect.y + row_h
    }

    fn modal_blocks_point(&self, pos: [f32; 2]) -> bool {
        let (tree, layout) = match (self.widget_tree.as_ref(), self.current_layout.as_ref()) {
            (Some(t), Some(l)) => (t, l),
            _ => return false,
        };
        modal_blocks_point(tree, layout, pos)
    }

    fn modal_close_button_at(&self, pos: [f32; 2]) -> Option<String> {
        let tree = self.widget_tree.as_ref()?;
        let layout = self.current_layout.as_ref()?;
        let modal = active_modal_ref(tree)?;
        let rect = modal_close_button_rect(modal, layout, &self.theme, self.scale_factor)?;
        let hit = pos[0] >= rect[0]
            && pos[0] < rect[0] + rect[2]
            && pos[1] >= rect[1]
            && pos[1] < rect[1] + rect[3];
        hit.then(|| modal.id.clone())
    }

    fn has_active_modal(&self) -> bool {
        self.widget_tree
            .as_ref()
            .is_some_and(|tree| has_active_modal(tree))
    }

    fn has_active_loading_spinner(&self) -> bool {
        match (
            self.widget_tree.as_ref(),
            self.current_layout.as_ref(),
            self.widget_state.as_ref(),
        ) {
            (Some(tree), Some(layout), Some(state)) => {
                node_has_active_loading_spinner(tree, layout, state)
            }
            _ => false,
        }
    }

    fn close_active_modal(&mut self) -> Option<String> {
        let tree = self.widget_tree.as_mut()?;
        let closed = close_active_modal(tree)?;
        if let Some(state) = &mut self.widget_state {
            state.focus_widget(None);
            state.pressed = None;
            state.close_popups();
        }
        self.apply_layout();
        Some(closed)
    }

    fn close_active_sidebar_drawer(&mut self) -> Option<String> {
        let (tree, state) = match (&mut self.widget_tree, &mut self.widget_state) {
            (Some(tree), Some(state)) => (tree, state),
            _ => return None,
        };
        let closed = close_active_sidebar_drawer(tree, state)?;
        self.reapply_stylesheets();
        self.apply_layout();
        Some(closed)
    }

    fn number_input_step_at(&self, pos: [f32; 2]) -> Option<(String, f32)> {
        number_input_step_at_pos(
            self.widget_tree.as_ref(),
            &self.widget_kinds,
            self.widget_state.as_ref()?,
            self.current_layout.as_ref()?,
            self.scale_factor,
            pos,
        )
    }

    /// Look up the kind of widget with `id` in the widget tree.
    fn widget_kind(&self, id: &str) -> Option<WidgetKind> {
        self.widget_kinds.get(id).cloned()
    }

    fn widget_has_event(&self, id: &str, event: &str) -> bool {
        self.widget_tree
            .as_ref()
            .and_then(|tree| find_widget(tree, id))
            .and_then(|node| node.props.raw_props.get("events"))
            .and_then(|value| value.as_array())
            .is_some_and(|events| events.iter().any(|value| value.as_str() == Some(event)))
    }

    fn extension_event_payload(
        &self,
        id: &str,
        event: &str,
        pos: [f32; 2],
        dx: f32,
        dy: f32,
        button: Option<&str>,
    ) -> Option<String> {
        if self.widget_kind(id) != Some(WidgetKind::Extension) || !self.widget_has_event(id, event)
        {
            return None;
        }
        let layout = self.current_layout.as_ref()?;
        let rect = layout
            .rects
            .get(id)
            .copied()
            .or_else(|| layout.visible_rect(id))?;
        let mut payload = Map::new();
        payload.insert("event".to_string(), json!(event));
        payload.insert("widget_id".to_string(), json!(id));
        payload.insert("x".to_string(), json!(pos[0]));
        payload.insert("y".to_string(), json!(pos[1]));
        payload.insert("local_x".to_string(), json!(pos[0] - rect.x));
        payload.insert("local_y".to_string(), json!(pos[1] - rect.y));
        payload.insert("dx".to_string(), json!(dx));
        payload.insert("dy".to_string(), json!(dy));
        if let Some(button) = button {
            payload.insert("button".to_string(), json!(button));
        }
        Some(Value::Object(payload).to_string())
    }

    fn extension_key_event_payload(
        &self,
        id: &str,
        event: &winit::event::KeyEvent,
        modifiers: ModifiersState,
    ) -> Option<String> {
        if self.widget_kind(id) != Some(WidgetKind::Extension)
            || !self.widget_has_event(id, "key_down")
        {
            return None;
        }
        let mut payload = Map::new();
        payload.insert("event".to_string(), json!("key_down"));
        payload.insert("widget_id".to_string(), json!(id));
        payload.insert("key".to_string(), json!(key_name(&event.logical_key)));
        payload.insert("text".to_string(), json!(event.text.as_deref()));
        payload.insert("shift".to_string(), json!(modifiers.shift_key()));
        payload.insert("ctrl".to_string(), json!(modifiers.control_key()));
        payload.insert("alt".to_string(), json!(modifiers.alt_key()));
        payload.insert("super".to_string(), json!(modifiers.super_key()));
        payload.insert("repeat".to_string(), json!(event.repeat));
        Some(Value::Object(payload).to_string())
    }

    fn has_widget(&self, id: &str) -> bool {
        self.widget_kinds.contains_key(id)
    }

    fn log_view_follow(&self, id: &str) -> bool {
        self.widget_tree
            .as_ref()
            .and_then(|tree| find_node(tree, id))
            .and_then(|node| node.props.raw_props.get("follow"))
            .and_then(|value| value.as_bool())
            .unwrap_or(true)
    }

    fn apply_set_prop(&mut self, id: &str, prop: &str, value: CommandValue) -> Option<Dirty> {
        let kind = self.widget_kind(id)?;
        if kind == WidgetKind::IconButton && prop == "icon" {
            let CommandValue::Text(icon) = value else {
                eprintln!("DragonGUI: ignoring unsupported live icon value for widget {id:?}");
                return None;
            };
            let normalized = icon.trim().to_ascii_lowercase().replace('_', "-");
            let tree = self.widget_tree.as_mut()?;
            if !set_widget_icon_prop(tree, id, normalized) {
                return None;
            }
            let node = find_widget_mut(tree, id)?;
            if let Err(error) = self.icon_theme.apply_to_subtree(node) {
                eprintln!("DragonGUI: failed to reconcile live icon {id:?}: {error}");
                return None;
            }
            return Some(Dirty::Text);
        }
        if matches!(prop, "scroll_x" | "scroll_y") {
            let CommandValue::Float(target_scroll) = value else {
                eprintln!(
                    "DragonGUI: ignoring unsupported live scroll value for widget {id:?} ({kind:?}).{prop}"
                );
                return None;
            };
            let (max_scroll_x, max_scroll_y) = {
                let tree = self.widget_tree.as_ref()?;
                let layout = self.current_layout.as_ref()?;
                let node = find_widget(tree, id)?;
                if !is_scroll_container_node(node) {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live SetProp for non-scroll widget {id:?} ({kind:?}).{prop}"
                    );
                    return None;
                }
                let max_scroll_x = layout
                    .scroll_max_x
                    .get(id)
                    .copied()
                    .unwrap_or_else(|| scroll_container_max_x(node, layout));
                let max_scroll_y = layout
                    .scroll_max_y
                    .get(id)
                    .copied()
                    .unwrap_or_else(|| scroll_container_max_y(node, layout));
                (max_scroll_x, max_scroll_y)
            };
            let state = self.widget_state.as_mut()?;
            let current_x = state.container_scroll_x(id, max_scroll_x);
            let current_y = state.container_scroll_y(id, max_scroll_y);
            let (delta_x, delta_y) = if prop == "scroll_x" {
                (target_scroll - current_x, 0.0)
            } else {
                (0.0, target_scroll - current_y)
            };
            return state
                .scroll_container(id, delta_x, delta_y, max_scroll_x, max_scroll_y)
                .then_some(Dirty::Layout);
        }
        if prop == "class" {
            let class_name = match value {
                CommandValue::Text(text) => Some(text),
                CommandValue::None => None,
                other => {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live class metadata value for widget {id:?}: {other:?}"
                    );
                    return None;
                }
            };
            if let Some(tree) = self.widget_tree.as_mut() {
                if set_widget_class_prop(tree, id, class_name) {
                    self.mark_styles_dirty();
                    return Some(Dirty::Full);
                }
            }
            return None;
        }
        if kind == WidgetKind::Sidebar && prop == "state" {
            let CommandValue::Text(state) = value else {
                eprintln!(
                    "DragonGUI: ignoring unsupported live Sidebar state value for widget {id:?}"
                );
                return None;
            };
            let (previous_state, sidebar_before) = self
                .widget_tree
                .as_ref()
                .and_then(|tree| find_widget(tree, id))
                .map(|sidebar| (sidebar_state(sidebar).to_string(), sidebar.clone()))?;
            if let Some(tree) = self.widget_tree.as_mut() {
                if set_widget_sidebar_state_prop(tree, id, state.clone()) {
                    if let Some(widget_state) = self.widget_state.as_mut() {
                        reconcile_sidebar_focus_for_state(
                            &sidebar_before,
                            &previous_state,
                            &state,
                            widget_state,
                        );
                    }
                    self.mark_styles_dirty();
                    return Some(Dirty::Full);
                }
            }
            eprintln!("DragonGUI: ignoring invalid live Sidebar state for widget {id:?}");
            return None;
        }
        if kind == WidgetKind::LoadingSpinner {
            let Some(tree) = self.widget_tree.as_mut() else {
                return None;
            };
            let dirty = set_widget_loading_spinner_prop(tree, id, prop, value);
            if dirty.is_none() {
                eprintln!(
                    "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                );
            }
            return dirty;
        }
        if let CommandValue::Text(text) = &value {
            if matches!(
                kind,
                WidgetKind::Label
                    | WidgetKind::Badge
                    | WidgetKind::Tag
                    | WidgetKind::Button
                    | WidgetKind::SmallButton
                    | WidgetKind::Selectable
                    | WidgetKind::RadioButton
                    | WidgetKind::Panel
                    | WidgetKind::Sidebar
                    | WidgetKind::Checkbox
                    | WidgetKind::ToggleSwitch
                    | WidgetKind::NumberInput
                    | WidgetKind::DragNumber
                    | WidgetKind::ProgressBar
                    | WidgetKind::Collapsible
                    | WidgetKind::Modal
                    | WidgetKind::Page
                    | WidgetKind::Tab
                    | WidgetKind::NavItem
                    | WidgetKind::Menu
                    | WidgetKind::MenuItem
            ) {
                if let Some(tree) = self.widget_tree.as_mut() {
                    if set_widget_text_prop(tree, id, prop, text.clone()) {
                        return Some(Dirty::Text);
                    }
                }
            }
        }
        if matches!(kind, WidgetKind::Badge | WidgetKind::Tag) && prop == "level" {
            let CommandValue::Text(level) = value else {
                eprintln!(
                    "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                );
                return None;
            };
            if let Some(tree) = self.widget_tree.as_mut() {
                if set_widget_level_prop(tree, id, level) {
                    self.mark_styles_dirty();
                    return Some(Dirty::Full);
                }
            }
            return None;
        }
        if kind == WidgetKind::Led {
            match (prop, value) {
                ("state", CommandValue::Text(state_name)) => {
                    let state_affects_styles = self
                        .stylesheets
                        .references_attribute_for_kind("state", WidgetKind::Led);
                    if let Some(tree) = self.widget_tree.as_mut() {
                        if set_widget_led_state_prop(tree, id, state_name) {
                            if state_affects_styles {
                                self.mark_styles_dirty();
                                return Some(Dirty::Full);
                            }
                            return Some(Dirty::Visual);
                        }
                    }
                    return None;
                }
                ("color", CommandValue::Text(color)) => {
                    if let Some(tree) = self.widget_tree.as_mut() {
                        if set_widget_led_color_prop(tree, id, color) {
                            return Some(Dirty::Visual);
                        }
                    }
                    return None;
                }
                ("size", CommandValue::Float(size)) => {
                    if let Some(tree) = self.widget_tree.as_mut() {
                        if set_widget_led_size_prop(tree, id, size) {
                            return Some(Dirty::Layout);
                        }
                    }
                    return None;
                }
                (_, _) => {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                    );
                    return None;
                }
            }
        }
        if kind == WidgetKind::Modal && prop == "open" {
            let CommandValue::Bool(open) = value else {
                eprintln!(
                    "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                );
                return None;
            };
            if let Some(tree) = self.widget_tree.as_mut() {
                if set_widget_open_prop(tree, id, open) {
                    return Some(Dirty::Layout);
                }
            }
            return None;
        }
        if matches!(kind, WidgetKind::Collapsible | WidgetKind::TreeNode) && prop == "expanded" {
            let CommandValue::Bool(expanded) = value else {
                eprintln!(
                    "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                );
                return None;
            };
            if let Some(state) = self.widget_state.as_mut() {
                state.set_expanded(id, expanded)?;
            }
            if let Some(tree) = self.widget_tree.as_mut() {
                set_widget_expanded_prop(tree, id, expanded);
            }
            return Some(Dirty::Layout);
        }
        if kind == WidgetKind::LinePlot {
            let Some(tree) = self.widget_tree.as_mut() else {
                return None;
            };
            let Some(node) = find_widget_mut(tree, id) else {
                return None;
            };
            match (prop, value) {
                ("line_width", CommandValue::Float(width)) => {
                    node.props.line_plot_line_width = width.max(0.5);
                    return Some(Dirty::Visual);
                }
                ("show_grid", CommandValue::Bool(visible)) => {
                    node.props.line_plot_show_grid = visible;
                    return Some(Dirty::Visual);
                }
                ("show_axes", CommandValue::Bool(visible)) => {
                    node.props.line_plot_show_axes = visible;
                    return Some(Dirty::Text);
                }
                ("show_ticks", CommandValue::Bool(visible)) => {
                    node.props.line_plot_show_ticks = visible;
                    return Some(Dirty::Text);
                }
                ("show_toolbar", CommandValue::Bool(visible)) => {
                    node.props.line_plot_show_toolbar = visible;
                    return Some(Dirty::Text);
                }
                ("show_legend", CommandValue::Bool(visible)) => {
                    node.props.line_plot_show_legend = visible;
                    return Some(Dirty::Text);
                }
                ("legend_position", CommandValue::Text(position)) => {
                    if matches!(
                        position.as_str(),
                        "top-right" | "top-left" | "bottom-right" | "bottom-left"
                    ) {
                        node.props.line_plot_legend_position = position;
                        return Some(Dirty::Text);
                    }
                    return None;
                }
                ("tick_count", CommandValue::Float(count)) => {
                    node.props.line_plot_tick_count = (count.round() as isize).clamp(2, 9) as usize;
                    return Some(Dirty::Text);
                }
                ("x_label", CommandValue::Text(label)) => {
                    node.props.line_plot_x_label = (!label.trim().is_empty()).then_some(label);
                    return Some(Dirty::Text);
                }
                ("y_label", CommandValue::Text(label)) => {
                    node.props.line_plot_y_label = (!label.trim().is_empty()).then_some(label);
                    return Some(Dirty::Text);
                }
                ("auto_fit", CommandValue::Bool(auto_fit)) => {
                    node.props.line_plot_auto_fit = auto_fit;
                    return Some(Dirty::Visual);
                }
                ("window_size", CommandValue::Float(size)) => {
                    node.props.line_plot_window_size =
                        (size.is_finite() && size > 0.0).then_some(size);
                    apply_line_plot_window_to_node(node);
                    return Some(Dirty::Text);
                }
                ("window_size", CommandValue::None) => {
                    node.props.line_plot_window_size = None;
                    node.props.line_plot_auto_fit = true;
                    node.props.line_plot_x_min = None;
                    node.props.line_plot_x_max = None;
                    node.props.line_plot_y_min = None;
                    node.props.line_plot_y_max = None;
                    return Some(Dirty::Text);
                }
                ("interaction", CommandValue::Text(mode)) => {
                    if matches!(mode.as_str(), "inspect" | "pan" | "zoom" | "box_zoom") {
                        node.props.line_plot_interaction = mode;
                        return Some(Dirty::Visual);
                    }
                    return None;
                }
                ("x_min", CommandValue::Float(value)) => {
                    node.props.line_plot_x_min = value.is_finite().then_some(value);
                    node.props.line_plot_auto_fit = false;
                    return Some(Dirty::Visual);
                }
                ("x_max", CommandValue::Float(value)) => {
                    node.props.line_plot_x_max = value.is_finite().then_some(value);
                    node.props.line_plot_auto_fit = false;
                    return Some(Dirty::Visual);
                }
                ("y_min", CommandValue::Float(value)) => {
                    node.props.line_plot_y_min = value.is_finite().then_some(value);
                    node.props.line_plot_auto_fit = false;
                    return Some(Dirty::Visual);
                }
                ("y_max", CommandValue::Float(value)) => {
                    node.props.line_plot_y_max = value.is_finite().then_some(value);
                    node.props.line_plot_auto_fit = false;
                    return Some(Dirty::Visual);
                }
                (_, _) => {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                    );
                    return None;
                }
            }
        }
        if kind == WidgetKind::Histogram {
            let Some(tree) = self.widget_tree.as_mut() else {
                return None;
            };
            let Some(node) = find_widget_mut(tree, id) else {
                return None;
            };
            match (prop, value) {
                ("show_grid", CommandValue::Bool(visible)) => {
                    node.props.histogram.show_grid = visible;
                    return Some(Dirty::Visual);
                }
                ("show_axes", CommandValue::Bool(visible)) => {
                    node.props.histogram.show_axes = visible;
                    return Some(Dirty::Text);
                }
                ("show_ticks", CommandValue::Bool(visible)) => {
                    node.props.histogram.show_ticks = visible;
                    return Some(Dirty::Text);
                }
                ("show_toolbar", CommandValue::Bool(visible)) => {
                    node.props.histogram.show_toolbar = visible;
                    return Some(Dirty::Text);
                }
                ("tick_count", CommandValue::Float(count)) => {
                    node.props.histogram.tick_count = (count.round() as isize).clamp(2, 9) as usize;
                    return Some(Dirty::Text);
                }
                ("x_label", CommandValue::Text(label)) => {
                    node.props.histogram.x_label = (!label.trim().is_empty()).then_some(label);
                    return Some(Dirty::Text);
                }
                ("y_label", CommandValue::Text(label)) => {
                    node.props.histogram.y_label = (!label.trim().is_empty()).then_some(label);
                    return Some(Dirty::Text);
                }
                ("auto_fit", CommandValue::Bool(auto_fit)) => {
                    node.props.histogram.auto_fit = auto_fit;
                    if auto_fit {
                        node.props.histogram.x_min = None;
                        node.props.histogram.x_max = None;
                        node.props.histogram.y_min = None;
                        node.props.histogram.y_max = None;
                    }
                    return Some(Dirty::Visual);
                }
                ("interaction", CommandValue::Text(mode)) => {
                    if matches!(mode.as_str(), "inspect" | "pan" | "zoom" | "box_zoom") {
                        node.props.histogram.interaction = mode;
                        return Some(Dirty::Visual);
                    }
                    return None;
                }
                (_, _) => {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                    );
                    return None;
                }
            }
        }
        if kind == WidgetKind::BarChart {
            let Some(tree) = self.widget_tree.as_mut() else {
                return None;
            };
            let Some(node) = find_widget_mut(tree, id) else {
                return None;
            };
            match (prop, value) {
                ("show_grid", CommandValue::Bool(visible)) => {
                    node.props.bar_chart.show_grid = visible;
                    return Some(Dirty::Visual);
                }
                ("show_axes", CommandValue::Bool(visible)) => {
                    node.props.bar_chart.show_axes = visible;
                    return Some(Dirty::Text);
                }
                ("show_ticks", CommandValue::Bool(visible)) => {
                    node.props.bar_chart.show_ticks = visible;
                    return Some(Dirty::Text);
                }
                ("show_toolbar", CommandValue::Bool(visible)) => {
                    node.props.bar_chart.show_toolbar = visible;
                    return Some(Dirty::Text);
                }
                ("tick_count", CommandValue::Float(count)) => {
                    node.props.bar_chart.tick_count = (count.round() as isize).clamp(2, 9) as usize;
                    return Some(Dirty::Text);
                }
                ("x_label", CommandValue::Text(label)) => {
                    node.props.bar_chart.x_label = (!label.trim().is_empty()).then_some(label);
                    return Some(Dirty::Text);
                }
                ("y_label", CommandValue::Text(label)) => {
                    node.props.bar_chart.y_label = (!label.trim().is_empty()).then_some(label);
                    return Some(Dirty::Text);
                }
                ("auto_fit", CommandValue::Bool(auto_fit)) => {
                    node.props.bar_chart.auto_fit = auto_fit;
                    if auto_fit {
                        node.props.bar_chart.value_min = None;
                        node.props.bar_chart.value_max = None;
                    }
                    return Some(Dirty::Visual);
                }
                (_, _) => {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                    );
                    return None;
                }
            }
        }
        if matches!(
            kind,
            WidgetKind::Button | WidgetKind::SmallButton | WidgetKind::Tab | WidgetKind::NavItem
        ) && prop == "badge"
        {
            let badge = match value {
                CommandValue::Text(text) => Some(text),
                CommandValue::Float(value) => Some(format_badge_number(value)),
                CommandValue::None => None,
                other => {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live badge value for widget {id:?}: {other:?}"
                    );
                    return None;
                }
            };
            if let Some(tree) = self.widget_tree.as_mut() {
                if set_widget_badge_prop(tree, id, badge) {
                    return Some(Dirty::Text);
                }
            }
            return None;
        }
        if matches!(kind, WidgetKind::Image | WidgetKind::ImageButton)
            && matches!(prop, "path" | "fit")
        {
            let CommandValue::Text(text) = value else {
                eprintln!(
                    "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                );
                return None;
            };
            if prop == "path" {
                if let Some(images) = self.images.as_mut() {
                    images.forget_path(&text);
                }
            }
            if let Some(tree) = self.widget_tree.as_mut() {
                if set_widget_image_prop(tree, id, prop, text) {
                    return Some(Dirty::Full);
                }
            }
            return None;
        }
        if kind == WidgetKind::HtmlReport {
            match (prop, value) {
                ("path" | "html" | "base_dir" | "text", CommandValue::Text(text)) => {
                    if let Some(tree) = self.widget_tree.as_mut() {
                        if set_widget_html_report_text_prop(tree, id, prop, Some(text)) {
                            return Some(if prop == "text" {
                                Dirty::Text
                            } else {
                                Dirty::Full
                            });
                        }
                    }
                    return None;
                }
                ("path" | "html" | "base_dir" | "text", CommandValue::None) => {
                    if let Some(tree) = self.widget_tree.as_mut() {
                        if set_widget_html_report_text_prop(tree, id, prop, None) {
                            return Some(if prop == "text" {
                                Dirty::Text
                            } else {
                                Dirty::Full
                            });
                        }
                    }
                    return None;
                }
                (
                    "allow_remote" | "allow_scripts" | "external_fallback",
                    CommandValue::Bool(enabled),
                ) => {
                    if let Some(tree) = self.widget_tree.as_mut() {
                        if set_widget_html_report_bool_prop(tree, id, prop, enabled) {
                            return Some(Dirty::Full);
                        }
                    }
                    return None;
                }
                (_, _) => {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                    );
                    return None;
                }
            }
        }
        let log_view_follow =
            kind == WidgetKind::LogView && prop == "value" && self.log_view_follow(id);
        let state = self.widget_state.as_mut()?;
        if matches!(kind, WidgetKind::Tabs | WidgetKind::Pages) && prop == "value" {
            let CommandValue::Text(value) = value else {
                eprintln!(
                    "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                );
                return None;
            };
            let changed = match kind {
                WidgetKind::Tabs => state.set_active_tab_value(id, &value).is_some(),
                WidgetKind::Pages => state.set_active_page_value(id, &value).is_some(),
                _ => false,
            };
            if !changed {
                eprintln!(
                    "DragonGUI: ignoring live SetProp for widget {id:?} ({kind:?}).{prop}: unknown or disabled route {value:?}"
                );
                return None;
            }
            if let Some(tree) = self.widget_tree.as_mut() {
                set_widget_route_value_prop(tree, id, value);
            }
            return Some(Dirty::Layout);
        }
        if kind == WidgetKind::Pane && prop == "size" {
            let size = match value {
                CommandValue::Float(value) => Some(value),
                CommandValue::None => None,
                other => {
                    eprintln!(
                        "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}: {other:?}"
                    );
                    return None;
                }
            };
            state.set_pane_size(id, size)?;
            if let Some(tree) = self.widget_tree.as_mut() {
                set_widget_pane_size_prop(tree, id, size);
            }
            return Some(Dirty::Layout);
        }
        match (kind, prop, value) {
            (WidgetKind::Checkbox | WidgetKind::ToggleSwitch, "checked", CommandValue::Bool(v)) => {
                state.set_checked(id, v)?;
                if let Some(tree) = self.widget_tree.as_mut() {
                    set_widget_checked_prop(tree, id, v);
                }
                Some(Dirty::Full)
            }
            (
                WidgetKind::Selectable | WidgetKind::RadioButton | WidgetKind::TreeNode,
                "checked",
                CommandValue::Bool(v),
            ) => {
                state.set_selectable_selected(id, v)?;
                if let Some(tree) = self.widget_tree.as_mut() {
                    set_widget_checked_prop(tree, id, v);
                }
                Some(Dirty::Full)
            }
            (WidgetKind::Slider, "value", CommandValue::Float(v)) => {
                state.try_set_float(id, v)?;
                Some(Dirty::Visual)
            }
            (WidgetKind::RangeSlider, "value_min", CommandValue::Float(v)) => {
                state.set_range_min_value(id, v)?;
                Some(Dirty::Visual)
            }
            (WidgetKind::RangeSlider, "value_max", CommandValue::Float(v)) => {
                state.set_range_max_value(id, v)?;
                Some(Dirty::Visual)
            }
            (WidgetKind::NumberInput | WidgetKind::DragNumber, "value", CommandValue::Float(v)) => {
                state.set_number_value(id, v)?;
                Some(Dirty::Text)
            }
            (WidgetKind::ProgressBar, "value", CommandValue::Float(v)) => {
                state.try_set_float(id, v)?;
                Some(Dirty::Visual)
            }
            (WidgetKind::Dropdown, "value", CommandValue::Text(v)) => {
                state.set_dropdown_value(id, &v)?;
                Some(Dirty::Text)
            }
            (
                WidgetKind::TextInput
                | WidgetKind::TextArea
                | WidgetKind::CodeEditor
                | WidgetKind::LogView,
                "value",
                CommandValue::Text(v),
            ) => {
                state.set_text_value(id, v)?;
                if log_view_follow {
                    state.text_scroll_y.insert(id.to_string(), f32::MAX);
                }
                Some(Dirty::Text)
            }
            (kind, prop, _) => {
                eprintln!(
                    "DragonGUI: ignoring unsupported live SetProp for widget {id:?} ({kind:?}).{prop}"
                );
                None
            }
        }
    }

    fn apply_set_style_patch(
        &mut self,
        id: &str,
        patch_json: &str,
    ) -> Result<Option<Dirty>, DragonError> {
        if !self.has_widget(id) {
            return Ok(None);
        }
        let patch: Value = serde_json::from_str(patch_json).map_err(|e| {
            DragonError::Runtime(format!("invalid live style patch for widget {id:?}: {e}"))
        })?;
        let Some(patch) = patch.as_object() else {
            return Err(DragonError::Runtime(format!(
                "live style patch for widget {id:?} must be a JSON object"
            )));
        };
        if patch.is_empty() {
            return Ok(None);
        }
        let Some(tree) = self.widget_tree.as_mut() else {
            return Ok(None);
        };
        let Some(node) = find_widget_mut(tree, id) else {
            return Ok(None);
        };
        merge_style_patch(&mut node.style_json, patch);
        reparse_inline_style(node);
        let dirty = style_patch_dirty(patch);
        if style_patch_can_merge_directly(patch) {
            merge_direct_style_patch(node, patch);
        } else {
            // A command drain may contain many inline-style mutations.
            // Reapplying the complete cascade here makes every SetStyle
            // O(tree), so defer one cascade to the merged rebuild boundary.
            self.mark_styles_dirty();
        }
        Ok(Some(dirty))
    }

    fn set_scatter_point_size_live(&mut self, id: &str, size: f32) -> bool {
        let logical_size = size.max(0.0);
        if let Some(tree) = self.widget_tree.as_mut() {
            if let Some(node) = find_widget_mut(tree, id) {
                node.style_json
                    .insert("scatter_point_size".to_string(), json!(logical_size));
                reparse_inline_style(node);
                node.style.widget.scatter_point_size = Some(logical_size);
            }
        }

        let Some(runtime) = self.scatters.get_mut(id) else {
            return false;
        };
        runtime
            .widget
            .set_point_size_override(Some(logical_size * self.scale_factor), &self.queue);
        runtime.primary_pick_cache = None;
        for actor in runtime.widget.extra_actors.values_mut() {
            actor.pick_cache = None;
        }
        true
    }

    fn update_inline_widget_style<F>(&mut self, id: &str, key: &str, value: Value, apply: F)
    where
        F: FnOnce(&mut WidgetStyle),
    {
        if let Some(tree) = self.widget_tree.as_mut() {
            if let Some(node) = find_widget_mut(tree, id) {
                node.style_json.insert(key.to_string(), value);
                reparse_inline_style(node);
                apply(&mut node.style.widget);
            }
        }
    }

    fn set_scatter_point_style_live(&mut self, id: &str, style: &str) -> bool {
        if let Some(tree) = self.widget_tree.as_mut() {
            if let Some(node) = find_widget_mut(tree, id) {
                node.style_json
                    .insert("scatter_point_style".to_string(), json!(style));
                reparse_inline_style(node);
                node.style.widget.scatter_point_style = Some(style.to_string());
            }
        }

        let Some(runtime) = self.scatters.get_mut(id) else {
            return false;
        };
        runtime.widget.set_point_style(Some(style), &self.queue);
        true
    }

    fn add_scatter_actor_points(
        &mut self,
        id: &str,
        actor_id: u32,
        pts: Vec<PointInstance>,
        hover_meta: Option<&str>,
        tooltip_axis_labels: &[String; 3],
        payload_bytes: usize,
        decode_ms: f64,
        total_t0: Instant,
    ) -> bool {
        let Some(runtime) = self.scatters.get_mut(id) else {
            return false;
        };
        let point_count = pts.len();
        let upload_t0 = Instant::now();
        runtime
            .widget
            .add_actor(actor_id, pts, &self.device, &self.queue);
        let upload_ms = upload_t0.elapsed().as_secs_f64() * 1000.0;
        if let Some(actor) = runtime.widget.extra_actors.get_mut(&actor_id) {
            actor.tooltip_axis_labels = tooltip_axis_labels.clone();
            if let Some(meta_json) = hover_meta {
                if let Ok(values) = serde_json::from_str::<Vec<serde_json::Value>>(meta_json) {
                    actor.hover_meta = values
                        .iter()
                        .map(|value| value.as_str().unwrap_or("").to_string())
                        .collect();
                }
            }
        }
        let (bounds_min, bounds_max) = runtime.merged_bounds();
        if !runtime.fitted_once && runtime.widget.has_visible_viewport() {
            let (fit_min, fit_max) = if runtime.points.is_empty() {
                runtime
                    .widget
                    .merged_extra_bounds()
                    .unwrap_or((bounds_min, bounds_max))
            } else {
                (bounds_min, bounds_max)
            };
            runtime.widget.fit_to_bounds(fit_min, fit_max, &self.queue);
            runtime.fitted_once = true;
        }
        let grid_t0 = Instant::now();
        runtime
            .widget
            .refresh_grid(bounds_min, bounds_max, &self.device, &self.queue);
        let grid_ms = grid_t0.elapsed().as_secs_f64() * 1000.0;
        let overlay_t0 = Instant::now();
        runtime.widget.refresh_overlays(&self.device, &self.queue);
        let overlay_ms = overlay_t0.elapsed().as_secs_f64() * 1000.0;
        runtime.metrics = ScatterMetrics {
            updates: runtime.metrics.updates + 1,
            last_point_count: point_count,
            last_payload_bytes: payload_bytes,
            last_pack_ms: 0.0,
            last_queue_latency_ms: 0.0,
            last_decode_ms: decode_ms,
            last_bounds_ms: 0.0,
            last_upload_ms: upload_ms,
            last_primary_upload_ms: 0.0,
            last_lod_ms: runtime.metrics.last_lod_ms,
            last_grid_ms: grid_ms,
            last_overlay_ms: overlay_ms,
            last_total_native_ms: total_t0.elapsed().as_secs_f64() * 1000.0,
            last_render_encode_ms: runtime.metrics.last_render_encode_ms,
            last_render_redraw_ms: runtime.metrics.last_render_redraw_ms,
            last_render_composite_ms: runtime.metrics.last_render_composite_ms,
            last_render_cache_hit: runtime.metrics.last_render_cache_hit,
            ..runtime.metrics.clone()
        };
        true
    }

    fn update_scatter_actor_points(
        &mut self,
        id: &str,
        actor_id: u32,
        pts: Vec<PointInstance>,
        tooltip_axis_labels: &[String; 3],
        payload_bytes: usize,
        decode_ms: f64,
        total_t0: Instant,
    ) -> bool {
        let Some(runtime) = self.scatters.get_mut(id) else {
            return false;
        };
        if !runtime.widget.extra_actors.contains_key(&actor_id) {
            return false;
        }
        let point_count = pts.len();
        let upload_t0 = Instant::now();
        runtime
            .widget
            .update_actor(actor_id, pts, &self.device, &self.queue);
        let upload_ms = upload_t0.elapsed().as_secs_f64() * 1000.0;
        if let Some(actor) = runtime.widget.extra_actors.get_mut(&actor_id) {
            actor.tooltip_axis_labels = tooltip_axis_labels.clone();
            actor.pick_cache = None;
        }
        let (bounds_min, bounds_max) = runtime.merged_bounds();
        if !runtime.fitted_once && runtime.widget.has_visible_viewport() {
            let (fit_min, fit_max) = if runtime.points.is_empty() {
                runtime
                    .widget
                    .merged_extra_bounds()
                    .unwrap_or((bounds_min, bounds_max))
            } else {
                (bounds_min, bounds_max)
            };
            runtime.widget.fit_to_bounds(fit_min, fit_max, &self.queue);
            runtime.fitted_once = true;
        }
        let grid_t0 = Instant::now();
        runtime
            .widget
            .refresh_grid(bounds_min, bounds_max, &self.device, &self.queue);
        let grid_ms = grid_t0.elapsed().as_secs_f64() * 1000.0;
        let overlay_t0 = Instant::now();
        runtime.widget.refresh_overlays(&self.device, &self.queue);
        let overlay_ms = overlay_t0.elapsed().as_secs_f64() * 1000.0;
        runtime.metrics = ScatterMetrics {
            updates: runtime.metrics.updates + 1,
            last_point_count: point_count,
            last_payload_bytes: payload_bytes,
            last_pack_ms: 0.0,
            last_queue_latency_ms: 0.0,
            last_decode_ms: decode_ms,
            last_bounds_ms: 0.0,
            last_upload_ms: upload_ms,
            last_primary_upload_ms: 0.0,
            last_lod_ms: runtime.metrics.last_lod_ms,
            last_grid_ms: grid_ms,
            last_overlay_ms: overlay_ms,
            last_total_native_ms: total_t0.elapsed().as_secs_f64() * 1000.0,
            last_render_encode_ms: runtime.metrics.last_render_encode_ms,
            last_render_redraw_ms: runtime.metrics.last_render_redraw_ms,
            last_render_composite_ms: runtime.metrics.last_render_composite_ms,
            last_render_cache_hit: runtime.metrics.last_render_cache_hit,
            ..runtime.metrics.clone()
        };
        true
    }

    fn stream_scatter_actor_points(
        &mut self,
        id: &str,
        actor_id: u32,
        pts: &[PointInstance],
    ) -> bool {
        let Some(runtime) = self.scatters.get_mut(id) else {
            return false;
        };
        runtime.widget.stream_actor(actor_id, pts, &self.queue);
        if let Some(actor) = runtime.widget.extra_actors.get_mut(&actor_id) {
            actor.pick_cache = None;
        }
        let (bounds_min, bounds_max) = runtime.merged_bounds();
        runtime
            .widget
            .refresh_grid(bounds_min, bounds_max, &self.device, &self.queue);
        runtime.widget.refresh_overlays(&self.device, &self.queue);
        true
    }

    fn prewarm_scatter_widgets(&mut self, count: usize) -> usize {
        let target = count.min(64);
        let missing = target.saturating_sub(self.scatter_widget_pool.len());
        if missing == 0 {
            self.prewarm_scatter_widget_timing.record(0.0);
            return 0;
        }
        let t0 = Instant::now();
        for _ in 0..missing {
            self.scatter_widget_pool.push(ScatterWidget::new(
                &self.device,
                self.config.format,
                self.config.width.max(1),
                self.config.height.max(1),
            ));
        }
        self.prewarm_scatter_widget_timing
            .record(t0.elapsed().as_secs_f64() * 1000.0);
        missing
    }

    fn take_scatter_widget(&mut self) -> ScatterWidget {
        self.scatter_widget_pool.pop().unwrap_or_else(|| {
            ScatterWidget::new(
                &self.device,
                self.config.format,
                self.config.width.max(1),
                self.config.height.max(1),
            )
        })
    }

    fn rebuild_retained_maps(&mut self) {
        let total_t0 = Instant::now();
        let mut widget_kinds = HashMap::new();
        let mut tooltip_overlay_targets = HashSet::new();
        let previous_state = self.widget_state.as_ref();
        let mut widget_state = None;
        if let Some(tree) = self.widget_tree.as_ref() {
            let kinds_t0 = Instant::now();
            collect_widget_kinds(tree, &mut widget_kinds);
            collect_tooltip_overlay_targets(tree, &mut tooltip_overlay_targets);
            self.retained_widget_kinds_timing
                .record(kinds_t0.elapsed().as_secs_f64() * 1000.0);

            let resources_t0 = Instant::now();
            self.resources.sync_from_tree(tree);
            self.retained_resources_timing
                .record(resources_t0.elapsed().as_secs_f64() * 1000.0);

            let state_t0 = Instant::now();
            widget_state = Some(WidgetState::from_tree(tree));
            self.retained_widget_state_timing
                .record(state_t0.elapsed().as_secs_f64() * 1000.0);
        }
        let preserve_t0 = Instant::now();
        if let (Some(previous), Some(current)) = (previous_state, widget_state.as_mut()) {
            current.preserve_rebuild_state_from(previous);
        }
        self.retained_state_preserve_timing
            .record(preserve_t0.elapsed().as_secs_f64() * 1000.0);
        if self.widget_tree.is_none() {
            self.resources = ResourceRegistry::default();
        }

        // Sync scatter runtime map: add new widgets, drop removed ones.
        let scatter_t0 = Instant::now();
        let collect_t0 = Instant::now();
        let mut current_ids: Vec<String> = Vec::new();
        if let Some(tree) = &self.widget_tree {
            collect_all_scatter_ids(tree, &mut current_ids);
        }
        self.retained_scatter_collect_timing
            .record(collect_t0.elapsed().as_secs_f64() * 1000.0);
        // Drop runtimes for ids no longer in the tree.
        let retain_t0 = Instant::now();
        self.scatters.retain(|id, _| current_ids.contains(id));
        self.retained_scatter_retain_timing
            .record(retain_t0.elapsed().as_secs_f64() * 1000.0);
        // Add runtimes for newly appeared scatter nodes.
        for id in &current_ids {
            if !self.scatters.contains_key(id) {
                let node = self
                    .widget_tree
                    .as_ref()
                    .and_then(|tree| find_widget(tree, id));
                let (colormap, data_b64, data_format, startup_chrome, interaction_mode) = node
                    .map(|n| {
                        let chrome = scatter_chrome_from_node(n);
                        (
                            n.props
                                .scatter_colormap
                                .clone()
                                .unwrap_or_else(|| "viridis".to_string()),
                            n.props.scatter_data_b64.clone(),
                            n.props.scatter_data_format,
                            chrome,
                            scatter_interaction_mode_from_node(n),
                        )
                    })
                    .unwrap_or_else(|| {
                        (
                            "viridis".to_string(),
                            None,
                            ScatterPayloadFormat::default(),
                            scatter::ScatterChromeState::default(),
                            scatter::ScatterInteractionMode::default(),
                        )
                    });

                let widget_t0 = Instant::now();
                let mut widget = self.take_scatter_widget();
                widget.interaction_mode = interaction_mode;
                self.retained_scatter_new_widget_timing
                    .record(widget_t0.elapsed().as_secs_f64() * 1000.0);
                let decode_t0 = Instant::now();
                let (mut pts, mut status) = if let Some(b64) = data_b64 {
                    let decoded_bytes = BASE64.decode(&b64);
                    match decoded_bytes {
                        Err(e) => {
                            let msg = format!("scatter base64 decode: {e}");
                            eprintln!("DragonGUI: {msg}");
                            (Vec::new(), ScatterPayloadStatus::DecodeError(msg))
                        }
                        Ok(bytes) => {
                            let mut pts = Vec::new();
                            let result = match data_format {
                                ScatterPayloadFormat::XyzF32V0 => {
                                    decode_scatter_points_bytes_into_colormap(
                                        &bytes, &mut pts, &colormap,
                                    )
                                }
                                ScatterPayloadFormat::PointInstanceV1 => {
                                    decode_scatter_points_v1(&bytes, &mut pts)
                                }
                            };
                            match result {
                                Err(e) => {
                                    let msg = e.to_string();
                                    eprintln!("DragonGUI: {msg}");
                                    (Vec::new(), ScatterPayloadStatus::DecodeError(msg))
                                }
                                Ok(_) => (pts, ScatterPayloadStatus::Ok),
                            }
                        }
                    }
                } else {
                    (Vec::new(), ScatterPayloadStatus::Empty)
                };
                self.retained_scatter_decode_timing
                    .record(decode_t0.elapsed().as_secs_f64() * 1000.0);

                let upload_t0 = Instant::now();
                let maybe_bounds = compute_scatter_bounds(&pts);
                if maybe_bounds.is_none() && !pts.is_empty() {
                    status = ScatterPayloadStatus::AllNonFinite;
                    pts.clear();
                }
                let (data_min, data_max) =
                    maybe_bounds.unwrap_or((glam::Vec3::ZERO, glam::Vec3::ZERO));
                if !pts.is_empty() {
                    widget.set_points(&self.device, &self.queue, &pts);
                    widget.fit_to_bounds(data_min, data_max, &self.queue);
                } else {
                    widget.update_camera(&self.queue);
                }
                self.retained_scatter_upload_timing
                    .record(upload_t0.elapsed().as_secs_f64() * 1000.0);
                let chrome_t0 = Instant::now();
                widget.set_chrome(startup_chrome);
                widget.refresh_grid(data_min, data_max, &self.device, &self.queue);
                widget.refresh_overlays(&self.device, &self.queue);
                self.retained_scatter_chrome_timing
                    .record(chrome_t0.elapsed().as_secs_f64() * 1000.0);

                self.scatters.insert(
                    id.clone(),
                    ScatterRuntime {
                        widget,
                        render_target: None,
                        last_direct_scene_revision: 0,
                        quality_last_change: Instant::now(),
                        points: pts,
                        primary_compact_xyz: Vec::new(),
                        primary_compact_colormap: colormap.clone(),
                        metrics: ScatterMetrics::default(),
                        fitted_once: matches!(status, ScatterPayloadStatus::Ok),
                        data_min,
                        data_max,
                        payload_format: data_format,
                        payload_status: status,
                        pending_fit_bounds: None,
                        primary_hover_meta: Vec::new(),
                        primary_hover_columns: Vec::new(),
                        tooltip_axis_labels: ["x".to_string(), "y".to_string(), "z".to_string()],
                        hover_tooltip_enabled: true,
                        primary_pick_cache: None,
                        pick_candidates_scratch: Vec::new(),
                    },
                );
            }
        }
        if let Some(tree) = &self.widget_tree {
            for id in &current_ids {
                if let (Some(runtime), Some(node)) =
                    (self.scatters.get_mut(id), find_widget(tree, id))
                {
                    runtime.widget.interaction_mode = scatter_interaction_mode_from_node(node);
                }
            }
        }
        self.retained_scatter_sync_timing
            .record(scatter_t0.elapsed().as_secs_f64() * 1000.0);

        let line_plot_t0 = Instant::now();
        self.line_plot_metrics
            .retain(|id, _| widget_kinds.get(id) == Some(&WidgetKind::LinePlot));
        self.retained_line_plot_sync_timing
            .record(line_plot_t0.elapsed().as_secs_f64() * 1000.0);
        self.widget_kinds = widget_kinds;
        self.tooltip_overlay_targets = tooltip_overlay_targets;
        self.widget_state = widget_state;
        self.retained_maps_timing
            .record(total_t0.elapsed().as_secs_f64() * 1000.0);
    }

    fn apply_replace_children(
        &mut self,
        id: &str,
        children_json: &str,
    ) -> Result<bool, DragonError> {
        if !self.has_widget(id) {
            return Ok(false);
        }
        let parse_t0 = Instant::now();
        let children = parse_widget_children_json(children_json)?;
        self.replace_children_parse_timing
            .record(parse_t0.elapsed().as_secs_f64() * 1000.0);
        let Some(tree) = self.widget_tree.as_mut() else {
            return Ok(false);
        };
        let swap_t0 = Instant::now();
        if !replace_widget_children(tree, id, children) {
            return Ok(false);
        }
        self.icon_theme
            .apply_to_tree(tree)
            .map_err(DragonError::Runtime)?;
        self.replace_children_swap_timing
            .record(swap_t0.elapsed().as_secs_f64() * 1000.0);

        let maps_t0 = Instant::now();
        self.rebuild_retained_maps();
        self.replace_children_maps_timing
            .record(maps_t0.elapsed().as_secs_f64() * 1000.0);
        Ok(true)
    }

    fn apply_replace_node(&mut self, id: &str, node_json: &str) -> Result<bool, DragonError> {
        if !self.has_widget(id) {
            return Ok(false);
        }
        let parse_t0 = Instant::now();
        let replacement = parse_widget_node_json(node_json)?;
        self.replace_node_parse_timing
            .record(parse_t0.elapsed().as_secs_f64() * 1000.0);
        let Some(tree) = self.widget_tree.as_mut() else {
            return Ok(false);
        };
        let swap_t0 = Instant::now();
        if !replace_widget_node(tree, id, replacement) {
            return Ok(false);
        }
        self.icon_theme
            .apply_to_tree(tree)
            .map_err(DragonError::Runtime)?;
        self.replace_node_swap_timing
            .record(swap_t0.elapsed().as_secs_f64() * 1000.0);

        let maps_t0 = Instant::now();
        self.rebuild_retained_maps();
        self.replace_node_maps_timing
            .record(maps_t0.elapsed().as_secs_f64() * 1000.0);
        Ok(true)
    }

    fn apply_update_extension_display_list(
        &mut self,
        id: &str,
        display_list_json: &str,
    ) -> Result<Option<Dirty>, DragonError> {
        if self.widget_kind(id) != Some(WidgetKind::Extension) {
            return Ok(None);
        }
        let display_list: serde_json::Value = serde_json::from_str(display_list_json)
            .map_err(|error| DragonError::Runtime(format!("invalid display-list JSON: {error}")))?;
        let Some(commands) = display_list.as_array() else {
            return Err(DragonError::Runtime(
                "extension display list must be a JSON array".to_string(),
            ));
        };
        if commands
            .iter()
            .any(|command| command.get("cmd").and_then(serde_json::Value::as_str) == Some("image"))
        {
            return Err(DragonError::Runtime(
                "paint-only display-list updates cannot change image resources".to_string(),
            ));
        }
        let Some(tree) = self.widget_tree.as_mut() else {
            return Ok(None);
        };
        let Some(node) = find_widget_mut(tree, id) else {
            return Ok(None);
        };
        let dirty =
            extension_display_list_dirty(node.props.raw_props.get("display_list"), &display_list);
        node.props
            .raw_props
            .insert("display_list".to_string(), display_list);
        Ok(Some(dirty))
    }

    fn apply_set_table_data(&mut self, id: &str, table_json: &str) -> Result<bool, DragonError> {
        if self.widget_kind(id) != Some(WidgetKind::DataFrameTable) {
            return Ok(false);
        }
        let props = parse_table_update_json(id, table_json)?;
        let Some(tree) = self.widget_tree.as_mut() else {
            return Ok(false);
        };
        let Some(node) = find_widget_mut(tree, id) else {
            return Ok(false);
        };
        node.props.table_columns = props.table_columns;
        node.props.table_dtypes = props.table_dtypes;
        node.props.table_rows = props.table_rows;
        node.props.table_resource_id = props.table_resource_id;
        node.props.table_sample_rows = props.table_sample_rows;
        node.props.page_size = props.page_size;
        node.props.table_cells = props.table_cells;

        self.rebuild_retained_maps();
        Ok(true)
    }

    fn apply_set_table_data_columns(
        &mut self,
        id: &str,
        table_json: &str,
        columns: Vec<TableColumnPacket>,
    ) -> Result<bool, DragonError> {
        if self.widget_kind(id) != Some(WidgetKind::DataFrameTable) {
            return Ok(false);
        }
        let props = parse_table_update_json(id, table_json)?;
        let Some(resource_id) = props.table_resource_id.clone() else {
            return Err(DragonError::Runtime(
                "table column update requires a resource_id".to_string(),
            ));
        };
        let Some(tree) = self.widget_tree.as_mut() else {
            return Ok(false);
        };
        let Some(node) = find_widget_mut(tree, id) else {
            return Ok(false);
        };
        node.props.table_columns = props.table_columns.clone();
        node.props.table_dtypes = props.table_dtypes.clone();
        node.props.table_rows = props.table_rows;
        node.props.table_resource_id = props.table_resource_id.clone();
        node.props.table_sample_rows = props.table_sample_rows;
        node.props.page_size = props.page_size;
        node.props.table_cells = props.table_cells.clone();

        self.resources
            .update_table_columns(&resource_id, &props, columns);
        self.rebuild_retained_maps();
        Ok(true)
    }

    fn apply_set_buffer_resource(
        &mut self,
        id: &str,
        kind: &str,
        bytes: Vec<u8>,
        owner_id: Option<String>,
    ) -> bool {
        self.resources
            .update_buffer(id.to_string(), kind.to_string(), bytes, owner_id);
        true
    }

    fn set_line_plot_data_packed(
        &mut self,
        id: &str,
        series: String,
        xy: Vec<u8>,
        label: Option<String>,
        color: Option<String>,
        line_width: Option<f32>,
        line_style: Option<String>,
        show_grid: Option<bool>,
        auto_fit: Option<bool>,
        max_points: Option<usize>,
        payload_format: LinePlotPayloadFormat,
    ) -> Result<bool, DragonError> {
        if self.widget_kind(id) != Some(WidgetKind::LinePlot) {
            return Ok(false);
        }
        let total_t0 = Instant::now();
        let payload_bytes = xy.len();
        let series_for_metrics = series.clone();
        let decode_t0 = Instant::now();
        let mut points = decode_line_plot_points_bytes(&xy, payload_format)?;
        let decode_ms = decode_t0.elapsed().as_secs_f64() * 1000.0;
        let trim_t0 = Instant::now();
        let trimmed_points = limit_line_plot_points(&mut points, max_points);
        let trim_ms = trim_t0.elapsed().as_secs_f64() * 1000.0;
        let bounds_t0 = Instant::now();
        let bounds = document::line_plot_points_bounds(&points);
        let x_sorted = document::line_plot_points_x_sorted(&points);
        let bounds_ms = bounds_t0.elapsed().as_secs_f64() * 1000.0;
        let (series_count, total_points, visible_points, window_ms, count_ms) = {
            let Some(tree) = self.widget_tree.as_mut() else {
                return Ok(false);
            };
            let Some(node) = find_widget_mut(tree, id) else {
                return Ok(false);
            };
            if let Some(width) = line_width {
                node.props.line_plot_line_width = width.max(0.5);
            }
            if let Some(show_grid) = show_grid {
                node.props.line_plot_show_grid = show_grid;
            }
            if let Some(auto_fit) = auto_fit {
                node.props.line_plot_auto_fit = auto_fit;
            }
            let label = label
                .filter(|value| !value.trim().is_empty())
                .unwrap_or_else(|| series.clone());
            let color = parse_line_plot_color(color);
            let line_style =
                line_style.map(|value| document::parse_line_plot_line_style(Some(&value)));
            let point_count = points.len();
            if let Some(existing) = node
                .props
                .line_plot_series
                .iter_mut()
                .find(|item| item.label.as_deref() == Some(series.as_str()))
            {
                existing.label = Some(label);
                if color.is_some() {
                    existing.color = color;
                }
                if let Some(line_style) = line_style.clone() {
                    existing.line_style = line_style;
                }
                existing.points = points;
                existing.front_offset = 0;
                existing.rebuild_y_blocks();
                existing.bounds = bounds;
                existing.x_sorted = x_sorted;
                existing.payload_format = payload_format;
                existing.declared_point_count = Some(point_count);
            } else {
                let y_blocks = document::line_plot_y_blocks(&points);
                node.props
                    .line_plot_series
                    .push(document::LinePlotSeriesProp {
                        label: Some(label),
                        color,
                        line_style: line_style.unwrap_or_else(|| "solid".to_string()),
                        points,
                        front_offset: 0,
                        y_blocks,
                        bounds,
                        x_sorted,
                        payload_format,
                        declared_point_count: Some(point_count),
                    });
            }
            let window_t0 = Instant::now();
            apply_line_plot_window_to_node(node);
            let window_ms = window_t0.elapsed().as_secs_f64() * 1000.0;
            let count_t0 = Instant::now();
            let (series_count, total_points, visible_points) = line_plot_point_counts(node);
            let count_ms = count_t0.elapsed().as_secs_f64() * 1000.0;
            (
                series_count,
                total_points,
                visible_points,
                window_ms,
                count_ms,
            )
        };
        let metrics = self.line_plot_metrics.entry(id.to_string()).or_default();
        metrics.updates += 1;
        metrics.sets += 1;
        metrics.last_operation = "set";
        metrics.last_series = Some(series_for_metrics);
        metrics.last_series_count = series_count;
        metrics.last_point_count = total_points;
        metrics.last_visible_point_count = visible_points;
        metrics.last_appended_points = 0;
        metrics.last_trimmed_points = trimmed_points;
        metrics.last_payload_bytes = payload_bytes;
        metrics.last_decode_ms = decode_ms;
        metrics.last_bounds_ms = bounds_ms;
        metrics.last_trim_ms = trim_ms;
        metrics.last_window_ms = window_ms;
        metrics.last_count_ms = count_ms;
        metrics.last_total_native_ms = total_t0.elapsed().as_secs_f64() * 1000.0;
        Ok(true)
    }

    fn append_line_plot_points_packed(
        &mut self,
        id: &str,
        series: String,
        xy: Vec<u8>,
        max_points: Option<usize>,
        payload_format: LinePlotPayloadFormat,
    ) -> Result<bool, DragonError> {
        if self.widget_kind(id) != Some(WidgetKind::LinePlot) {
            return Ok(false);
        }
        let total_t0 = Instant::now();
        let payload_bytes = xy.len();
        let series_for_metrics = series.clone();
        let decode_t0 = Instant::now();
        let mut points = decode_line_plot_points_bytes(&xy, payload_format)?;
        let decode_ms = decode_t0.elapsed().as_secs_f64() * 1000.0;
        let appended_points = points.len();
        let bounds_t0 = Instant::now();
        let appended_bounds = document::line_plot_points_bounds(&points);
        let appended_x_sorted = document::line_plot_points_x_sorted(&points);
        let mut bounds_ms = bounds_t0.elapsed().as_secs_f64() * 1000.0;
        let mut trim_ms = 0.0;
        let (series_count, total_points, visible_points, trimmed_points, window_ms, count_ms) = {
            let Some(tree) = self.widget_tree.as_mut() else {
                return Ok(false);
            };
            let Some(node) = find_widget_mut(tree, id) else {
                return Ok(false);
            };
            let trimmed_points = if let Some(existing) = node
                .props
                .line_plot_series
                .iter_mut()
                .find(|item| item.label.as_deref() == Some(series.as_str()))
            {
                let prior_bounds = existing.bounds;
                let combined_bounds = merge_line_plot_bounds(prior_bounds, appended_bounds);
                let existing_logical_len = existing.logical_len();
                let x_sorted = existing.x_sorted
                    && appended_x_sorted
                    && line_plot_append_preserves_x_order(existing.logical_points(), &points);
                let old_physical_len = existing.points.len();
                existing.points.append(&mut points);
                existing.rebuild_y_blocks_from(old_physical_len);
                let trimmed =
                    line_plot_front_trim_count(existing_logical_len + appended_points, max_points);
                existing.bounds = if trimmed > 0 {
                    let bounds_t0 = Instant::now();
                    let bounds = line_plot_bounds_after_front_trim(
                        existing.logical_points(),
                        trimmed,
                        combined_bounds,
                        x_sorted,
                    );
                    bounds_ms += bounds_t0.elapsed().as_secs_f64() * 1000.0;
                    let trim_t0 = Instant::now();
                    existing.front_offset = existing
                        .front_offset
                        .saturating_add(trimmed)
                        .min(existing.points.len());
                    existing.maybe_compact_front_offset();
                    trim_ms += trim_t0.elapsed().as_secs_f64() * 1000.0;
                    bounds
                } else {
                    combined_bounds
                };
                existing.x_sorted = x_sorted;
                existing.declared_point_count = Some(existing.logical_len());
                trimmed
            } else {
                let trimmed = line_plot_front_trim_count(points.len(), max_points);
                let bounds = if trimmed > 0 {
                    let bounds_t0 = Instant::now();
                    let bounds = line_plot_bounds_after_front_trim(
                        &points,
                        trimmed,
                        appended_bounds,
                        appended_x_sorted,
                    );
                    bounds_ms += bounds_t0.elapsed().as_secs_f64() * 1000.0;
                    bounds
                } else {
                    appended_bounds
                };
                let point_count = points.len().saturating_sub(trimmed);
                let y_blocks = document::line_plot_y_blocks(&points);
                node.props
                    .line_plot_series
                    .push(document::LinePlotSeriesProp {
                        label: Some(series),
                        color: None,
                        line_style: "solid".to_string(),
                        points,
                        front_offset: trimmed,
                        y_blocks,
                        bounds,
                        x_sorted: appended_x_sorted,
                        payload_format,
                        declared_point_count: Some(point_count),
                    });
                trimmed
            };
            let window_t0 = Instant::now();
            apply_line_plot_window_to_node(node);
            let window_ms = window_t0.elapsed().as_secs_f64() * 1000.0;
            let count_t0 = Instant::now();
            let (series_count, total_points, visible_points) = line_plot_point_counts(node);
            let count_ms = count_t0.elapsed().as_secs_f64() * 1000.0;
            (
                series_count,
                total_points,
                visible_points,
                trimmed_points,
                window_ms,
                count_ms,
            )
        };
        let metrics = self.line_plot_metrics.entry(id.to_string()).or_default();
        metrics.updates += 1;
        metrics.appends += 1;
        metrics.last_operation = "append";
        metrics.last_series = Some(series_for_metrics);
        metrics.last_series_count = series_count;
        metrics.last_point_count = total_points;
        metrics.last_visible_point_count = visible_points;
        metrics.last_appended_points = appended_points;
        metrics.last_trimmed_points = trimmed_points;
        metrics.last_payload_bytes = payload_bytes;
        metrics.last_decode_ms = decode_ms;
        metrics.last_bounds_ms = bounds_ms;
        metrics.last_trim_ms = trim_ms;
        metrics.last_window_ms = window_ms;
        metrics.last_count_ms = count_ms;
        metrics.last_total_native_ms = total_t0.elapsed().as_secs_f64() * 1000.0;
        Ok(true)
    }

    fn clear_line_plot_series(&mut self, id: &str, series: Option<String>) -> bool {
        if self.widget_kind(id) != Some(WidgetKind::LinePlot) {
            return false;
        }
        let Some(tree) = self.widget_tree.as_mut() else {
            return false;
        };
        let Some(node) = find_widget_mut(tree, id) else {
            return false;
        };
        if let Some(series) = series {
            for item in &mut node.props.line_plot_series {
                if item.label.as_deref() == Some(series.as_str()) {
                    item.points.clear();
                    item.front_offset = 0;
                    item.y_blocks.clear();
                    item.bounds = None;
                    item.x_sorted = true;
                    item.declared_point_count = Some(0);
                }
            }
        } else {
            for item in &mut node.props.line_plot_series {
                item.points.clear();
                item.front_offset = 0;
                item.y_blocks.clear();
                item.bounds = None;
                item.x_sorted = true;
                item.declared_point_count = Some(0);
            }
        }
        true
    }

    fn activate_line_plot_toolbar(&mut self, id: &str, pos: [f32; 2]) -> bool {
        if self.widget_kind(id) != Some(WidgetKind::LinePlot) {
            return false;
        }
        let hit = {
            let Some(layout) = self.current_layout.as_ref() else {
                return false;
            };
            let Some(rect) = layout.visible_rect(id) else {
                return false;
            };
            let Some(tree) = self.widget_tree.as_ref() else {
                return false;
            };
            let Some(node) = find_node(tree, id) else {
                return false;
            };
            line_plot_toolbar_hit(
                node,
                self.scale_factor,
                [rect.x, rect.y, rect.w, rect.h],
                pos,
            )
        };
        let Some(action) = hit else {
            return false;
        };
        let Some(tree) = self.widget_tree.as_mut() else {
            return false;
        };
        let Some(node) = find_widget_mut(tree, id) else {
            return false;
        };
        match action {
            "Fit" => {
                node.props.line_plot_auto_fit = true;
                node.props.line_plot_x_min = None;
                node.props.line_plot_x_max = None;
                node.props.line_plot_y_min = None;
                node.props.line_plot_y_max = None;
            }
            "Pan" => {
                node.props.line_plot_interaction = if node.props.line_plot_interaction == "pan" {
                    "inspect"
                } else {
                    "pan"
                }
                .to_string();
            }
            "Zoom" => {
                node.props.line_plot_interaction = if node.props.line_plot_interaction == "zoom" {
                    "inspect"
                } else {
                    "zoom"
                }
                .to_string();
            }
            "Box" => {
                node.props.line_plot_interaction =
                    if node.props.line_plot_interaction == "box_zoom" {
                        "inspect"
                    } else {
                        "box_zoom"
                    }
                    .to_string();
                node.props.line_plot_selection_rect = None;
            }
            "Grid" => {
                node.props.line_plot_show_grid = !node.props.line_plot_show_grid;
            }
            "Axes" => {
                let visible = !(node.props.line_plot_show_axes || node.props.line_plot_show_ticks);
                node.props.line_plot_show_axes = visible;
                node.props.line_plot_show_ticks = visible;
            }
            _ => return false,
        }
        self.rebuild_primitives();
        true
    }

