    fn update_line_plot_hover(&mut self, pos: [f32; 2]) -> bool {
        let hit = self.line_plot_at(pos).and_then(|id| {
            (self.line_plot_interaction(&id) == Some("inspect"))
                .then(|| {
                    self.nearest_line_plot_point(&id, pos)
                        .map(|hover| (id, hover))
                })
                .flatten()
        });
        let mut changed = false;
        let mut dirty_ids = Vec::new();
        let Some(tree) = self.widget_tree.as_mut() else {
            return false;
        };
        clear_line_plot_hover_except(
            tree,
            hit.as_ref().map(|(id, _)| id.as_str()),
            &mut changed,
            &mut dirty_ids,
        );
        if let Some((id, hover)) = hit {
            if let Some(node) = find_widget_mut(tree, &id) {
                let should_update = node.props.line_plot_hover.as_ref().is_none_or(|current| {
                    (current.screen[0] - hover.screen[0]).abs() > 0.5
                        || (current.screen[1] - hover.screen[1]).abs() > 0.5
                        || (current.plot[0] - hover.plot[0]).abs() > f32::EPSILON
                        || (current.plot[1] - hover.plot[1]).abs() > f32::EPSILON
                        || current.label != hover.label
                });
                if should_update {
                    node.props.line_plot_hover = Some(hover);
                    dirty_ids.push(id);
                    changed = true;
                }
            }
        }
        if changed {
            self.rebuild_interaction_visuals(
                &dirty_ids.into_iter().collect(),
                &HashSet::new(),
                false,
            );
        }
        changed
    }

    fn clear_line_plot_hover_all(&mut self) -> bool {
        let Some(tree) = self.widget_tree.as_mut() else {
            return false;
        };
        let mut changed = false;
        let mut cleared_ids = Vec::new();
        clear_line_plot_hover_except(tree, None, &mut changed, &mut cleared_ids);
        if changed {
            self.rebuild_interaction_visuals(
                &cleared_ids.into_iter().collect(),
                &HashSet::new(),
                false,
            );
        }
        changed
    }

    fn update_heatmap_hover(&mut self, pos: [f32; 2]) -> (bool, Vec<(String, String)>) {
        let hit = self
            .heatmap_at(pos)
            .and_then(|id| self.heatmap_cell_at(&id, pos).map(|hover| (id, hover)));
        let keep_id = hit.as_ref().map(|(id, _)| id.clone());
        let mut changed = false;
        let mut cleared_ids = Vec::new();
        let mut dirty_ids = HashSet::new();
        let mut payloads = Vec::new();
        let Some(tree) = self.widget_tree.as_mut() else {
            return (false, payloads);
        };
        clear_heatmap_hover_except(tree, keep_id.as_deref(), &mut changed, &mut cleared_ids);
        for id in cleared_ids {
            dirty_ids.insert(id.clone());
            payloads.push((
                id.clone(),
                json!({"event":"hover_changed","widget_id": id}).to_string(),
            ));
        }
        if let Some((id, hover)) = hit {
            if let Some(node) = find_widget_mut(tree, &id) {
                let should_update = node.props.heatmap.hover.as_ref().is_none_or(|current| {
                    current.row != hover.row
                        || current.col != hover.col
                        || (current.value - hover.value).abs() > f32::EPSILON
                });
                if should_update {
                    let payload = heatmap_hover_payload(&id, &hover);
                    node.props.heatmap.hover = Some(hover);
                    changed = true;
                    dirty_ids.insert(id.clone());
                    payloads.push((id, payload));
                }
            }
        }
        if changed {
            self.rebuild_interaction_visuals(&dirty_ids, &HashSet::new(), false);
        }
        (changed, payloads)
    }

    fn clear_heatmap_hover_all(&mut self) -> (bool, Vec<(String, String)>) {
        let Some(tree) = self.widget_tree.as_mut() else {
            return (false, Vec::new());
        };
        let mut changed = false;
        let mut cleared_ids = Vec::new();
        clear_heatmap_hover_except(tree, None, &mut changed, &mut cleared_ids);
        if changed {
            self.rebuild_interaction_visuals(
                &cleared_ids.iter().cloned().collect(),
                &HashSet::new(),
                false,
            );
        }
        let payloads = cleared_ids
            .into_iter()
            .map(|id| {
                (
                    id.clone(),
                    json!({"event":"hover_changed","widget_id": id}).to_string(),
                )
            })
            .collect();
        (changed, payloads)
    }

