    fn nearest_line_plot_point(&self, id: &str, pos: [f32; 2]) -> Option<LinePlotHoverProp> {
        let (plot, bounds) = self.line_plot_plot_rect_and_bounds(id)?;
        if pos[0] < plot[0]
            || pos[0] > plot[0] + plot[2]
            || pos[1] < plot[1]
            || pos[1] > plot[1] + plot[3]
        {
            return None;
        }
        let tree = self.widget_tree.as_ref()?;
        let node = find_node(tree, id)?;
        let mut best: Option<(f32, LinePlotHoverProp)> = None;
        let radius = 18.0_f32;
        for series in &node.props.line_plot_series {
            let points = series.logical_points();
            let (start, end) = line_plot_hover_x_range(points, bounds, plot, pos, radius);
            for point in &points[start..end] {
                let Some(screen) = map_line_plot_point_to_screen(*point, plot, bounds) else {
                    continue;
                };
                let dx = screen[0] - pos[0];
                let dy = screen[1] - pos[1];
                let d2 = dx * dx + dy * dy;
                if best.as_ref().is_none_or(|(best_d2, _)| d2 < *best_d2) {
                    best = Some((
                        d2,
                        LinePlotHoverProp {
                            screen,
                            plot: *point,
                            label: series.label.clone(),
                            color: series.color.clone(),
                        },
                    ));
                }
            }
        }
        best.and_then(|(d2, hover)| (d2 <= radius.powi(2)).then_some(hover))
    }

    fn refresh_table_sort(&mut self, id: &str) {
        let Some((resource_id, sort, rows)) = self
            .widget_state
            .as_ref()
            .and_then(|state| state.table(id))
            .map(|table| (table.resource_id.clone(), table.sort, table.rows))
        else {
            return;
        };
        let row_order = sort.and_then(|(target, direction)| match target {
            TableSortColumn::Index => {
                let mut row_order: Vec<usize> = (0..rows).collect();
                if matches!(direction, crate::events::SortDirection::Desc) {
                    row_order.reverse();
                }
                Some(row_order)
            }
            TableSortColumn::Data(col) => {
                self.resources
                    .sorted_table_rows(resource_id.as_deref(), col, rows, direction)
            }
        });
        if let Some(state) = &mut self.widget_state {
            state.set_table_row_order(id, row_order);
        }
    }

    fn apply_release_resource(&mut self, id: &str) -> bool {
        self.resources.release(id)
    }

    fn set_scatter_points_packed(
        &mut self,
        id: &str,
        xyz: Vec<u8>,
        telemetry: Option<ScatterTelemetry>,
        colormap: String,
        data_format: ScatterPayloadFormat,
        fit: bool,
    ) -> Result<bool, DragonError> {
        if self.widget_kind(id) != Some(WidgetKind::Scatter3D) {
            return Ok(false);
        }
        let Some(runtime) = self.scatters.get_mut(id) else {
            return Ok(false);
        };
        let total_t0 = Instant::now();
        let queue_latency_ms = telemetry
            .as_ref()
            .map(|t| (now_epoch_ms() - t.enqueue_epoch_ms).max(0.0))
            .unwrap_or(0.0);

        if data_format == ScatterPayloadFormat::PointInstanceV1 {
            let telemetry_bounds = telemetry.as_ref().and_then(|t| t.bounds);
            let bounds_t0 = Instant::now();
            let maybe_bounds = if let Some((min, max)) = telemetry_bounds {
                Some((glam::Vec3::from_array(min), glam::Vec3::from_array(max)))
            } else {
                match bounds_from_scatter_point_instances_v1(&xyz) {
                    Ok(bounds) => bounds,
                    Err(e) => {
                        let msg = e.to_string();
                        eprintln!("DragonGUI: {msg}");
                        runtime.payload_status = ScatterPayloadStatus::DecodeError(msg.clone());
                        return Err(DragonError::Runtime(msg));
                    }
                }
            };
            let bounds_ms = if telemetry_bounds.is_some() {
                0.0
            } else {
                bounds_t0.elapsed().as_secs_f64() * 1000.0
            };
            let point_count = xyz.len() / std::mem::size_of::<PointInstance>();
            if maybe_bounds.is_none() && point_count > 0 {
                runtime.payload_format = data_format;
                runtime.points.clear();
                runtime.primary_compact_xyz.clear();
                runtime.primary_pick_cache = None;
                runtime.payload_status = ScatterPayloadStatus::AllNonFinite;
                runtime.primary_hover_meta = Vec::new();
                runtime.primary_hover_columns = Vec::new();
                let cleared_hover_label = runtime.widget.hover_label.take().is_some();
                runtime.data_min = glam::Vec3::ZERO;
                runtime.data_max = glam::Vec3::ZERO;
                let upload_timings = runtime.widget.set_points(&self.device, &self.queue, &[]);
                let grid_t0 = Instant::now();
                runtime.widget.refresh_grid(
                    glam::Vec3::ZERO,
                    glam::Vec3::ZERO,
                    &self.device,
                    &self.queue,
                );
                let grid_ms = grid_t0.elapsed().as_secs_f64() * 1000.0;
                let overlay_t0 = Instant::now();
                let overlay_ms = if cleared_hover_label {
                    runtime.widget.refresh_overlays(&self.device, &self.queue);
                    overlay_t0.elapsed().as_secs_f64() * 1000.0
                } else {
                    0.0
                };
                let pack_ms = telemetry.as_ref().map(|t| t.pack_ms).unwrap_or(0.0);
                let reported_payload_bytes = telemetry
                    .as_ref()
                    .map(|t| t.payload_bytes)
                    .unwrap_or(xyz.len());
                runtime.metrics = ScatterMetrics {
                    updates: runtime.metrics.updates + 1,
                    last_point_count: 0,
                    last_payload_bytes: reported_payload_bytes,
                    last_pack_ms: pack_ms,
                    last_queue_latency_ms: queue_latency_ms,
                    last_decode_ms: 0.0,
                    last_bounds_ms: bounds_ms,
                    last_upload_ms: upload_timings.primary_ms
                        + upload_timings.lod_ms
                        + grid_ms
                        + overlay_ms,
                    last_primary_upload_ms: upload_timings.primary_ms,
                    last_lod_ms: upload_timings.lod_ms,
                    last_grid_ms: grid_ms,
                    last_overlay_ms: overlay_ms,
                    last_total_native_ms: total_t0.elapsed().as_secs_f64() * 1000.0,
                    last_render_encode_ms: runtime.metrics.last_render_encode_ms,
                    last_render_redraw_ms: runtime.metrics.last_render_redraw_ms,
                    last_render_composite_ms: runtime.metrics.last_render_composite_ms,
                    last_render_cache_hit: runtime.metrics.last_render_cache_hit,
                    ..runtime.metrics.clone()
                };
                return Ok(true);
            }
            if let Some(upload_timings) =
                runtime
                    .widget
                    .set_point_instances_raw(&self.device, &self.queue, &xyz)
            {
                let (data_min, data_max) =
                    maybe_bounds.unwrap_or((glam::Vec3::ZERO, glam::Vec3::ZERO));
                runtime.payload_format = data_format;
                runtime.points.clear();
                runtime.primary_compact_xyz.clear();
                runtime.primary_pick_cache = None;
                runtime.primary_hover_meta = Vec::new();
                runtime.primary_hover_columns = Vec::new();
                let cleared_hover_label = runtime.widget.hover_label.take().is_some();
                runtime.data_min = data_min;
                runtime.data_max = data_max;
                runtime.payload_status = ScatterPayloadStatus::Ok;

                let mut camera_fitted = false;
                if (fit || !runtime.fitted_once)
                    && point_count > 0
                    && runtime.widget.has_visible_viewport()
                {
                    runtime
                        .widget
                        .fit_to_bounds(data_min, data_max, &self.queue);
                    runtime.fitted_once = true;
                    camera_fitted = true;
                } else if fit {
                    runtime.fitted_once = false;
                }
                let grid_t0 = Instant::now();
                runtime
                    .widget
                    .refresh_grid(data_min, data_max, &self.device, &self.queue);
                let grid_ms = grid_t0.elapsed().as_secs_f64() * 1000.0;
                let overlay_t0 = Instant::now();
                let overlay_ms = if camera_fitted || cleared_hover_label {
                    runtime.widget.refresh_overlays(&self.device, &self.queue);
                    overlay_t0.elapsed().as_secs_f64() * 1000.0
                } else {
                    0.0
                };

                let pack_ms = telemetry.as_ref().map(|t| t.pack_ms).unwrap_or(0.0);
                let reported_point_count = telemetry
                    .as_ref()
                    .map(|t| t.point_count)
                    .unwrap_or(point_count);
                let reported_payload_bytes = telemetry
                    .as_ref()
                    .map(|t| t.payload_bytes)
                    .unwrap_or(xyz.len());
                runtime.metrics = ScatterMetrics {
                    updates: runtime.metrics.updates + 1,
                    last_point_count: reported_point_count,
                    last_payload_bytes: reported_payload_bytes,
                    last_pack_ms: pack_ms,
                    last_queue_latency_ms: queue_latency_ms,
                    last_decode_ms: 0.0,
                    last_bounds_ms: bounds_ms,
                    last_upload_ms: upload_timings.primary_ms
                        + upload_timings.lod_ms
                        + grid_ms
                        + overlay_ms,
                    last_primary_upload_ms: upload_timings.primary_ms,
                    last_lod_ms: upload_timings.lod_ms,
                    last_grid_ms: grid_ms,
                    last_overlay_ms: overlay_ms,
                    last_total_native_ms: total_t0.elapsed().as_secs_f64() * 1000.0,
                    last_render_encode_ms: runtime.metrics.last_render_encode_ms,
                    last_render_redraw_ms: runtime.metrics.last_render_redraw_ms,
                    last_render_composite_ms: runtime.metrics.last_render_composite_ms,
                    last_render_cache_hit: runtime.metrics.last_render_cache_hit,
                    ..runtime.metrics.clone()
                };
                return Ok(true);
            }
        }

        if data_format == ScatterPayloadFormat::XyzF32V0 {
            let point_count = xyz.len() / 12;
            let telemetry_bounds = telemetry
                .as_ref()
                .and_then(|t| t.bounds)
                .map(|(min, max)| (glam::Vec3::from_array(min), glam::Vec3::from_array(max)));
            if point_count == 0 || telemetry_bounds.is_some() {
                let (data_min, data_max) =
                    telemetry_bounds.unwrap_or((glam::Vec3::ZERO, glam::Vec3::ZERO));
                let effective_colormap = if runtime.widget.chrome.scalar_bar.visible {
                    runtime.widget.chrome.scalar_bar.colormap.clone()
                } else {
                    colormap.clone()
                };
                if let Some(upload_timings) = runtime.widget.set_xyz_points_raw(
                    &self.device,
                    &self.queue,
                    &xyz,
                    data_min,
                    data_max,
                    &effective_colormap,
                ) {
                    let payload_bytes = xyz.len();
                    runtime.payload_format = data_format;
                    runtime.points.clear();
                    runtime.primary_compact_xyz = xyz;
                    runtime.primary_compact_colormap = effective_colormap;
                    runtime.primary_pick_cache = None;
                    runtime.primary_hover_meta = Vec::new();
                    runtime.primary_hover_columns = Vec::new();
                    let cleared_hover_label = runtime.widget.hover_label.take().is_some();
                    runtime.data_min = data_min;
                    runtime.data_max = data_max;
                    runtime.payload_status = ScatterPayloadStatus::Ok;

                    let mut camera_fitted = false;
                    if (fit || !runtime.fitted_once)
                        && point_count > 0
                        && runtime.widget.has_visible_viewport()
                    {
                        runtime
                            .widget
                            .fit_to_bounds(data_min, data_max, &self.queue);
                        runtime.fitted_once = true;
                        camera_fitted = true;
                    } else if fit {
                        runtime.fitted_once = false;
                    }
                    let grid_t0 = Instant::now();
                    runtime
                        .widget
                        .refresh_grid(data_min, data_max, &self.device, &self.queue);
                    let grid_ms = grid_t0.elapsed().as_secs_f64() * 1000.0;
                    let overlay_t0 = Instant::now();
                    let overlay_ms = if camera_fitted || cleared_hover_label {
                        runtime.widget.refresh_overlays(&self.device, &self.queue);
                        overlay_t0.elapsed().as_secs_f64() * 1000.0
                    } else {
                        0.0
                    };

                    let pack_ms = telemetry.as_ref().map(|t| t.pack_ms).unwrap_or(0.0);
                    let reported_point_count = telemetry
                        .as_ref()
                        .map(|t| t.point_count)
                        .unwrap_or(point_count);
                    let reported_payload_bytes = telemetry
                        .as_ref()
                        .map(|t| t.payload_bytes)
                        .unwrap_or(payload_bytes);
                    runtime.metrics = ScatterMetrics {
                        updates: runtime.metrics.updates + 1,
                        last_point_count: reported_point_count,
                        last_payload_bytes: reported_payload_bytes,
                        last_pack_ms: pack_ms,
                        last_queue_latency_ms: queue_latency_ms,
                        last_decode_ms: 0.0,
                        last_bounds_ms: 0.0,
                        last_upload_ms: upload_timings.primary_ms
                            + upload_timings.lod_ms
                            + grid_ms
                            + overlay_ms,
                        last_primary_upload_ms: upload_timings.primary_ms,
                        last_lod_ms: upload_timings.lod_ms,
                        last_grid_ms: grid_ms,
                        last_overlay_ms: overlay_ms,
                        last_total_native_ms: total_t0.elapsed().as_secs_f64() * 1000.0,
                        last_render_encode_ms: runtime.metrics.last_render_encode_ms,
                        last_render_redraw_ms: runtime.metrics.last_render_redraw_ms,
                        last_render_composite_ms: runtime.metrics.last_render_composite_ms,
                        last_render_cache_hit: runtime.metrics.last_render_cache_hit,
                        ..runtime.metrics.clone()
                    };
                    return Ok(true);
                }
            }
        }

        let decode_t0 = Instant::now();
        let mut decoded = std::mem::take(&mut runtime.points);
        let result = match data_format {
            ScatterPayloadFormat::XyzF32V0 => {
                let telemetry_bounds = telemetry
                    .as_ref()
                    .and_then(|t| t.bounds)
                    .map(|(min, max)| (glam::Vec3::from_array(min), glam::Vec3::from_array(max)));
                let effective_colormap = if runtime.widget.chrome.scalar_bar.visible {
                    runtime.widget.chrome.scalar_bar.colormap.as_str()
                } else {
                    colormap.as_str()
                };
                decode_scatter_points_bytes_into_colormap_with_bounds(
                    &xyz,
                    &mut decoded,
                    effective_colormap,
                    telemetry_bounds,
                )
            }
            ScatterPayloadFormat::PointInstanceV1 => decode_scatter_points_v1(&xyz, &mut decoded),
        };
        let maybe_bounds = match result {
            Ok(bounds) => bounds,
            Err(e) => {
                runtime.points = decoded;
                let msg = e.to_string();
                eprintln!("DragonGUI: {msg}");
                runtime.payload_status = ScatterPayloadStatus::DecodeError(msg.clone());
                // Do not mutate runtime.points or payload_format — preserve last valid state.
                return Err(DragonError::Runtime(msg));
            }
        };
        let decode_ms = decode_t0.elapsed().as_secs_f64() * 1000.0;
        let bounds_ms = 0.0;

        if maybe_bounds.is_none() && !decoded.is_empty() {
            runtime.payload_format = data_format;
            decoded.clear();
            runtime.points = decoded;
            runtime.primary_compact_xyz.clear();
            runtime.primary_pick_cache = None;
            runtime.payload_status = ScatterPayloadStatus::AllNonFinite;
            runtime.primary_hover_meta = Vec::new();
            runtime.primary_hover_columns = Vec::new();
            let cleared_hover_label = runtime.widget.hover_label.take().is_some();
            runtime.data_min = glam::Vec3::ZERO;
            runtime.data_max = glam::Vec3::ZERO;
            // Clear the GPU draw count so the old geometry is not rendered.
            let upload_timings = runtime.widget.set_points(&self.device, &self.queue, &[]);
            let grid_t0 = Instant::now();
            runtime.widget.refresh_grid(
                glam::Vec3::ZERO,
                glam::Vec3::ZERO,
                &self.device,
                &self.queue,
            );
            let grid_ms = grid_t0.elapsed().as_secs_f64() * 1000.0;
            let overlay_t0 = Instant::now();
            let overlay_ms = if cleared_hover_label {
                runtime.widget.refresh_overlays(&self.device, &self.queue);
                overlay_t0.elapsed().as_secs_f64() * 1000.0
            } else {
                0.0
            };
            let pack_ms = telemetry.as_ref().map(|t| t.pack_ms).unwrap_or(0.0);
            let reported_payload_bytes = telemetry
                .as_ref()
                .map(|t| t.payload_bytes)
                .unwrap_or(xyz.len());
            runtime.metrics = ScatterMetrics {
                updates: runtime.metrics.updates + 1,
                last_point_count: 0,
                last_payload_bytes: reported_payload_bytes,
                last_pack_ms: pack_ms,
                last_queue_latency_ms: queue_latency_ms,
                last_decode_ms: decode_ms,
                last_bounds_ms: bounds_ms,
                last_upload_ms: upload_timings.primary_ms
                    + upload_timings.lod_ms
                    + grid_ms
                    + overlay_ms,
                last_primary_upload_ms: upload_timings.primary_ms,
                last_lod_ms: upload_timings.lod_ms,
                last_grid_ms: grid_ms,
                last_overlay_ms: overlay_ms,
                last_total_native_ms: total_t0.elapsed().as_secs_f64() * 1000.0,
                last_render_encode_ms: runtime.metrics.last_render_encode_ms,
                last_render_redraw_ms: runtime.metrics.last_render_redraw_ms,
                last_render_composite_ms: runtime.metrics.last_render_composite_ms,
                last_render_cache_hit: runtime.metrics.last_render_cache_hit,
                ..runtime.metrics.clone()
            };
            return Ok(true);
        }
        let (data_min, data_max) = maybe_bounds.unwrap_or((glam::Vec3::ZERO, glam::Vec3::ZERO));
        runtime.payload_format = data_format;
        runtime.points = decoded;
        if data_format == ScatterPayloadFormat::XyzF32V0 {
            runtime.primary_compact_xyz = xyz.clone();
            runtime.primary_compact_colormap = if runtime.widget.chrome.scalar_bar.visible {
                runtime.widget.chrome.scalar_bar.colormap.clone()
            } else {
                colormap.clone()
            };
        } else {
            runtime.primary_compact_xyz.clear();
        }
        runtime.primary_pick_cache = None;
        runtime.primary_hover_meta = Vec::new();
        runtime.primary_hover_columns = Vec::new();
        let cleared_hover_label = runtime.widget.hover_label.take().is_some();
        runtime.data_min = data_min;
        runtime.data_max = data_max;
        runtime.payload_status = ScatterPayloadStatus::Ok;

        let upload_t0 = Instant::now();
        let upload_timings = runtime
            .widget
            .set_points(&self.device, &self.queue, &runtime.points);
        // Fit on first visible data load, or when the caller declares this
        // payload replaces the scene with a different coordinate frame.
        // Preserve camera for ordinary live updates.
        //
        // Startup resource uploads can arrive while a scatter is hidden inside
        // an inactive page. Hidden scatters have a zero-sized layout rect, and
        // fitting against that aspect ratio pushes the camera thousands of
        // units away. Leave `fitted_once` false so the next visible layout pass
        // can fit with the real viewport dimensions.
        let mut camera_fitted = false;
        if (fit || !runtime.fitted_once)
            && !runtime.points.is_empty()
            && runtime.widget.has_visible_viewport()
        {
            runtime
                .widget
                .fit_to_bounds(data_min, data_max, &self.queue);
            runtime.fitted_once = true;
            camera_fitted = true;
        } else if fit {
            runtime.fitted_once = false;
        }
        let grid_t0 = Instant::now();
        runtime
            .widget
            .refresh_grid(data_min, data_max, &self.device, &self.queue);
        let grid_ms = grid_t0.elapsed().as_secs_f64() * 1000.0;
        let overlay_t0 = Instant::now();
        let overlay_ms = if camera_fitted || cleared_hover_label {
            runtime.widget.refresh_overlays(&self.device, &self.queue);
            overlay_t0.elapsed().as_secs_f64() * 1000.0
        } else {
            0.0
        };
        let upload_ms = upload_t0.elapsed().as_secs_f64() * 1000.0;

        let point_count = runtime.points.len();
        let payload_bytes = xyz.len();
        let pack_ms = telemetry.as_ref().map(|t| t.pack_ms).unwrap_or(0.0);
        let reported_point_count = telemetry
            .as_ref()
            .map(|t| t.point_count)
            .unwrap_or(point_count);
        let reported_payload_bytes = telemetry
            .as_ref()
            .map(|t| t.payload_bytes)
            .unwrap_or(payload_bytes);
        runtime.metrics = ScatterMetrics {
            updates: runtime.metrics.updates + 1,
            last_point_count: reported_point_count,
            last_payload_bytes: reported_payload_bytes,
            last_pack_ms: pack_ms,
            last_queue_latency_ms: queue_latency_ms,
            last_decode_ms: decode_ms,
            last_bounds_ms: bounds_ms,
            last_upload_ms: upload_ms,
            last_primary_upload_ms: upload_timings.primary_ms,
            last_lod_ms: upload_timings.lod_ms,
            last_grid_ms: grid_ms,
            last_overlay_ms: overlay_ms,
            last_total_native_ms: total_t0.elapsed().as_secs_f64() * 1000.0,
            last_render_encode_ms: runtime.metrics.last_render_encode_ms,
            last_render_redraw_ms: runtime.metrics.last_render_redraw_ms,
            last_render_composite_ms: runtime.metrics.last_render_composite_ms,
            last_render_cache_hit: runtime.metrics.last_render_cache_hit,
            ..runtime.metrics.clone()
        };
        Ok(true)
    }

    fn sync_scatter_style_overrides(&mut self) {
        let Some(tree) = self.widget_tree.as_ref() else {
            return;
        };
        let overrides: Vec<(
            String,
            Option<f32>,
            Option<String>,
            Option<scatter::ScatterChromeState>,
        )> = self
            .visible_scatter_order
            .iter()
            .map(|id| {
                let node = find_node(tree, id);
                (
                    id.clone(),
                    node.and_then(|node| node.style.widget.scatter_point_size)
                        .map(|size| size * self.scale_factor),
                    node.and_then(|node| node.style.widget.scatter_point_style.clone()),
                    node.map(scatter_chrome_from_node),
                )
            })
            .collect();
        for (id, point_size, point_style, chrome) in overrides {
            let Some(runtime) = self.scatters.get_mut(&id) else {
                continue;
            };
            let old_point_size = runtime.widget.point_size_override;
            runtime
                .widget
                .set_point_size_override(point_size, &self.queue);
            if runtime.widget.point_size_override.to_bits() != old_point_size.to_bits() {
                runtime.primary_pick_cache = None;
                for actor in runtime.widget.extra_actors.values_mut() {
                    actor.pick_cache = None;
                }
            }
            runtime
                .widget
                .set_point_style(point_style.as_deref(), &self.queue);
            if let Some(chrome) = chrome {
                if runtime.widget.chrome != chrome {
                    runtime.widget.set_chrome(chrome);
                    let (data_min, data_max) = runtime.merged_bounds();
                    runtime
                        .widget
                        .refresh_grid(data_min, data_max, &self.device, &self.queue);
                    runtime.widget.refresh_overlays(&self.device, &self.queue);
                }
            }
        }
    }

    fn begin_deferred_rebuilds(&mut self) {
        debug_assert!(self.deferred_dirty.is_none());
        self.deferred_text_targets.clear();
        self.deferred_visual_targets.clear();
        self.deferred_table_text_targets.clear();
        self.deferred_text_requires_full = false;
        self.deferred_visual_requires_full = false;
        self.deferred_overlay_text = false;
        self.defer_rebuilds = true;
    }

    fn flush_deferred_rebuilds(&mut self) -> bool {
        self.defer_rebuilds = false;
        let mut text_targets = std::mem::take(&mut self.deferred_text_targets);
        let visual_targets = std::mem::take(&mut self.deferred_visual_targets);
        merge_deferred_visual_targets(&mut text_targets, visual_targets);
        let table_text_targets = std::mem::take(&mut self.deferred_table_text_targets);
        let text_requires_full = std::mem::take(&mut self.deferred_text_requires_full);
        let visual_requires_full = std::mem::take(&mut self.deferred_visual_requires_full);
        let overlay_text = std::mem::take(&mut self.deferred_overlay_text);
        let Some(dirty) = self.deferred_dirty.take() else {
            self.deferred_scatter_style_sync = false;
            return false;
        };
        let scatter_style_sync = std::mem::take(&mut self.deferred_scatter_style_sync);
        if scatter_style_sync && matches!(dirty, Dirty::Text) {
            self.sync_scatter_style_overrides();
        }
        if can_use_targeted_deferred_rebuild(
            dirty,
            text_requires_full,
            visual_requires_full,
            !text_targets.is_empty() || !table_text_targets.is_empty() || overlay_text,
        ) {
            self.command_text_rebuild_stats.attempted_batches = self
                .command_text_rebuild_stats
                .attempted_batches
                .saturating_add(1);
            let roots = if text_targets.is_empty() {
                Some(HashSet::new())
            } else {
                self.widget_tree
                    .as_ref()
                    .and_then(|tree| normalize_targeted_text_roots(tree, &text_targets))
            };
            if let Some(roots) = roots.filter(|roots| {
                roots.len() + table_text_targets.len() <= MAX_TARGETED_TEXT_ROOTS_PER_BATCH
            }) {
                self.dirty_rebuild_stats.record_execution(Dirty::Text);
                if self.rebuild_targeted_visuals(&roots, &table_text_targets, overlay_text) {
                    self.command_text_rebuild_stats.completed_batches = self
                        .command_text_rebuild_stats
                        .completed_batches
                        .saturating_add(1);
                    self.command_text_rebuild_stats.rebuilt_roots = self
                        .command_text_rebuild_stats
                        .rebuilt_roots
                        .saturating_add((roots.len() + table_text_targets.len()) as u64);
                    if overlay_text {
                        self.command_text_rebuild_stats.overlay_batches = self
                            .command_text_rebuild_stats
                            .overlay_batches
                            .saturating_add(1);
                    }
                    return true;
                }
                self.command_text_rebuild_stats.fallback_batches = self
                    .command_text_rebuild_stats
                    .fallback_batches
                    .saturating_add(1);
                self.rebuild_visuals();
                return true;
            }
            self.command_text_rebuild_stats.fallback_batches = self
                .command_text_rebuild_stats
                .fallback_batches
                .saturating_add(1);
        }
        self.execute_rebuild_for_dirty(dirty);
        true
    }

    fn rebuild_for_dirty(&mut self, dirty: Dirty) {
        self.rebuild_for_widget_dirty(dirty, None);
    }

    fn rebuild_for_overlay_text(&mut self) {
        self.dirty_rebuild_stats.record_request(Dirty::Text);
        self.command_text_rebuild_stats.overlay_requests = self
            .command_text_rebuild_stats
            .overlay_requests
            .saturating_add(1);
        if self.defer_rebuilds {
            self.deferred_overlay_text = true;
            if self.deferred_dirty.is_some() {
                self.dirty_rebuild_stats.deferred_merges =
                    self.dirty_rebuild_stats.deferred_merges.saturating_add(1);
            }
            self.deferred_dirty = Some(merge_dirty(self.deferred_dirty, Dirty::Text));
            return;
        }
        self.dirty_rebuild_stats.record_execution(Dirty::Text);
        if !self.rebuild_targeted_visuals(&HashSet::new(), &HashSet::new(), true) {
            self.rebuild_visuals();
        }
    }

    fn rebuild_for_table_text(&mut self, widget_id: &str) {
        self.dirty_rebuild_stats.record_request(Dirty::Text);
        self.command_text_rebuild_stats.targeted_requests = self
            .command_text_rebuild_stats
            .targeted_requests
            .saturating_add(1);
        if self.defer_rebuilds {
            self.deferred_table_text_targets
                .insert(widget_id.to_string());
            if self.deferred_dirty.is_some() {
                self.dirty_rebuild_stats.deferred_merges =
                    self.dirty_rebuild_stats.deferred_merges.saturating_add(1);
            }
            self.deferred_dirty = Some(merge_dirty(self.deferred_dirty, Dirty::Text));
            return;
        }
        self.dirty_rebuild_stats.record_execution(Dirty::Text);
        let table_ids = HashSet::from([widget_id.to_string()]);
        if !self.rebuild_targeted_visuals(&HashSet::new(), &table_ids, false) {
            self.rebuild_visuals();
        }
    }

    fn rebuild_for_widget_dirty(&mut self, dirty: Dirty, widget_id: Option<&str>) {
        self.dirty_rebuild_stats.record_request(dirty);
        if self.defer_rebuilds {
            if matches!(dirty, Dirty::Text) {
                if let Some(widget_id) = widget_id {
                    self.deferred_text_targets.insert(widget_id.to_string());
                    self.command_text_rebuild_stats.targeted_requests = self
                        .command_text_rebuild_stats
                        .targeted_requests
                        .saturating_add(1);
                } else {
                    self.deferred_text_requires_full = true;
                    self.command_text_rebuild_stats.global_requests = self
                        .command_text_rebuild_stats
                        .global_requests
                        .saturating_add(1);
                }
            }
            if matches!(dirty, Dirty::Visual) {
                self.deferred_scatter_style_sync = true;
                if let Some(widget_id) = widget_id {
                    self.deferred_visual_targets.insert(widget_id.to_string());
                } else {
                    self.deferred_visual_requires_full = true;
                }
            }
            if self.deferred_dirty.is_some() {
                self.dirty_rebuild_stats.deferred_merges =
                    self.dirty_rebuild_stats.deferred_merges.saturating_add(1);
            }
            self.deferred_dirty = Some(merge_dirty(self.deferred_dirty, dirty));
            return;
        }
        self.execute_rebuild_for_dirty(dirty);
    }

    fn execute_rebuild_for_dirty(&mut self, dirty: Dirty) {
        self.dirty_rebuild_stats.record_execution(dirty);
        if matches!(dirty, Dirty::Layout | Dirty::Full) {
            self.cancel_hover_transitions();
        }
        if self.styles_dirty && !matches!(dirty, Dirty::Layout | Dirty::Full) {
            self.reapply_stylesheets();
        }
        match dirty {
            Dirty::Layout | Dirty::Full => self.apply_layout(),
            Dirty::Text => self.rebuild_visuals(),
            Dirty::Visual => {
                self.sync_scatter_style_overrides();
                self.rebuild_primitives();
            }
            Dirty::GpuData => {}
        }
    }

    fn reapply_stylesheets(&mut self) {
        self.cancel_hover_transitions();
        self.mark_styles_dirty();
        self.reapply_stylesheets_for_current_viewport();
    }

    fn set_stylesheet(
        &mut self,
        origin: StylesheetOrigin,
        id: Option<&str>,
        css: &str,
    ) -> Result<(), String> {
        match id {
            Some(id) => self.stylesheets.set_named_stylesheet(origin, id, css),
            None => self.stylesheets.set_stylesheet(origin, css),
        }
        .map_err(|error| error.to_string())?;
        self.mark_styles_dirty();
        self.rebuild_for_dirty(Dirty::Full);
        Ok(())
    }

    fn remove_stylesheet(&mut self, origin: StylesheetOrigin, id: &str) -> bool {
        if !self.stylesheets.remove_stylesheet(origin, id) {
            return false;
        }
        self.mark_styles_dirty();
        self.rebuild_for_dirty(Dirty::Full);
        true
    }

    fn set_theme(&mut self, theme: Theme) -> Dirty {
        let dirty = theme_change_dirty(&self.theme, &theme).unwrap_or(Dirty::Visual);
        self.theme = theme;
        self.stylesheets.install_framework_defaults(&self.theme);
        self.mark_styles_dirty();
        self.rebuild_for_dirty(dirty);
        dirty
    }

    fn set_icon_theme(
        &mut self,
        icon_theme: crate::icons::IconThemeRegistry,
    ) -> Result<bool, String> {
        if self.icon_theme == icon_theme {
            return Ok(false);
        }
        if let Some(tree) = &mut self.widget_tree {
            icon_theme.apply_to_tree(tree)?;
        }
        self.icon_theme = icon_theme;
        Ok(true)
    }

    fn clear_stylesheets(&mut self, origin: StylesheetOrigin) {
        self.stylesheets.clear(origin);
        self.mark_styles_dirty();
        self.rebuild_for_dirty(Dirty::Full);
    }

    fn show_toast(
        &mut self,
        id: String,
        message: String,
        level: ToastLevel,
        duration_ms: Option<u64>,
        opacity: Option<f32>,
        radius: Option<f32>,
        padding: Option<f32>,
        position: Option<ToastPosition>,
    ) {
        let existing_style = self.toasts.iter().find(|existing| existing.id == id);
        let toast = RuntimeToast {
            id,
            message,
            level,
            duration: duration_ms.map(Duration::from_millis),
            created: Instant::now(),
            opacity: opacity
                .or_else(|| existing_style.map(|toast| toast.opacity))
                .unwrap_or(1.0)
                .clamp(0.0, 1.0),
            radius: radius.or_else(|| existing_style.and_then(|toast| toast.radius)),
            padding: padding.or_else(|| existing_style.and_then(|toast| toast.padding)),
            position: position
                .or_else(|| existing_style.map(|toast| toast.position))
                .unwrap_or_default(),
        };
        if let Some(existing) = self
            .toasts
            .iter_mut()
            .find(|existing| existing.id == toast.id)
        {
            *existing = toast;
        } else {
            self.toasts.push(toast);
        }
        self.refresh_toast_overlays();
    }

    fn dismiss_toast(&mut self, id: &str) -> bool {
        let before = self.toasts.len();
        self.toasts.retain(|toast| toast.id != id);
        let changed = self.toasts.len() != before;
        if changed {
            self.refresh_toast_overlays();
        }
        changed
    }

    fn expire_toasts(&mut self) -> bool {
        let now = Instant::now();
        let before = self.toasts.len();
        self.toasts.retain(|toast| !toast.is_expired(now));
        let changed = self.toasts.len() != before;
        if changed {
            self.refresh_toast_overlays();
        }
        changed
    }

    fn next_toast_deadline(&self) -> Option<Instant> {
        self.toasts
            .iter()
            .filter_map(RuntimeToast::expires_at)
            .min()
    }

    fn refresh_toast_overlays(&mut self) {
        self.toast_overlays = self.toasts.iter().map(RuntimeToast::overlay).collect();
    }

    fn toast_snapshot(&self) -> Value {
        let now = Instant::now();
        json!({
            "count": self.toasts.len(),
            "items": self.toasts.iter().map(|toast| {
                json!({
                    "id": toast.id.as_str(),
                    "message": toast.message.as_str(),
                    "level": toast.level.as_str(),
                    "duration_ms": toast.duration.map(|duration| duration.as_millis() as u64),
                    "age_ms": now.saturating_duration_since(toast.created).as_millis() as u64,
                    "opacity": toast.opacity,
                    "radius": toast.radius,
                    "padding": toast.padding,
                    "position": toast.position.as_str(),
                })
            }).collect::<Vec<_>>(),
        })
    }

